            false,
            ["elements", "children", "void-elements-take-no-children", "when-a-name-collides", "decorations", "handlers", "the-class-channel", "where-a-decoration-may-go", "next"],
            "<p>BlazorCodeFirst mirrors HTML directly: every element you write in a <code>Body</code> expression names the\nelement it produces. There is no second set of widget names to learn on top of HTML, and no runtime\nUI tree.</p>\n<h2 id=\"elements\">Elements<a href=\"#elements\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>An HTML element is a helper, named by its tag with only the first letter uppercased — <code>Figcaption</code>,\nnot <code>FigCaption</code>, likewise <code>Colgroup</code> and <code>Textarea</code>. Attributes chain onto it, children go in\nbrackets.</p>\n<!-- bcf-figure: ElementNames -->\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Figure[\n        Img.Src(<span class=\"string\">&quot;/diagram.png&quot;</span>).Alt(<span class=\"string\">&quot;Architecture&quot;</span>),\n        Figcaption[<span class=\"string\">&quot;The compilation pipeline&quot;</span>]];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">figure</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">img</span> <span class=\"htmlAttributeName\">src</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;/diagram.png&quot;</span> <span class=\"htmlAttributeName\">alt</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;Architecture&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">figcaption</span><span class=\"htmlTagDelimiter\">&gt;</span>The compilation pipeline<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">figcaption</span><span class=\"htmlTagDelimiter\">&gt;</span>\n<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">figure</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>A dedicated helper exists for every element the HTML Living Standard lists as conforming.</p>\n<p><code>Element</code> covers everything else. Two things use it. The first is custom elements and Web\nComponents, whose tag names are never a known helper. The second is the handful of standard elements\nno helper covers:</p>\n<ul>\n<li>the document and <code>&lt;head&gt;</code>-only elements: <code>html</code>, <code>head</code>, <code>body</code>, <code>title</code>, <code>base</code>, <code>meta</code>, <code>link</code></li>\n<li>raw-text elements: <code>script</code>, <code>style</code>, <code>noscript</code></li>\n<li>elements the render tree cannot give meaning to: <code>template</code>, <code>slot</code></li>\n<li><code>object</code>, whose name is ambiguous with the C# keyword</li>\n<li>the foreign elements <code>svg</code> and <code>math</code>, in full</li>\n</ul>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">const</span> <span class=\"keyword\">string</span> Widget = <span class=\"string\">&quot;my-widget&quot;</span>;\n\nElement(Widget).Attr(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;42&quot;</span>)        <span class=\"comment\">// custom element</span>\nElement(<span class=\"string\">&quot;svg&quot;</span>)[Element(<span class=\"string\">&quot;circle&quot;</span>)]          <span class=\"comment\">// foreign element</span>\nElement(_kind + <span class=\"string\">&quot;-widget&quot;</span>)                 <span class=\"comment\">// BCF3009: not a constant</span>\nElement(<span class=\"string\">&quot;my widget&quot;</span>)                       <span class=\"comment\">// BCF3009: not spelled like a tag name</span>\n</pre></div>\n<p>The tag has to be a compile-time constant spelled like a tag name, or\n<a href=\"/docs/diagnostics#bcf3009\">BCF3009</a> is reported.</p>\n<h2 id=\"children\">Children<a href=\"#children\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>A bare string converts to a text node, so there is no separate <code>Text()</code> construct. An element with\nno children drops the brackets entirely.</p>\n<!-- bcf-figure: MixedChildren -->\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        <span class=\"string\">&quot;plain text, then &quot;</span>,\n        A.Href(<span class=\"string\">&quot;/docs&quot;</span>)[<span class=\"string\">&quot;a link&quot;</span>],\n        Br,\n        Img.Src(<span class=\"string\">&quot;/logo.png&quot;</span>).Alt(<span class=\"string\">&quot;Logo&quot;</span>)];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>plain text, then <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">a</span> <span class=\"htmlAttributeName\">href</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;/docs&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>a link<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">a</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">br</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">img</span> <span class=\"htmlAttributeName\">src</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;/logo.png&quot;</span> <span class=\"htmlAttributeName\">alt</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;Logo&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>A Blazor <code>RenderFragment</code> sits in the child list like any other child:</p>\n<div class=\"csharp\"><pre>\n[Parameter] <span class=\"keyword\">public</span> RenderFragment? ChildContent { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div[<span class=\"string\">&quot;before&quot;</span>, ChildContent];\n</pre></div>\n<p>The generator has to see each child as its own expression to give it a sequence number. Writing the\nchildren as a nested collection literal is accepted, because C# expands it to the same call:</p>\n<div class=\"csharp\"><pre>\nDiv[[<span class=\"string\">&quot;a&quot;</span>, <span class=\"string\">&quot;b&quot;</span>]]     <span class=\"comment\">// same as Div[&quot;a&quot;, &quot;b&quot;], which is the form to prefer</span>\n</pre></div>\n<p>A child list the generator cannot read through reports\n<a href=\"/docs/diagnostics#bcf1003\">BCF1003</a>. Use <a href=\"/docs/control-flow#foreach-and-its-key\"><code>ForEach</code></a> for\nrepetition instead.</p>\n<h2 id=\"void-elements-take-no-children\">Void elements take no children<a href=\"#void-elements-take-no-children\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>The thirteen void elements of the HTML standard have no closing tag, so children written on one\nreport <a href=\"/docs/diagnostics#bcf3016\">BCF3016</a>:</p>\n<div class=\"csharp\"><pre>\nImg.Src(<span class=\"string\">&quot;/logo.png&quot;</span>)[<span class=\"string\">&quot;Logo&quot;</span>]     <span class=\"comment\">// BCF3016</span>\nElement(<span class=\"string\">&quot;img&quot;</span>)[<span class=\"string\">&quot;Logo&quot;</span>]           <span class=\"comment\">// BCF3016, same rule</span>\nImg.Src(<span class=\"string\">&quot;/logo.png&quot;</span>).Alt(<span class=\"string\">&quot;Logo&quot;</span>) <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>Configure a void element with decorations and put content beside it. This is the limit of what the\nsurface checks about HTML, and the limit is deliberate: <code>Table[Div[&quot;x&quot;]]</code> also renders differently\nafter hydration, and it is accepted, along with attributes an element does not define\n(<code>Div.Href(&quot;/x&quot;)</code>). See <code>DESIGN.md</code> §4.1 for the full rationale.</p>\n<h2 id=\"when-a-name-collides\">When a name collides<a href=\"#when-a-name-collides\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>using static BlazorCodeFirst.Html;</code> imports every conforming HTML element name, and a declaration\nof your own wins simple-name lookup over an imported one. Blazor parameters named <code>Label</code>, <code>Data</code>,\n<code>Summary</code> or <code>Source</code> are ordinary, so this happens:</p>\n<div class=\"csharp\"><pre>\n[Parameter] <span class=\"keyword\">public</span> <span class=\"keyword\">string</span> Data { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\nDiv[Data[<span class=\"string\">&quot;Heading&quot;</span>]]                          <span class=\"comment\">// BCF3027</span>\nDiv[Html.Data[<span class=\"string\">&quot;Heading&quot;</span>]]                     <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>A type, a namespace, or a method of yours takes the name the same way, and each is\n<a href=\"/docs/diagnostics#bcf3027\">BCF3027</a>, naming what it found.</p>\n<h2 id=\"decorations\">Decorations<a href=\"#decorations\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Decorations are chained onto the element they belong to, before its children, the way HTML writes\nattributes inside the tag. They collapse into the owning element's attributes rather than\nintroducing wrapper nodes, and <code>class</code> folds: chaining <code>.Class</code> more than once merges the values\ninto a single attribute.</p>\n<!-- bcf-figure: ChainedDecorations -->\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Button\n        .Class(<span class=\"string\">&quot;btn&quot;</span>)\n        .Class(<span class=\"string\">&quot;btn-primary&quot;</span>)\n        .Title(<span class=\"string\">&quot;Save the current document&quot;</span>)[<span class=\"string\">&quot;Save&quot;</span>];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">button</span> <span class=\"htmlAttributeName\">class</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;btn btn-primary&quot;</span> <span class=\"htmlAttributeName\">title</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;Save the current document&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>Save<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">button</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>Available decorations are <code>.Class</code>, <code>.Id</code>, <code>.Href</code>, <code>.Src</code>, <code>.Alt</code>, <code>.Type</code>, <code>.Title</code>, <code>.Role</code>,\n<code>.OnClick</code>, and the general-purpose escape hatches <code>.Attr(name, value)</code> and <code>.On(eventName, handler)</code>.</p>\n<p><code>.On</code> takes the full attribute name including the <code>on</code> prefix (<code>.On(&quot;onmouseenter&quot;, …)</code>); nothing is\nprefixed for you, and a name without it reports <a href=\"/docs/diagnostics#bcf3019\">BCF3019</a>. The name given\nto <code>.Attr</code> or <code>.On</code> must be a non-empty compile-time constant\n(<a href=\"/docs/diagnostics#bcf3011\">BCF3011</a>).</p>\n<p><code>.Attr</code> takes a <code>string?</code> or a <code>bool</code>. A <code>bool</code> is Blazor's conditional attribute: <code>true</code> renders the\nattribute with an empty value, which is how HTML reads <code>disabled</code>, <code>checked</code> and <code>hidden</code> as set, and\n<code>false</code> leaves the attribute out entirely. Where the attribute is always present, write it bare, as HTML\ndoes — the <code>bool</code> is for the conditional case.</p>\n<div class=\"csharp\"><pre>\nInput.Type(<span class=\"string\">&quot;checkbox&quot;</span>).Attr(<span class=\"string\">&quot;checked&quot;</span>)                    <span class=\"comment\">// &lt;input type=&quot;checkbox&quot; checked&gt;</span>\nButton.Attr(<span class=\"string\">&quot;disabled&quot;</span>, _submitting)[<span class=\"string\">&quot;Save&quot;</span>]              <span class=\"comment\">// conditional</span>\n</pre></div>\n<p>A <code>null</code> string value leaves the attribute out too, so an attribute that carries a value only sometimes\nneeds no branch around the element:</p>\n<div class=\"csharp\"><pre>\nSpan.Attr(<span class=\"string\">&quot;title&quot;</span>, _hasTip ? _tip : <span class=\"keyword\">null</span>)[<span class=\"string\">&quot;Hover me&quot;</span>]\n</pre></div>\n<p><code>null</code> and <code>&quot;&quot;</code> are different values at every stage — frames, prerendered HTML, and a re-render — so\n<code>&quot;&quot;</code> gives you <code>title=&quot;&quot;</code> and <code>null</code> gives you no <code>title</code> at all. When a re-render turns a value null,\nBlazor removes the attribute from the element already in the DOM rather than replacing the element.\nEvery decoration that takes one value accepts <code>null</code> this way.</p>\n<p>There is deliberately no <code>object</code> overload. A value of any other type is formatted at render time\nunder the formatting thread's culture rather than the one your component ran under, so write it out\nyourself, where the culture is explicit:</p>\n<div class=\"csharp\"><pre>\nDiv.Attr(<span class=\"string\">&quot;tabindex&quot;</span>, index.ToString(CultureInfo.InvariantCulture))\n</pre></div><h3 id=\"handlers\">Handlers<a href=\"#handlers\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>A handler written as <code>Action</code> or <code>Func&lt;Task&gt;</code> receives nothing. To read the event, give the lambda\nparameter its type, and <code>.On</code> picks up the typed overload:</p>\n<div class=\"csharp\"><pre>\nInput.Type(<span class=\"string\">&quot;text&quot;</span>).Attr(<span class=\"string\">&quot;value&quot;</span>, _name)\n     .On(<span class=\"string\">&quot;oninput&quot;</span>, (ChangeEventArgs e) =&gt; _name = e.Value?.ToString() ?? <span class=\"string\">&quot;&quot;</span>)\n</pre></div>\n<p>Unlike Razor, the argument type is not inferred from the event name, so writing it on the parameter\nis what selects the overload. <code>ChangeEventArgs</code> lives in <code>Microsoft.AspNetCore.Components</code>;\n<code>MouseEventArgs</code>, <code>KeyboardEventArgs</code> and <code>FocusEventArgs</code> live in\n<code>Microsoft.AspNetCore.Components.Web</code>, which a Blazor app already references.</p>\n<p>The type is not inferred, but it is checked. Naming one the event does not deliver reports\n<a href=\"/docs/diagnostics#bcf3028\">BCF3028</a>, read from the same <code>[EventHandler]</code> metadata Razor uses. A base\nof the delivered type is accepted, because that is what the handler can actually receive:</p>\n<div class=\"csharp\"><pre>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (MouseEventArgs e) =&gt; Zoom(e.ClientX, e.ClientY))[<span class=\"string\">&quot;Zoom&quot;</span>]   <span class=\"comment\">// the delivered type</span>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (EventArgs e) =&gt; Save())[<span class=\"string\">&quot;Save&quot;</span>]                            <span class=\"comment\">// a base of it: fine</span>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (KeyboardEventArgs e) =&gt; Save())[<span class=\"string\">&quot;Save&quot;</span>]                    <span class=\"comment\">// BCF3028</span>\n</pre></div>\n<p>An event with no <code>[EventHandler]</code> registration has no mapping to check against, so a custom event you\nhave not registered is left alone. Registering one is the ordinary Blazor mechanism, and a\nregistration in your own project is read:</p>\n<div class=\"csharp\"><pre>\n[EventHandler(<span class=\"string\">&quot;onrate&quot;</span>, <span class=\"keyword\">typeof</span>(RatingEventArgs))]\n<span class=\"keyword\">public</span> <span class=\"keyword\">static</span> <span class=\"keyword\">class</span> AppEventHandlers;\n</pre></div>\n<p>An attribute out and an event back is the pair <a href=\"/docs/two-way-binding\"><code>.Bind</code></a> writes as one\ndecoration.</p>\n<h3 id=\"the-class-channel\">The class channel<a href=\"#the-class-channel\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Because that channel joins its values as text, <code>class</code> is the one name that takes a string and nothing\nelse. <code>.Attr(&quot;class&quot;, flag)</code> reports <a href=\"/docs/diagnostics#bcf3023\">BCF3023</a> — as does <code>.Attr(&quot;class&quot;)</code>,\nwhose bare spelling stands for a presence and so has no text to join either. Write a conditional class\nas a string, using <code>null</code> for the term you want gone:</p>\n<div class=\"csharp\"><pre>\nDiv.Class(<span class=\"string\">&quot;card&quot;</span>).Class(_selected ? <span class=\"string\">&quot;is-selected&quot;</span> : <span class=\"string\">&quot;&quot;</span>)\n</pre></div>\n<p>A <code>null</code> term drops out of the join, so an element carrying one class decoration loses the attribute\nentirely when the term is null. It still leaves the separator behind when there is another term to join\nagainst: <code>Div.Class(&quot;card&quot;).Class(_selected ? &quot;is-selected&quot; : null)</code> renders <code>class=&quot;card &quot;</code> while\n<code>_selected</code> is false, which the browser reads as the single class <code>card</code>.</p>\n<p>Every other attribute and event is a single binding, and binding one twice on the same element reports\n<a href=\"/docs/diagnostics#bcf3010\">BCF3010</a>. <code>style</code> is one of those others: write it as <code>.Attr(&quot;style&quot;, …)</code>.\n<code>.Bind(&quot;class&quot;, …)</code> is the third way to write the name and the one that does not fold, so an element\ncarrying both it and a <code>.Class</code> reports <a href=\"/docs/diagnostics#bcf3024\">BCF3024</a>.</p>\n<h3 id=\"where-a-decoration-may-go\">Where a decoration may go<a href=\"#where-a-decoration-may-go\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>A decoration must target a single element. Applying one to <code>If</code>, <code>ForEach</code>, <code>Fragment</code>, <code>Raw</code>, or a\ncomponent result reports <a href=\"/docs/diagnostics#bcf3008\">BCF3008</a>, because none of those opens an\nelement. Writing the chain after the children (<code>Div[&quot;text&quot;].Class(&quot;card&quot;)</code>) reports the same thing:\nthe brackets have already produced a <code>View</code>.</p>\n<p>A decoration also has to be one this library declares. A misspelled name (<code>Div.Clas(&quot;card&quot;)</code>), or an\nextension method of your own that takes an element and gives one back, reports\n<a href=\"/docs/diagnostics#bcf3026\">BCF3026</a>.</p>\n<h2 id=\"next\">Next<a href=\"#next\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Read <a href=\"/docs/control-flow\">control flow</a> for conditionals and lists, or go back to\n<a href=\"/docs/getting-started#installation\">getting started</a>.</p>\n"),
        new DocEntry(
            "control-flow",
            "Control Flow",
            "If and ForEach, the constructs that let the generator assign a compile-time sequence number to every position in a template.",
            50,
            "write",
            "en",
            false,
            ["if", "foreach-and-its-key", "declining-the-key", "spreading-a-select-into-children", "fragment", "raw", "next"],
            "<p>Conditionals and lists are expressed with dedicated constructs so the generator can assign\ncompile-time sequence numbers to every position in the template.</p>\n<h2 id=\"if\">If<a href=\"#if\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>If</code> takes a condition and a content thunk, with an optional else branch. A render is one state, so\nthe output below is the branch <code>_items.Length == 0</code> did not take:</p>\n<!-- bcf-figure: Conditional -->\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        If(_items.Length == <span class=\"number\">0</span>,\n            () =&gt; P[<span class=\"string\">&quot;Nothing here yet.&quot;</span>],\n            () =&gt; Span[$<span class=\"string\">&quot;{_items.Length} items&quot;</span>])];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">span</span><span class=\"htmlTagDelimiter\">&gt;</span>2 items<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">span</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>Mutually exclusive branches get disjoint sequence ranges, so switching branches never disturbs the\nsibling positions around them.</p>\n<h2 id=\"foreach-and-its-key\">ForEach and its key<a href=\"#foreach-and-its-key\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>ForEach</code> takes a key that identifies the item, not its position. The key is not written to the\nmarkup: it is a diffing instruction, not an attribute.</p>\n<!-- bcf-figure: KeyedList -->\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Ul[\n        ForEach(_items,\n            key: item =&gt; item.Id,\n            content: item =&gt; Li[item.Name])];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">ul</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">li</span><span class=\"htmlTagDelimiter\">&gt;</span>Alpha<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">li</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">li</span><span class=\"htmlTagDelimiter\">&gt;</span>Beta<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">li</span><span class=\"htmlTagDelimiter\">&gt;</span>\n<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">ul</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>Sequence numbers identify template positions; keys identify data instances. Passing an index as the\nkey makes the diff useless, because reordering the list makes Blazor reuse the wrong element state.</p>\n<p>A key that never references its item is reported. All three of these report\n<a href=\"/docs/diagnostics#bcf3002\">BCF3002</a>:</p>\n<ul>\n<li><code>key: _ =&gt; 0</code></li>\n<li>a key read from a counter outside the lambda</li>\n<li>in a nested loop, an inner key naming only the outer item</li>\n</ul>\n<div class=\"csharp\"><pre>\nForEach(_groups, key: g =&gt; g.Id, content: g =&gt;\n    Div[ForEach(g.Items, key: i =&gt; g.Id, content: i =&gt; Span[i.Name])])   <span class=\"comment\">// BCF3002 on the inner key</span>\n</pre></div>\n<p>It is a warning rather than an error and does not stop the component being emitted, because the list\nstill renders correctly and only diffs badly. The check is also deliberately conservative: it asks\nwhether the item was referenced, not whether the value identifies anything. A key derived from the\nitem but still position-like passes it. BCF3002 is a lower bound, not a guarantee.</p>\n<p>Both lambdas have to be inline expression lambdas, so wrap a call instead of naming it —\n<code>item =&gt; Row(item)</code> rather than <code>Row</code> (<a href=\"/docs/diagnostics#bcf3004\">BCF3004</a>). The content root must\nbe a single element or component (<a href=\"/docs/diagnostics#bcf3003\">BCF3003</a>), and it may not key itself as\nwell (<a href=\"/docs/diagnostics#bcf3032\">BCF3032</a>).</p>\n<h2 id=\"declining-the-key\">Declining the key<a href=\"#declining-the-key\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>The key parameter has no default value, so a list that has no identity to key on says so:</p>\n<div class=\"csharp\"><pre>\nUl[ForEach(_columns, key: <span class=\"keyword\">null</span>, content: c =&gt; Li[c.Header])]\n</pre></div>\n<p>That is the right spelling for a static menu, a fixed set of columns, or any projection that never\nreorders. The cost is the one BCF3002 warns about: the list diffs as an index-derived key does, so\nan insertion at the front rewrites every row and each row loses its local state. Because no <code>SetKey</code>\nis emitted, BCF3002 has nothing to check and BCF3003 no longer applies — a <code>Fragment</code>, a <code>Raw</code>,\nor a bare <code>If</code> may root the content.</p>\n<h2 id=\"spreading-a-select-into-children\">Spreading a <code>Select</code> into children<a href=\"#spreading-a-select-into-children\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>A child list can also take an ordinary projection — a <code>Select</code> — spread into it:</p>\n<div class=\"csharp\"><pre>\nUl[[.. _columns.Select(c =&gt; Li[c.Header])]]\n</pre></div>\n<p>That is a second spelling of the declined-key <code>ForEach</code> above, and it compiles to the same <code>foreach</code>.\nThe items land in the order they are spread, among any children written by hand:</p>\n<div class=\"csharp\"><pre>\nUl[[Li[<span class=\"string\">&quot;first&quot;</span>], .. _columns.Select(c =&gt; Li[c.Header]), Li[<span class=\"string\">&quot;last&quot;</span>]]]\n</pre></div>\n<p>Only <code>&lt;source&gt;.Select(&lt;inline expression lambda&gt;)</code> folds. Any other spread — a stored array of\n<code>View</code>, a method returning one — is not statically sequenceable children and reports\n<a href=\"/docs/diagnostics#bcf1003\">BCF1003</a>, as a stored <code>View</code> written as a single child already does.</p>\n<h2 id=\"fragment\">Fragment<a href=\"#fragment\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>Fragment</code> groups several children into one <code>View</code> without emitting a wrapper element:</p>\n<div class=\"csharp\"><pre>\nFragment(H2[<span class=\"string\">&quot;Title&quot;</span>], P[<span class=\"string\">&quot;Body&quot;</span>])\n</pre></div>\n<p>Because it opens no element it cannot be decorated (<a href=\"/docs/diagnostics#bcf3008\">BCF3008</a>) and cannot\nbe a <code>ForEach</code> content root (<a href=\"/docs/diagnostics#bcf3003\">BCF3003</a>).</p>\n<h2 id=\"raw\">Raw<a href=\"#raw\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>Raw</code> injects an HTML string verbatim, the <code>MarkupString</code> equivalent.</p>\n<div class=\"warning\" role=\"note\"><p><code>Raw</code> writes to the DOM without escaping. Pass it only content you produced yourself. A string that\ncame from a user, or back from another service, is parsed as HTML, and any script in it runs.</p>\n</div>\n<p>This page is rendered through it. Its Markdown is converted to HTML at build time, by a tool in this\nrepository, and the result is passed to <code>Raw</code>.</p>\n<div class=\"csharp\"><pre>\nArticle.Class(<span class=\"string\">&quot;prose&quot;</span>)[Raw(entry.Html)]\n</pre></div><h2 id=\"next\">Next<a href=\"#next\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>See <a href=\"/docs/components-and-reuse\">components and reuse</a> for calling one component from another, or\n<a href=\"/docs/elements-and-decorations#decorations\">elements and decorations</a> for the element vocabulary.</p>\n"),
        new DocEntry(
            "components-and-reuse",
            "Components and Reuse",
            "Calling one component from another, interoperating with Razor components in both directions, and what a ViewPart is for.",
            60,
            "write",
            "en",
            false,
            ["calling-another-blazorcodefirst-component", "passing-child-content", "generic-fragment-parameters", "calling-an-existing-razor-or-third-party-component", "cascading-a-value", "using-a-blazorcodefirst-component-from-razor", "splitting-without-a-component-viewpart", "naming-a-component-call", "wrapping-content", "next"],
            "<p>A component is the unit of reuse. One BlazorCodeFirst component calls another with\n<code>Component&lt;T&gt;()</code>, an existing Razor or third-party component is called exactly the same way, and a\n<code>.razor</code> file can call back into a BlazorCodeFirst component as an ordinary tag. <code>[ViewPart]</code> is\na different tool for a different job, covered at the end of this page.</p>\n<h2 id=\"calling-another-blazorcodefirst-component\">Calling another BlazorCodeFirst component<a href=\"#calling-another-blazorcodefirst-component\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>Component&lt;T&gt;()</code> places a component into the tree. Parameters bind through <code>.Param</code>, naming the\ntarget property with a lambda:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div.Class(<span class=\"string\">&quot;dashboard&quot;</span>)[\n        Component&lt;StatusBadge&gt;()\n            .Param(b =&gt; b.Status, _status)\n            .Param(b =&gt; b.Compact, <span class=\"keyword\">true</span>)];\n</pre></div>\n<p>The generator turns each <code>.Param</code> into a static parameter setter, emitted as\n<code>AddComponentParameter</code> calls. Nothing is reflected over and no expression tree is compiled at\nruntime, which is what keeps the path trimming- and AOT-safe.</p>\n<p>That is also why diagnostics constrain the shape. Every channel that names a parameter with a\nselector lambda is checked — <code>.Param</code>, <code>.Template</code>, and the component <code>.Bind</code> alike, not <code>.Param</code>\nalone:</p>\n<ul>\n<li>The selector must be a plain property selection (<a href=\"/docs/diagnostics#bcf3005\">BCF3005</a>).</li>\n<li>The target must be a settable <code>[Parameter]</code> property (<a href=\"/docs/diagnostics#bcf3006\">BCF3006</a>).</li>\n<li>Each property is bound at most once per chain, counting every channel\n(<a href=\"/docs/diagnostics#bcf3007\">BCF3007</a>).</li>\n</ul>\n<h2 id=\"passing-child-content\">Passing child content<a href=\"#passing-child-content\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Nested children bind to <code>ChildContent</code>, mirroring Razor's rule that nested content becomes\n<code>ChildContent</code> and nothing else:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;Card&gt;()[\n        H2[<span class=\"string\">&quot;Heading&quot;</span>],\n        P[<span class=\"string\">&quot;Body text&quot;</span>]];\n</pre></div>\n<p>This requires <code>Card</code> to have a settable <code>[Parameter]</code> named <code>ChildContent</code> of a fragment type;\notherwise <a href=\"/docs/diagnostics#bcf3013\">BCF3013</a> is reported. A <code>RenderFragment&lt;TContext&gt;</code> counts: the brackets bind it with the\ncontext discarded, because there is no name inside brackets to read a context through. A generic\nfragment under any <em>other</em> name is named with <code>.Template</code> instead — see\n<a href=\"#generic-fragment-parameters\">Generic fragment parameters</a> below.</p>\n<p>Other non-generic <code>RenderFragment</code> parameters (such as <code>Footer</code> or <code>Header</code>) bind through\n<code>.Param(c =&gt; c.Footer, content)</code>, naming the parameter explicitly:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;Card&gt;()\n        .Param(c =&gt; c.Title, <span class=\"string\">&quot;Card title&quot;</span>)\n        .Param(c =&gt; c.Footer, Span[<span class=\"string\">&quot;Footer note&quot;</span>])[\n            H2[<span class=\"string\">&quot;Heading&quot;</span>],\n            P[<span class=\"string\">&quot;Body text&quot;</span>]];\n</pre></div>\n<p>Naming <code>ChildContent</code> through <code>.Param</code> is also legal. That is verbose, but it matches Razor's\nattribute form (<code>&lt;Card&gt;&lt;ChildContent&gt;...&lt;/ChildContent&gt;&lt;/Card&gt;</code>). Binding the same parameter\nthrough both channels reports <a href=\"/docs/diagnostics#bcf3007\">BCF3007</a>.</p>\n<p>A real <code>RenderFragment</code> value (as opposed to a BlazorCodeFirst <code>View</code> expression) still binds\nthrough the generic <code>.Param&lt;TValue&gt;</code> overload and is emitted verbatim.</p>\n<p>Which overload runs is decided by the target parameter's type: a <code>RenderFragment?</code> parameter takes\nthe content overload, everything else takes the generic one. So content aimed at a parameter that is\nnot a <code>RenderFragment</code> lands on the generic overload, which emits its value verbatim — and the\nruntime value of a design-time expression is an empty marker. That reports\n<a href=\"/docs/diagnostics#bcf3014\">BCF3014</a>:</p>\n<div class=\"csharp\"><pre>\n[Parameter] <span class=\"keyword\">public</span> <span class=\"keyword\">object</span>? Payload { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\n\nComponent&lt;Card&gt;().Param(c =&gt; c.Payload, Div[<span class=\"string\">&quot;x&quot;</span>])   <span class=\"comment\">// BCF3014</span>\n</pre></div>\n<p><code>View</code>, <code>ElementView</code>, <code>ComponentView&lt;T&gt;</code> and <code>SlotView</code> are all reported the same way. To pass\ncontent, give the receiving component a <code>RenderFragment</code> parameter.</p>\n<p>For unresolved type names inside parameter values, see\n<a href=\"/docs/diagnostics#bcf3015\">BCF3015</a>.</p>\n<h2 id=\"generic-fragment-parameters\">Generic fragment parameters<a href=\"#generic-fragment-parameters\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>A <code>RenderFragment&lt;TContext&gt;</code> parameter takes a <em>template</em>: the component invokes it once per context\nvalue it wants rendered. <code>EditForm.ChildContent</code> is the most common example: it is a\n<code>RenderFragment&lt;EditContext&gt;</code>.</p>\n<p><code>.Template</code> names such a parameter. It has two spellings, and which one you want depends only on\nwhether the content reads the context. A generic fragment under a name other than <code>ChildContent</code>,\nsuch as a grid's <code>RowTemplate</code>, always needs <code>.Template</code>, because the brackets never reach it.</p>\n<p>For a <code>ChildContent</code> whose content ignores the context, the brackets are the spelling — the form\nshown above, which emits exactly what <code>.Template(form =&gt; form.ChildContent, content)</code> emits:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;EditForm&gt;()\n        .Param(form =&gt; form.Model, _model)[\n            Component&lt;NameFields&gt;().Param(fields =&gt; fields.Value, _model)];\n</pre></div>\n<p>Or name it, with a lambda from the context to content:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;EditForm&gt;()\n        .Param(form =&gt; form.Model, _model)\n        .Template(form =&gt; form.ChildContent, editContext =&gt;\n            Fragment(\n                Span[editContext.IsModified() ? <span class=\"string\">&quot;Unsaved changes&quot;</span> : <span class=\"string\">&quot;No changes&quot;</span>],\n                Component&lt;NameFields&gt;().Param(fields =&gt; fields.Value, _model)));\n</pre></div>\n<p>That second example needs one caveat, or the badge will never change. <code>IsModified()</code> is read when the\ntemplate runs, and nothing in the <code>EditForm</code> / <code>CascadingValue</code> chain re-renders on <code>OnFieldChanged</code>.\nTyping into a field does notify the <code>EditContext</code>, but with nothing subscribed to that notification\nthe component holding the template never re-renders, so the badge keeps the text it was first\nrendered with. This is Blazor's render propagation, not a limit on\nthe context the template receives: the template is handed the live <code>EditContext</code> every time it runs.</p>\n<p>So if a template reads context state that changes, the component owning the form has to re-render\nitself. Construct the <code>EditContext</code> rather than letting <code>Model</code> create it, subscribe to\n<code>OnFieldChanged</code>, call <code>StateHasChanged</code>, and unsubscribe in <code>Dispose</code>:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> ContextReadingForm()\n{\n    _editContext = <span class=\"keyword\">new</span> EditContext(_model);\n    _editContext.OnFieldChanged += OnFieldChanged;\n}\n\n<span class=\"keyword\">private</span> <span class=\"keyword\">void</span> OnFieldChanged(<span class=\"keyword\">object</span>? sender, FieldChangedEventArgs e) =&gt; StateHasChanged();\n\n<span class=\"keyword\">public</span> <span class=\"keyword\">void</span> Dispose() =&gt; _editContext.OnFieldChanged -= OnFieldChanged;\n\n<span class=\"comment\">// ...then pass .Param(form =&gt; form.EditContext, _editContext) instead of .Param(form =&gt; form.Model, …)</span>\n</pre></div>\n<p>A template that ignores its context, or reads only state that does not change while the form is open,\nneeds none of this.</p>\n<p>The generator writes the <code>RenderFragment&lt;TContext&gt;</code> lambda for you, so the content inside is ordinary\nBlazorCodeFirst and its sequence numbers continue the surrounding ones. The context parameter's name\nis yours to choose; the generated code uses a name of its own and rewrites the places you referred to\nit, so a field that happens to share the name is not disturbed.</p>\n<p>The second argument must be an inline lambda. A method group, or a delegate held in a variable or\nfield, reports <a href=\"/docs/diagnostics#bcf3022\">BCF3022</a>: what gets copied into the generated code is the lambda's body syntax, and\na delegate whose declaration is elsewhere has no body to copy.</p>\n<p>If you already hold a <code>RenderFragment&lt;TContext&gt;</code> <em>value</em>, pass it through the scalar\n<code>.Param</code> instead. Both channels reach the same parameter, but they differ in delegate identity, and\nthat difference is visible:</p>\n<div class=\"csharp\"><pre>\n<span class=\"comment\">// Built once, in the constructor. The parameter reference stays stable across renders.</span>\n<span class=\"keyword\">private</span> <span class=\"keyword\">readonly</span> RenderFragment&lt;EditContext&gt; _fields;\n</pre></div>\n<p><code>.Template</code> content that reads state captures it, so the lambda becomes a new delegate on every\nrender. The receiving component sees a changed parameter and re-renders the template. A cached\ndelegate passed through <code>.Param</code> does not change, so it does not. Use the cached form only when you\nwant that stability; <code>.Template</code> is otherwise the shorter and safer spelling, because it cannot be\nforgotten the way caching can.</p>\n<h2 id=\"calling-an-existing-razor-or-third-party-component\">Calling an existing Razor or third-party component<a href=\"#calling-an-existing-razor-or-third-party-component\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>The syntax does not change. A component written in <code>.razor</code>, or one from a package such as\nMudBlazor or QuickGrid, is placed with the same <code>Component&lt;T&gt;()</code>:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        Span[<span class=\"string\">&quot;Data Grid&quot;</span>],\n        Component&lt;MudDataGrid&lt;Order&gt;&gt;()\n            .Param(g =&gt; g.Items, _orders)\n            .Param(g =&gt; g.Dense, <span class=\"keyword\">true</span>)];\n</pre></div>\n<p>One restriction applies, and it is the one most authors hit first. The type argument falls into\nthe generated code as a literal <code>OpenComponent&lt;T&gt;</code>, so it has to resolve while the generator runs.\nThe Razor compiler is itself a source generator, and source generators cannot observe each other's\noutput. A <code>.razor</code> component declared in the <em>same project</em> therefore does not exist yet when\nBlazorCodeFirst's generator runs, and naming it reports <a href=\"/docs/diagnostics#bcf3012\">BCF3012</a>.</p>\n<p>There are two ways around it:</p>\n<ul>\n<li>Move the <code>.razor</code> component into a referenced project or a package. Its type then comes from\nmetadata and resolves normally.</li>\n<li>Hand-write the component in C#. A hand-written component is ordinary source, so it always\nresolves — including in the same project.</li>\n</ul>\n<p>A typo or a missing <code>using</code> produces the same BCF3012, alongside CS0246 at the same position.</p>\n<h2 id=\"cascading-a-value\">Cascading a value<a href=\"#cascading-a-value\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>CascadingValue&lt;T&gt;</code> is one of those existing components, so this surface adds nothing for cascading.\nPlace it with <code>Component&lt;T&gt;()</code>, set <code>Value</code> through <code>.Param</code>, and put the subtree that reads it in\nbrackets:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;CascadingValue&lt;ThemeInfo&gt;&gt;()\n        .Param(c =&gt; c.Value, _theme)[\n            Component&lt;Toolbar&gt;(),\n            Component&lt;Editor&gt;()];\n</pre></div>\n<p><code>Name</code> and <code>IsFixed</code> are <code>.Param</code> targets like any other, so a named cascade is\n<code>.Param(c =&gt; c.Name, &quot;locale&quot;)</code> on this side and <code>[CascadingParameter(Name = &quot;locale&quot;)]</code> on the\nreceiving one.</p>\n<p>That receiving side is ordinary Blazor, and the generator never sees it. <code>[CascadingParameter]</code> is a\nproperty on the class, exactly as it is in a <code>.razor</code> component:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Toolbar : BodyComponentBase\n{\n    [CascadingParameter]\n    <span class=\"keyword\">public</span> ThemeInfo? Theme { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\n\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n        Div.Class(<span class=\"string\">&quot;toolbar&quot;</span>)[Span[Theme?.Name ?? <span class=\"string\">&quot;default&quot;</span>]];\n}\n</pre></div>\n<p>Replacing the value re-renders every descendant that reads it, including ones whose own frames did\nnot change. The subscription is Blazor's own: what the generator emits for the call above is what\n<code>&lt;CascadingValue Value=&quot;@_theme&quot;&gt;</code> emits.</p>\n<h2 id=\"using-a-blazorcodefirst-component-from-razor\">Using a BlazorCodeFirst component from Razor<a href=\"#using-a-blazorcodefirst-component-from-razor\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>The other direction has no such restriction. A BlazorCodeFirst component is a plain Blazor\ncomponent — <code>BodyComponentBase</code> derives from <code>ComponentBase</code> — so a <code>.razor</code> file names it as an\nordinary tag:</p>\n<pre><code class=\"language-razor\">@* ExistingPage.razor *@\n&lt;div class=&quot;legacy-layout&quot;&gt;\n    &lt;StatusBadge Status=&quot;@currentStatus&quot; /&gt;\n&lt;/div&gt;\n</code></pre>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> StatusBadge : BodyComponentBase\n{\n    [Parameter] <span class=\"keyword\">public</span> Status Status { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; } = <span class=\"keyword\">default</span>!;\n\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n        Span.Class(Status.IsHealthy ? <span class=\"string\">&quot;badge badge-ok&quot;</span> : <span class=\"string\">&quot;badge badge-alert&quot;</span>)[Status.Label];\n}\n</pre></div>\n<p>This works in the same project, and it is worth understanding why the asymmetry with BCF3012\nexists. What Razor has to resolve here is the <em>class name</em>, and that class declaration is source\nyou wrote. The generator only fills in <code>RenderView</code> inside it, and Razor never needs to see that.\nIn the BCF3012 direction, the type itself is generated output, which is a different problem.</p>\n<p>This site does it: <code>App.razor</code> names <code>NotFoundPage</code>, a BlazorCodeFirst component declared in a\nplain <code>.cs</code> file in the same project.</p>\n<h2 id=\"splitting-without-a-component-viewpart\">Splitting without a component: <code>[ViewPart]</code><a href=\"#splitting-without-a-component-viewpart\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Not every part of a <code>Body</code> expression needs a component. A <code>[ViewPart]</code> method is a piece of\nUI that the generator expands <em>into the caller</em> rather than rendering through a component\nboundary:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        AppHeader(<span class=\"string\">&quot;My Application&quot;</span>),\n        BodyContent()];\n\n[ViewPart]\n<span class=\"keyword\">private</span> <span class=\"keyword\">static</span> View AppHeader(<span class=\"keyword\">string</span> title) =&gt;\n    Div.Class(<span class=\"string\">&quot;app-header&quot;</span>)[\n        Span[title]];\n</pre></div>\n<p>The caller's generated <code>RenderView</code> contains the header's frames directly. There is no component\ninstance, no parameters, no lifecycle, and no diffing boundary — it is as if you had written the\nmarkup inline.</p>\n<h3 id=\"naming-a-component-call\">Naming a component call<a href=\"#naming-a-component-call\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>A part's body is ordinary design-time syntax, so it can be a component call as readily as an element.\nThat gives a component invocation a name of its own, and the call site stops mentioning\n<code>Component&lt;T&gt;()</code> or <code>.Param</code> at all:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">static</span> <span class=\"keyword\">class</span> Widgets\n{\n    [ViewPart]\n    <span class=\"keyword\">public</span> <span class=\"keyword\">static</span> View Badge(<span class=\"keyword\">string</span> label, <span class=\"keyword\">bool</span> compact = <span class=\"keyword\">false</span>) =&gt;\n        Component&lt;StatusBadge&gt;()\n            .Param(b =&gt; b.Label, label)\n            .Param(b =&gt; b.Compact, compact);\n}\n\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Dashboard : BodyComponentBase\n{\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n        Div[\n            Widgets.Badge(<span class=\"string\">&quot;hello&quot;</span>),\n            Widgets.Badge(<span class=\"string\">&quot;x&quot;</span>, compact: <span class=\"keyword\">true</span>)];\n}\n</pre></div>\n<p>Named and optional arguments work, because the call site is an ordinary C# call. The caller's\ngenerated <code>RenderView</code> opens <code>StatusBadge</code> directly at each call, so the rendered tree is the one\nwriting <code>Component&lt;StatusBadge&gt;()</code> twice would have produced. The\n<code>.Param</code> rules are checked where the selector is written, so BCF3006 and BCF3007 are reported once at\nthe part's declaration, however many call sites it has.</p>\n<p>The component being named can come from anywhere, a package included, so <code>MudDataGrid&lt;Order&gt;</code> takes a\nname on the same terms as a component you wrote. The part cannot: it is expanded from its\ndeclaration's source syntax, so it has to live in the project that calls it (BCF1002, below). A\ncomponent library therefore ships components and not the parts that name them, and each consuming\nproject writes its own — the BCF3012 asymmetry seen from the other side.</p>\n<h3 id=\"wrapping-content\">Wrapping content<a href=\"#wrapping-content\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>A part that wraps content the caller supplies returns <code>SlotView</code> instead of <code>View</code>, and writes\n<code>Slot</code> where that content belongs. The caller supplies it in brackets, exactly as it supplies an\nelement's children:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        Card(<span class=\"string\">&quot;Profile&quot;</span>)[P[<span class=\"string\">&quot;Body text&quot;</span>]],\n        Section.Class(<span class=\"string\">&quot;body&quot;</span>)[P[<span class=\"string\">&quot;…&quot;</span>]]];\n\n[ViewPart]\n<span class=\"keyword\">private</span> <span class=\"keyword\">static</span> SlotView Card(<span class=\"keyword\">string</span> title) =&gt;\n    Div.Class(<span class=\"string\">&quot;card&quot;</span>)[\n        H2[title],\n        Slot];\n</pre></div>\n<p>That is the point of the spelling: a part you factored out reads the same way a built-in element\ndoes. <code>Card(&quot;Profile&quot;)[…]</code> and <code>Section.Class(&quot;body&quot;)[…]</code> read alike, and nothing marks one of them\nas yours.</p>\n<p>The brackets are not optional, and nothing enforces that but C#. <code>SlotView</code> has no conversion to\n<code>View</code>, so <code>Div[Card(&quot;Profile&quot;)]</code> — the brackets forgotten — is a compile error rather than a card\nthat renders silently empty. The same property rules out a decoration (<code>Card(&quot;t&quot;).Class(&quot;x&quot;)</code>, which\nfinds no extension method) and the positional spelling (<code>Card(&quot;t&quot;, P[&quot;x&quot;])</code>, which has no parameter\nto bind to).</p>\n<p>A second slot is an ordinary <code>View</code> parameter:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Panel(H2[<span class=\"string\">&quot;Title&quot;</span>])[\n        P[<span class=\"string\">&quot;Body text&quot;</span>]];\n\n[ViewPart]\n<span class=\"keyword\">private</span> <span class=\"keyword\">static</span> SlotView Panel(View header) =&gt;\n    Div.Class(<span class=\"string\">&quot;panel&quot;</span>)[\n        Div.Class(<span class=\"string\">&quot;panel-head&quot;</span>)[header],\n        Div.Class(<span class=\"string\">&quot;panel-body&quot;</span>)[Slot]];\n</pre></div>\n<p>Named channels first, the main content in brackets: the shape <code>Div.Class(&quot;card&quot;)[…]</code> and\n<code>Component&lt;T&gt;().Template(…)[…]</code> already have on this surface.</p>\n<p>A slot sits in a component's brackets as readily as in an element's, which is how a named component\ncall takes content:</p>\n<div class=\"csharp\"><pre>\n[ViewPart]\n<span class=\"keyword\">private</span> <span class=\"keyword\">static</span> SlotView Framed(<span class=\"keyword\">string</span> title) =&gt;\n    Component&lt;Card&gt;().Param(c =&gt; c.Title, title)[Slot];\n</pre></div>\n<p>The caller's content reaches <code>Card.ChildContent</code>, by the rule\n<a href=\"#passing-child-content\">Passing child content</a> states.</p>\n<p>Two rules apply. A <code>SlotView</code> part must name <code>Slot</code> <strong>exactly once</strong>: naming it twice\nwould emit the caller's content twice from one bracket, and never naming it would discard content the\ncaller was required to supply. Either reports <a href=\"/docs/diagnostics#bcf3025\">BCF3025</a>, as does a <code>Slot</code> written anywhere that\nreceives no caller content — a component's own <code>Body</code>, or a part returning <code>View</code>.</p>\n<p>A <code>View</code> parameter, by contrast, may be referenced any number of times, because it is an ordinary\nparameter. Nothing is captured or shared: each reference expands the caller's expression again, so an\nargument with side effects runs once per reference. That is the same behaviour a Blazor\n<code>RenderFragment</code> invoked twice has.</p>\n<p>Both kinds are content, though, and content has no value: it becomes frames, not an expression. So a\nslot can only be <em>placed</em> as a child. Reading one where a value is expected — as a <code>ForEach</code> key, or\ninside an attribute value — reports <a href=\"/docs/diagnostics#bcf1002\">BCF1002</a>.</p>\n<p>The trade-off in full:</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th><code>[ViewPart]</code></th>\n<th>A component</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>State and lifecycle</td>\n<td>none; it is a method</td>\n<td>its own, as any Blazor component has</td>\n</tr>\n<tr>\n<td>Re-rendering</td>\n<td>with the caller, having no boundary of its own</td>\n<td>on its own, at its own diffing boundary</td>\n</tr>\n<tr>\n<td>What the caller's frames hold</td>\n<td>the part's frames, expanded in place</td>\n<td>one frame that opens the component</td>\n</tr>\n<tr>\n<td>Arguments</td>\n<td>by-value parameters, named and optional</td>\n<td><code>[Parameter]</code> properties, set through <code>.Param</code></td>\n</tr>\n<tr>\n<td>From another assembly</td>\n<td>not available (BCF1002)</td>\n<td>available</td>\n</tr>\n</tbody>\n</table>\n<p>A <code>[ViewPart]</code> has to satisfy a declaration contract the generator can expand, or it reports\n<strong>BCF1002</strong>. The method must be:</p>\n<ul>\n<li>static</li>\n<li>non-generic, and declared in a non-generic type</li>\n<li>reaching one returned expression, with locals and expression statements allowed ahead of it — the\nsame shape a <code>Body</code> getter takes</li>\n<li>returning <code>View</code>, or <code>SlotView</code> to take content</li>\n</ul>\n<p>Its parameters must be ordinary by-value parameters whose types can be named from generated code.\n<code>params</code>, by-reference parameters,\nand <code>ElementView</code> parameters are all rejected — a childless element is passed as content by\nwriting <code>Div[…]</code> or <code>Fragment(Div)</code>, both of which are <code>View</code>s. A <code>View</code> parameter is a content slot,\nso it requires the <code>SlotView</code> return type; on a part returning <code>View</code> it is BCF1002, and it may\nnever be optional.</p>\n<p>It also must not be an extension member — neither a <code>this</code> parameter nor a member of an <code>extension</code>\nblock. A call is written as a plain call (<code>AppHeader(&quot;My Application&quot;)</code>), the way this surface writes\nevery call that is not a decoration on an element. The fluent spelling would put something that is\nnot a decoration in the position the surface reserves for one. Its receiver could only ever be some\nother type's value, which would turn <code>[ViewPart]</code> into a way to grow <em>that</em> type's API rather than to\nsplit up a <code>Body</code>.</p>\n<p>BCF1002 also fires at the <em>call site</em>, and one of its conditions is worth stating plainly:</p>\n<p><strong>a <code>[ViewPart]</code> cannot cross an assembly boundary.</strong> Expanding a call needs the declaration's\nsource syntax, and the generator collects declarations from the compilation it is running in. IL\ncarries no body syntax, so a <code>[ViewPart]</code> in a referenced project or a package always reports\nBCF1002 where it is called. The same diagnostic covers a recursive expansion cycle, and a body\nthat reaches a <code>private</code> or <code>protected</code> member the expansion site cannot see.</p>\n<p>If you need the part in another project, make it a component and use it through <code>Component&lt;T&gt;()</code>.</p>\n<p>BCF1002 is not only the <code>[ViewPart]</code> diagnostic. A component's own <code>Body</code> and a layout's <code>Chrome</code> are\nnormalized through the same check, and a report from there names the expression rather than a method\n— see <a href=\"/docs/diagnostics#bcf1002\">BCF1002</a>.</p>\n<h2 id=\"next\">Next<a href=\"#next\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>See <a href=\"/docs/layouts\">layouts</a> for wrapping routed pages in shared chrome,\n<a href=\"/docs/two-way-binding#binding-a-component-parameter\">two-way binding</a> for <code>.Bind</code>, the other way a\nparameter is supplied, or <a href=\"/docs/control-flow\">control flow</a> for <code>If</code> and keyed <code>ForEach</code>.</p>\n"),
        new DocEntry(
            "layouts",
            "Layouts",
            "Wrapping the routed page in shared chrome by deriving a layout from ChromeLayoutBase.",
            70,
            "write",
            "en",
            false,
            ["chrome-and-body", "why-chrome-not-body", "nesting-layouts", "renderfragment-becomes-content-directly", "reads-are-allowed-mutation-is-not", "next"],
            "<p>A layout wraps the routed page with shared chrome: headers, navigation, footers. BlazorCodeFirst\nlayouts are written the same way as components: derive from <code>ChromeLayoutBase</code>, declare a\ndesign-time UI expression, and let the source generator produce the rendering.</p>\n<h2 id=\"chrome-and-body\">Chrome and Body<a href=\"#chrome-and-body\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>ChromeLayoutBase</code> derives from Blazor's <code>LayoutComponentBase</code>, so it already has a <code>Body</code>\nparameter holding the routed page. The chrome the layout itself draws goes in a separate\noverridden property, <code>Chrome</code>:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">using</span> BlazorCodeFirst;\n<span class=\"keyword\">using</span> <span class=\"keyword\">static</span> BlazorCodeFirst.Html;\n\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> MainLayout : ChromeLayoutBase\n{\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Chrome =&gt;\n        Div.Class(<span class=\"string\">&quot;shell&quot;</span>)[\n            Header[H1[<span class=\"string\">&quot;My App&quot;</span>]],\n            Main.Class(<span class=\"string\">&quot;content&quot;</span>)[Body],\n            Footer[<span class=\"string\">&quot;&#169; 2026&quot;</span>]];\n}\n</pre></div>\n<p><code>Main[Body]</code> here is exactly <code>&lt;main&gt;@Body&lt;/main&gt;</code> in Razor, the routed page placed as element\ncontent. The output below shows a placeholder where the routed page appears:</p>\n<!-- bcf-figure: AppShell -->\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Chrome =&gt;\n    Div.Class(<span class=\"string\">&quot;shell&quot;</span>)[\n        Header[H1[<span class=\"string\">&quot;My App&quot;</span>]],\n        Main.Class(<span class=\"string\">&quot;content&quot;</span>)[Body],\n        Footer[<span class=\"string\">&quot;&#169; 2026&quot;</span>]];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">div</span> <span class=\"htmlAttributeName\">class</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;shell&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">header</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">h1</span><span class=\"htmlTagDelimiter\">&gt;</span>My App<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">h1</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">header</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">main</span> <span class=\"htmlAttributeName\">class</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;content&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>the routed page<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">main</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">footer</span><span class=\"htmlTagDelimiter\">&gt;</span>&#169; 2026<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">footer</span><span class=\"htmlTagDelimiter\">&gt;</span>\n<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div><h2 id=\"why-chrome-not-body\">Why Chrome, not Body<a href=\"#why-chrome-not-body\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Blazor requires a layout's routed content to be exposed through a parameter named exactly\n<code>Body</code>, and C# cannot declare two members with the same name on one type. So <code>Body</code> keeps\nits Razor meaning, the page being wrapped, and the layout's own design-time expression is\nnamed <code>Chrome</code> instead.</p>\n<h2 id=\"nesting-layouts\">Nesting layouts<a href=\"#nesting-layouts\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>A layout can itself sit inside another layout. Put <code>[Layout]</code> on the layout type, exactly as you\nwould on a page:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">using</span> BlazorCodeFirst;\n<span class=\"keyword\">using</span> Microsoft.AspNetCore.Components;\n<span class=\"keyword\">using</span> <span class=\"keyword\">static</span> BlazorCodeFirst.Html;\n\n[Layout(<span class=\"keyword\">typeof</span>(SiteLayout))]\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> DocsLayout : ChromeLayoutBase\n{\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Chrome =&gt; Div.Class(<span class=\"string\">&quot;docs&quot;</span>)[Aside[TableOfContents()], Main[Body]];\n}\n</pre></div>\n<p>Nesting is resolved by Blazor, not by BlazorCodeFirst: <code>LayoutView</code> reads the attribute off the layout\ntype and wraps it in its own layout, and a BlazorCodeFirst layout is an ordinary <code>LayoutComponentBase</code>\ndescendant. Each level's <code>Body</code> holds the level below it. <code>SiteLayout</code>'s <code>Body</code> is the rendered\n<code>DocsLayout</code>, whose own <code>Body</code> is the routed page.</p>\n<h2 id=\"renderfragment-becomes-content-directly\">RenderFragment becomes content directly<a href=\"#renderfragment-becomes-content-directly\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>Body</code> is a plain Blazor <code>RenderFragment?</code>, not a BlazorCodeFirst type, yet <code>Main[Body]</code> above\ncompiles without dedicated syntax. <code>View</code> has an implicit conversion from <code>RenderFragment?</code>,\nso any fragment can appear wherever element content is expected. The conversion is from the\nnon-generic <code>RenderFragment</code> only, and a <code>RenderFragment&lt;T&gt;</code> does not convert. Like <code>Fragment</code>\nand <code>Raw</code>, a <code>RenderFragment</code> opens no keyable frame, so it cannot be a <code>ForEach</code> content root\n(<a href=\"/docs/diagnostics#bcf3003\">BCF3003</a>) and cannot carry decorations\n(<a href=\"/docs/diagnostics#bcf3008\">BCF3008</a>).</p>\n<p>The same mechanism lets a BlazorCodeFirst component render children passed in from Razor. A component\nwith <code>[Parameter] public RenderFragment? ChildContent</code> uses it exactly like <code>Body</code>:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">using</span> BlazorCodeFirst;\n<span class=\"keyword\">using</span> Microsoft.AspNetCore.Components;\n<span class=\"keyword\">using</span> <span class=\"keyword\">static</span> BlazorCodeFirst.Html;\n\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Card : BodyComponentBase\n{\n    [Parameter]\n    <span class=\"keyword\">public</span> RenderFragment? ChildContent { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\n\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div.Class(<span class=\"string\">&quot;card&quot;</span>)[ChildContent];\n}\n</pre></div>\n<p>Passing content the other way, from BlazorCodeFirst code into a Razor or hand-written component,\nuses <code>Component&lt;T&gt;()</code>. See\n<a href=\"/docs/components-and-reuse#passing-child-content\">passing child content</a>.</p>\n<h2 id=\"reads-are-allowed-mutation-is-not\">Reads are allowed, mutation is not<a href=\"#reads-are-allowed-mutation-is-not\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Both <code>Chrome</code> and <code>Body</code> may read component state, since projecting state to UI is their purpose,\nbut neither may mutate it. <code>Body</code> here means the <code>BodyComponentBase</code> one, not the layout's\nrouted-content parameter. Mutating state inside either reports\n<a href=\"/docs/diagnostics#bcf3001\">BCF3001</a>, the same diagnostic that applies to a regular component's\n<code>Body</code>.</p>\n<h2 id=\"next\">Next<a href=\"#next\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>See <a href=\"/docs/components-and-reuse\">components and reuse</a> for calling one component from another, or\n<a href=\"/docs/elements-and-decorations\">elements and decorations</a> for the element vocabulary used above.</p>\n"),
        new DocEntry(
            "two-way-binding",
            "Two-Way Binding",
            ".Bind is the Razor bind directive with every argument visible: the attribute, the event, and a lambda reading the current value.",
            80,
            "write",
            "en",
            false,
            ["binding-an-element", "checkboxes-bind-checked", "why-you-write-both-names", "normalizing-with-an-explicit-setter", "numbers-dates-and-enums", "write-the-invariant-culture-for-number-and-date", "a-value-that-will-not-parse-is-put-back", "dates-need-a-format", "if-you-publish-trimmed", "doing-the-conversion-yourself", "binding-a-component-parameter", "what-is-checked", "next"],
            "<p>A two-way binding is one decoration that writes a value out to the DOM and reads the user's edit back\ninto your state. <code>.Bind</code> is Razor's <code>@bind</code>, spelled so that everything it needs is an argument you can\nsee. Nothing generated compiles an expression tree at runtime, and nothing generated reflects; binding\nan enum reaches one reflective lookup inside the framework's own converter.</p>\n<h2 id=\"binding-an-element\">Binding an element<a href=\"#binding-an-element\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Name the attribute that carries the value, the event that reports a change, and a lambda that reads\nthe current value. Only the first of those three appears in the markup:</p>\n<!-- bcf-figure: TextBinding -->\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        Input.Type(<span class=\"string\">&quot;text&quot;</span>).Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _name),\n        P[$<span class=\"string\">&quot;Hello, {_name}&quot;</span>]];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">input</span> <span class=\"htmlAttributeName\">type</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;text&quot;</span> <span class=\"htmlAttributeName\">value</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;Ada&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">p</span><span class=\"htmlTagDelimiter\">&gt;</span>Hello, Ada<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">p</span><span class=\"htmlTagDelimiter\">&gt;</span>\n<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>The lambda is read in both directions. Its body becomes the attribute's value, and — in this\ngetter-only form — the same body becomes the left-hand side of the assignment the generator writes\nfor you. So the target has to be assignable: a field, a property with a setter, or a path through\neither (<code>_form.Name</code>, <code>Model.Items[0].Title</code>, <code>_dict[&quot;k&quot;]</code>). A computed expression such as\n<code>() =&gt; _name.ToUpper()</code> reports <a href=\"/docs/diagnostics#bcf3018\">BCF3018</a>, and the way to write that is the\nexplicit setter below.</p>\n<p>Use <code>&quot;oninput&quot;</code> to bind on every keystroke and <code>&quot;onchange&quot;</code> to bind when the element loses focus.\nThose are the two you will usually want, and no list restricts the pair. Three rules do: both names\nhave to be non-empty compile-time constants (<a href=\"/docs/diagnostics#bcf3011\">BCF3011</a>), the event name has\nto start with <code>on</code> (<a href=\"/docs/diagnostics#bcf3019\">BCF3019</a>), and neither may already be bound on the same\nelement by another decoration (<a href=\"/docs/diagnostics#bcf3010\">BCF3010</a>).</p>\n<p>Nothing checks the names against HTML.</p>\n<h2 id=\"checkboxes-bind-checked\">Checkboxes bind <code>checked</code><a href=\"#checkboxes-bind-checked\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>A checkbox binds a <code>bool</code> to the <code>checked</code> attribute, on <code>onchange</code>. The same decoration, a different\nfirst argument, and a different attribute in the output:</p>\n<!-- bcf-figure: CheckboxBinding -->\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Label[\n        Input.Type(<span class=\"string\">&quot;checkbox&quot;</span>).Bind(<span class=\"string\">&quot;checked&quot;</span>, <span class=\"string\">&quot;onchange&quot;</span>, () =&gt; _agreed),\n        <span class=\"string\">&quot; I agree&quot;</span>];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">label</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">input</span> <span class=\"htmlAttributeName\">type</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;checkbox&quot;</span> <span class=\"htmlAttributeName\">checked</span><span class=\"htmlTagDelimiter\">&gt;</span> I agree<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">label</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p><code>bool</code> is HTML's boolean-attribute form, the same one\n<a href=\"/docs/elements-and-decorations#decorations\"><code>.Attr</code> takes</a>: <code>true</code> renders the attribute with an empty\nvalue, <code>false</code> leaves it out entirely.</p>\n<h2 id=\"why-you-write-both-names\">Why you write both names<a href=\"#why-you-write-both-names\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Razor infers the attribute from the markup: it reads the literal <code>type=&quot;checkbox&quot;</code> out of your <code>.razor</code>\nfile and binds <code>checked</code> instead of <code>value</code>. This surface has no literal to read. The tag is a string\nand <code>type</code> is an expression — <code>Input.Type(kind)</code> is an ordinary C# call whose value may not be known\nuntil it runs — so there is nothing an inference could be checked against.</p>\n<p>Defaulting to <code>value</code> would produce the failure most worth avoiding: a checkbox bound to the wrong\nattribute, silently, with no diagnostic. So the rule across the whole surface is <strong>infer only what\nyou can verify</strong>. The element side cannot verify, so it does not infer, and you write two short\nstrings instead.</p>\n<p>The half of the mistake that <em>is</em> checkable is caught: an event name that does not start with <code>on</code>\nreports <a href=\"/docs/diagnostics#bcf3019\">BCF3019</a>, so swapping the two arguments stops at compile time\nrather than adding an attribute that does nothing.</p>\n<p>The component side of <code>.Bind</code> does infer names, because the same rule allows it there — see\n<a href=\"#binding-a-component-parameter\">binding a component parameter</a>.</p>\n<h2 id=\"normalizing-with-an-explicit-setter\">Normalizing with an explicit setter<a href=\"#normalizing-with-an-explicit-setter\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>A fourth argument replaces the generated assignment with your own setter, which is where validation,\nnormalization, or any work that has to happen on each edit belongs:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">string</span> _name = <span class=\"string\">&quot;&quot;</span>;\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Input.Type(<span class=\"string\">&quot;text&quot;</span>).Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _name, v =&gt; _name = v.Trim());\n</pre></div>\n<p>This covers what Razor splits across <code>@bind:get</code> / <code>@bind:set</code> and <code>@bind:after</code>: the setter <em>is</em> the\nwrite, so anything you would have run afterwards goes in the same lambda. Note that the write is now\nyours to perform — nothing assigns for you once you supply a setter. A method group works too\n(<code>SetName</code>), the lambda may have a block body, and an <code>async</code> variant is available by returning\n<code>Task</code>:</p>\n<div class=\"csharp\"><pre>\nInput.Type(<span class=\"string\">&quot;text&quot;</span>).Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _query, <span class=\"keyword\">async</span> v =&gt;\n{\n    _query = v;\n    <span class=\"keyword\">await</span> SearchAsync(v);\n});\n</pre></div>\n<p>Only the getter-only form needs an assignable getter. With a setter, the getter is only ever read, so\nany expression will do. The getter itself must be an inline lambda with an expression body either way\n(<a href=\"/docs/diagnostics#bcf3017\">BCF3017</a>), because its body is copied into both the attribute value and\nthe binder.</p>\n<p>A normalizing setter creates a divergence: the element shows what was typed, while your field holds\nthe trimmed value. Ordinary diffing writes nothing, because the render tree has not changed since the\nlast render. On a <code>value</code> or <code>checked</code> binding, <code>.Bind</code> registers that attribute for DOM\nresynchronization to close the gap, so the element is corrected to show the normalized value. This\nneeds no configuration.</p>\n<p>That registration covers two names only. Blazor's client sends back a form element's own <code>value</code> — or\n<code>checked</code> for a checkbox — and nothing else, so those are the only two names the generator registers.\nA binding to any other attribute registers nothing; <code>.Bind(&quot;hue&quot;, &quot;onhuechange&quot;, () =&gt; _hue, Normalize)</code>\non a custom element is the usual shape. The setter still runs and the new value still reaches the DOM\nby ordinary diffing on the next render. What is missing is the repair above, for the case where\nnormalizing leaves the render tree unchanged and the element goes on showing what was typed.</p>\n<p>The setter receives <code>&quot;&quot;</code> for an emptied text input, never <code>null</code> — which is why it takes a\nnon-nullable <code>string</code>. Writing to your own state from the setter is allowed, even though writing to\nstate anywhere else in a <code>Body</code> reports <a href=\"/docs/diagnostics#bcf3001\">BCF3001</a>: a setter is a deferred\nhandler, like an <code>.OnClick</code> lambda, and does not run while the tree is being built.</p>\n<h2 id=\"numbers-dates-and-enums\">Numbers, dates, and enums<a href=\"#numbers-dates-and-enums\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Any type binds, as long as you write the culture. It is the last argument and it cannot be omitted:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">int</span> _age;\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Input.Type(<span class=\"string\">&quot;number&quot;</span>).Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _age, CultureInfo.InvariantCulture);\n</pre></div>\n<p>The culture formats the value on the way out and parses it on the way back, through Blazor's own\n<code>BindConverter</code>. Numbers, dates, times, <code>Guid</code>, enums, and every nullable form of those all work,\nbecause the conversion is the framework's rather than this library's.</p>\n<p>It is an argument rather than a default because a default would be a culture chosen without your\nseeing it. Razor picks one from the element's literal <code>type</code> — the literal this surface does not\nread, for the same reason it does not infer the attribute name. The choice moves to the call site.</p>\n<h3 id=\"write-the-invariant-culture-for-number-and-date\">Write the invariant culture for <code>number</code> and <code>date</code><a href=\"#write-the-invariant-culture-for-number-and-date\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>&lt;input type=&quot;number&quot;&gt;</code> and <code>&lt;input type=&quot;date&quot;&gt;</code> are defined in terms of a fixed format, not the\nuser's locale. Binding either under <code>CultureInfo.CurrentCulture</code> produces a value the element rejects\nas soon as the current locale writes decimals with a comma.</p>\n<p><strong>This is not diagnosed.</strong> The check would need to read <code>type</code>, and <code>type</code> is an expression here. A\nrule that fired only on a literal would catch the mistake in one spelling and miss it in another.\nWrite <code>CultureInfo.InvariantCulture</code> for those two, and use the current\nculture for text the user reads as prose.</p>\n<h3 id=\"a-value-that-will-not-parse-is-put-back\">A value that will not parse is put back<a href=\"#a-value-that-will-not-parse-is-put-back\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>If the converter cannot read what was typed, your setter is never called and both your field and the\nelement return to the previous value. That is Blazor's behaviour, and <code>.Bind</code> reaches it through the\nsame DOM resynchronization described above.</p>\n<p>This has a consequence worth choosing deliberately. On <code>&quot;oninput&quot;</code> the reversion runs on every\nkeystroke, so a decimal point typed into an <code>int</code> binding does not survive: <code>4.</code> is rejected and the\n<code>.</code> is removed. For numeric input that is usually not what you want:</p>\n<div class=\"csharp\"><pre>\n<span class=\"comment\">// Reverts on blur, so a half-typed number survives.</span>\nInput.Type(<span class=\"string\">&quot;number&quot;</span>).Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;onchange&quot;</span>, () =&gt; _amount, CultureInfo.InvariantCulture);\n</pre></div>\n<p><code>&quot;oninput&quot;</code> is still right when every intermediate value is meaningful — a range slider, or a text\nfield whose type accepts anything the user can type.</p>\n<p>Emptying the field is a separate matter, and it is not a rejection. Blazor reads an empty string as\nthe type's default, so clearing an <code>int</code> binding gives you <code>0</code> rather than leaving the previous value\nin place. Bind an <code>int?</code> where the field is genuinely optional; that takes <code>null</code> there.</p>\n<h3 id=\"dates-need-a-format\">Dates need a format<a href=\"#dates-need-a-format\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>A date input requires <code>yyyy-MM-dd</code>, and this surface cannot supply that from <code>type</code> the way Razor\ndoes. Write it as the argument before the culture:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> DateOnly _due = <span class=\"keyword\">new</span>(<span class=\"number\">2026</span>, <span class=\"number\">8</span>, <span class=\"number\">14</span>);\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Input.Type(<span class=\"string\">&quot;date&quot;</span>).Bind(\n        <span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _due, <span class=\"string\">&quot;yyyy-MM-dd&quot;</span>, CultureInfo.InvariantCulture);\n</pre></div>\n<p>A format is accepted for <code>DateTime</code>, <code>DateTimeOffset</code>, <code>DateOnly</code>, <code>TimeOnly</code> and their nullable\nforms, and for nothing else — those are the types the framework declares a format-taking converter\nfor. Writing one for an <code>int</code> reports <a href=\"/docs/diagnostics#bcf3031\">BCF3031</a>. To format a number, format\nit in the getter and parse it in an explicit setter instead.</p>\n<h3 id=\"if-you-publish-trimmed\">If you publish trimmed<a href=\"#if-you-publish-trimmed\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Binding any value type roots Blazor's <code>BindConverter</code> whole, including converters for types you never\nbind. Measured on a trimmed self-contained publish, that is about 10 KB of\n<code>Microsoft.AspNetCore.Components.dll</code>. An app that binds only <code>string</code> and <code>bool</code> does not pay it. It\nis a one-off, not per binding.</p>\n<h3 id=\"doing-the-conversion-yourself\">Doing the conversion yourself<a href=\"#doing-the-conversion-yourself\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>The explicit form still works, and is what you want when the value needs validating rather than\nconverting:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">decimal</span> _amount;\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Input.Type(<span class=\"string\">&quot;text&quot;</span>).Bind(\n        <span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;onchange&quot;</span>,\n        () =&gt; _amount.ToString(CultureInfo.InvariantCulture),\n        v =&gt; _amount = <span class=\"keyword\">decimal</span>.TryParse(v, NumberStyles.Number, CultureInfo.InvariantCulture, <span class=\"keyword\">out</span> <span class=\"keyword\">var</span> d)\n            ? d\n            : _amount);\n</pre></div>\n<p>Use <code>TryParse</code> rather than <code>Parse</code> here. An exception thrown from a setter is not the framework's\nrejection path; it faults the render.</p>\n<h2 id=\"binding-a-component-parameter\">Binding a component parameter<a href=\"#binding-a-component-parameter\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>On a component the names are derived rather than written, because there the derivation can be checked.\n<code>.Bind</code> selects the parameter with a lambda and the generator appends <code>{Name}Changed</code>, plus\n<code>{Name}Expression</code> when the component declares it:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">using</span> Microsoft.AspNetCore.Components.Forms;\n\n<span class=\"keyword\">private</span> <span class=\"keyword\">readonly</span> NameModel _model = <span class=\"keyword\">new</span>();\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;InputText&gt;().Bind(c =&gt; c.Value, () =&gt; _model.Name);\n</pre></div>\n<p>That single call supplies <code>Value</code>, <code>ValueChanged</code>, and <code>ValueExpression</code>. Every derived name is looked\nup on the component type, so a missing or mistyped <code>{Name}Changed</code> reports\n<a href=\"/docs/diagnostics#bcf3020\">BCF3020</a> rather than binding nothing. This is what makes the asymmetry with\nthe element side a rule and not an inconsistency.</p>\n<p><code>{Name}Expression</code> is the reason the target is written as a getter lambda rather than passed by\nreference. A component under an <code>EditForm</code> resolves a <code>FieldIdentifier</code> from that expression, and the\nidentifier is what ties the input to a property of your model, so validation messages land on the right\nfield. No other spelling could supply it.</p>\n<p>The <code>EditForm</code> around it is written the same way. <code>EditForm.ChildContent</code> is a\n<code>RenderFragment&lt;EditContext&gt;</code>, and the brackets supply it with the context discarded, so the content\nbelow needs nothing else. Content that reads the <code>EditContext</code> is named with <code>.Template</code> instead:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;EditForm&gt;()\n        .Param(form =&gt; form.Model, _model)[\n            Component&lt;NameFields&gt;().Param(fields =&gt; fields.Value, _model)];\n</pre></div>\n<p>The bound inputs may sit directly in the brackets or in their own component; the binding above, and\nthe <code>ValueExpression</code> it supplies, are unaffected either way. See\n<a href=\"/docs/components-and-reuse#generic-fragment-parameters\">generic fragment parameters</a> for the spelling\nthat reads the <code>EditContext</code>, and for when a cached delegate through <code>.Param</code> is the better choice.</p>\n<p>An explicit setter and an <code>async</code> setter are available here too, with the same meaning as on an\nelement. <code>TValue</code> takes no culture and no format: the value goes to a parameter rather than to the\nDOM, so nothing formats or parses it on the way and there is no choice to write down.</p>\n<p>Remember that <code>Component&lt;T&gt;()</code> cannot name a <code>.razor</code> component declared in the same project\n(<a href=\"/docs/diagnostics#bcf3012\">BCF3012</a>). Framework components such as <code>InputText</code>, and hand-written C#\ncomponents, always resolve.</p>\n<h2 id=\"what-is-checked\">What is checked<a href=\"#what-is-checked\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Six diagnostics read a <code>.Bind</code>, and each has an entry in the <a href=\"/docs/diagnostics\">reference</a>:</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><a href=\"/docs/diagnostics#bcf3017\">BCF3017</a></td>\n<td>the getter's shape</td>\n</tr>\n<tr>\n<td><a href=\"/docs/diagnostics#bcf3018\">BCF3018</a></td>\n<td>a getter-only target that cannot be assigned</td>\n</tr>\n<tr>\n<td><a href=\"/docs/diagnostics#bcf3019\">BCF3019</a></td>\n<td>an event name missing its <code>on</code></td>\n</tr>\n<tr>\n<td><a href=\"/docs/diagnostics#bcf3020\">BCF3020</a></td>\n<td>a component with no matching change callback</td>\n</tr>\n<tr>\n<td><a href=\"/docs/diagnostics#bcf3024\">BCF3024</a></td>\n<td>a bound <code>class</code> beside a <code>.Class</code></td>\n</tr>\n<tr>\n<td><a href=\"/docs/diagnostics#bcf3031\">BCF3031</a></td>\n<td>a format the value's type has no converter for</td>\n</tr>\n</tbody>\n</table>\n<p>An element may carry more than one <code>.Bind</code>. If two of them share an attribute name or an event name,\nthat is <a href=\"/docs/diagnostics#bcf3010\">BCF3010</a>, the same duplicate any two decorations would report. DOM\nresynchronization — the repair that puts a normalized value back over what the user typed — applies to\n<code>value</code> and <code>checked</code> only, because those are the only two the browser sends back with the event.</p>\n<h2 id=\"next\">Next<a href=\"#next\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>See <a href=\"/docs/elements-and-decorations#decorations\">elements and decorations</a> for the one-way <code>.Attr</code> and\n<code>.On</code> this is built from, or <a href=\"/docs/components-and-reuse\">components and reuse</a> for <code>.Param</code> and the\nrest of the component surface.</p>\n"),
        new DocEntry(
            "element-reference",
            "Element Reference",
            "Every element helper, decoration and control-flow construct this surface declares, in one list, with void elements marked.",
            90,
            "reference",
            "en",
            false,
            ["elements", "sections", "grouping", "text-level", "edits", "embedded", "tabular", "forms", "interactive", "everything-else-elementtag", "decorations-on-an-element", "constructs", "decorations-on-a-component-call", "base-types"],
            "<p>Everything this surface declares, in one place. What each construct means is in\n<a href=\"/docs/elements-and-decorations\">elements and decorations</a> and <a href=\"/docs/control-flow\">control flow</a>.</p>\n<h2 id=\"elements\">Elements<a href=\"#elements\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>A helper is named by its tag with only the first letter uppercased: <code>Figcaption</code>, not <code>FigCaption</code>.\nAn asterisk marks a void element, which takes no children\n(<a href=\"/docs/diagnostics#bcf3016\">BCF3016</a>).</p>\n<p>There are 100 of them, one for every element the HTML Living Standard lists as conforming and that\nthe render tree can give meaning to.</p>\n<h3 id=\"sections\">Sections<a href=\"#sections\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Address</code>, <code>Article</code>, <code>Aside</code>, <code>Footer</code>, <code>H1</code>, <code>H2</code>, <code>H3</code>, <code>H4</code>, <code>H5</code>, <code>H6</code>, <code>Header</code>, <code>Hgroup</code>,\n<code>Main</code>, <code>Nav</code>, <code>Search</code>, <code>Section</code></p>\n<h3 id=\"grouping\">Grouping<a href=\"#grouping\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Blockquote</code>, <code>Dd</code>, <code>Div</code>, <code>Dl</code>, <code>Dt</code>, <code>Figcaption</code>, <code>Figure</code>, <code>Hr</code>*, <code>Li</code>, <code>Menu</code>, <code>Ol</code>, <code>P</code>,\n<code>Pre</code>, <code>Ul</code></p>\n<h3 id=\"text-level\">Text-level<a href=\"#text-level\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>A</code>, <code>Abbr</code>, <code>B</code>, <code>Bdi</code>, <code>Bdo</code>, <code>Br</code>*, <code>Cite</code>, <code>Code</code>, <code>Data</code>, <code>Dfn</code>, <code>Em</code>, <code>I</code>, <code>Kbd</code>, <code>Mark</code>,\n<code>Q</code>, <code>Rp</code>, <code>Rt</code>, <code>Ruby</code>, <code>S</code>, <code>Samp</code>, <code>Small</code>, <code>Span</code>, <code>Strong</code>, <code>Sub</code>, <code>Sup</code>, <code>Time</code>, <code>U</code>, <code>Var</code>,\n<code>Wbr</code>*</p>\n<h3 id=\"edits\">Edits<a href=\"#edits\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Del</code>, <code>Ins</code></p>\n<h3 id=\"embedded\">Embedded<a href=\"#embedded\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Area</code>*, <code>Audio</code>, <code>Canvas</code>, <code>Embed</code>*, <code>Iframe</code>, <code>Img</code>*, <code>Map</code>, <code>Picture</code>, <code>Source</code>*, <code>Track</code>*,\n<code>Video</code></p>\n<h3 id=\"tabular\">Tabular<a href=\"#tabular\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Caption</code>, <code>Col</code>*, <code>Colgroup</code>, <code>Table</code>, <code>Tbody</code>, <code>Td</code>, <code>Tfoot</code>, <code>Th</code>, <code>Thead</code>, <code>Tr</code></p>\n<h3 id=\"forms\">Forms<a href=\"#forms\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Button</code>, <code>Datalist</code>, <code>Fieldset</code>, <code>Form</code>, <code>Input</code>*, <code>Label</code>, <code>Legend</code>, <code>Meter</code>, <code>Optgroup</code>,\n<code>Option</code>, <code>Output</code>, <code>Progress</code>, <code>Select</code>, <code>Selectedcontent</code>, <code>Textarea</code></p>\n<h3 id=\"interactive\">Interactive<a href=\"#interactive\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Details</code>, <code>Dialog</code>, <code>Summary</code></p>\n<h3 id=\"everything-else-elementtag\">Everything else: <code>Element(tag)</code><a href=\"#everything-else-elementtag\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Element(&quot;my-widget&quot;)</code> names an element no helper covers. That is custom elements and Web\nComponents, plus the standard elements deliberately left out: the document and <code>&lt;head&gt;</code> elements,\nraw-text elements, <code>template</code> and <code>slot</code>, <code>object</code>, and the SVG and MathML elements. The tag has\nto be a compile-time constant spelled like a tag name\n(<a href=\"/docs/diagnostics#bcf3009\">BCF3009</a>). See\n<a href=\"/docs/elements-and-decorations#elements\">elements and decorations</a> for the full list of what reaches\nit and why.</p>\n<h2 id=\"decorations-on-an-element\">Decorations on an element<a href=\"#decorations-on-an-element\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<table>\n<thead>\n<tr>\n<th>Decoration</th>\n<th>Writes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>.Attr(name, value)</code></td>\n<td>any attribute, by name</td>\n</tr>\n<tr>\n<td><code>.Class(value)</code></td>\n<td>the class channel, which folds (<a href=\"/docs/elements-and-decorations#the-class-channel\">the class channel</a>)</td>\n</tr>\n<tr>\n<td><code>.Id(value)</code></td>\n<td><code>id</code></td>\n</tr>\n<tr>\n<td><code>.Title(value)</code></td>\n<td><code>title</code></td>\n</tr>\n<tr>\n<td><code>.Role(value)</code></td>\n<td><code>role</code></td>\n</tr>\n<tr>\n<td><code>.Type(value)</code></td>\n<td><code>type</code></td>\n</tr>\n<tr>\n<td><code>.Src(value)</code></td>\n<td><code>src</code></td>\n</tr>\n<tr>\n<td><code>.Alt(value)</code></td>\n<td><code>alt</code></td>\n</tr>\n<tr>\n<td><code>.Href(value)</code></td>\n<td><code>href</code></td>\n</tr>\n<tr>\n<td><code>.On(name, handler)</code></td>\n<td>any event, by name</td>\n</tr>\n<tr>\n<td><code>.OnClick(handler)</code></td>\n<td><code>onclick</code></td>\n</tr>\n<tr>\n<td><code>.PreventDefault()</code></td>\n<td>the preceding event's <code>preventDefault</code></td>\n</tr>\n<tr>\n<td><code>.StopPropagation()</code></td>\n<td>the preceding event's <code>stopPropagation</code></td>\n</tr>\n<tr>\n<td><code>.Bind(…)</code></td>\n<td>a two-way binding (<a href=\"/docs/two-way-binding\">two-way binding</a>)</td>\n</tr>\n<tr>\n<td><code>.Key(value)</code></td>\n<td>a diffing key, no markup (<a href=\"/docs/control-flow#foreach-and-its-key\">control flow</a>)</td>\n</tr>\n<tr>\n<td><code>.Ref(capture)</code></td>\n<td>an element reference, no markup</td>\n</tr>\n</tbody>\n</table>\n<p>The named ones are shorthands, not a separate mechanism: <code>.Id(&quot;x&quot;)</code> and <code>.Attr(&quot;id&quot;, &quot;x&quot;)</code> produce\nthe same frame, and both count as the same channel\n(<a href=\"/docs/diagnostics#bcf3010\">BCF3010</a>).</p>\n<h2 id=\"constructs\">Constructs<a href=\"#constructs\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<table>\n<thead>\n<tr>\n<th>Construct</th>\n<th>Does</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>If(condition, then, otherwise?)</code></td>\n<td>one branch, with disjoint sequence ranges</td>\n</tr>\n<tr>\n<td><code>ForEach(source, key, content)</code></td>\n<td>a keyed list</td>\n</tr>\n<tr>\n<td><code>Fragment(children…)</code></td>\n<td>groups children with no wrapper element</td>\n</tr>\n<tr>\n<td><code>Raw(html)</code></td>\n<td>injects trusted HTML verbatim</td>\n</tr>\n<tr>\n<td><code>Slot</code></td>\n<td>where a <code>SlotView</code> <code>[ViewPart]</code> places its caller's children</td>\n</tr>\n<tr>\n<td><code>Component&lt;T&gt;()</code></td>\n<td>calls a Blazor component</td>\n</tr>\n</tbody>\n</table>\n<h2 id=\"decorations-on-a-component-call\">Decorations on a component call<a href=\"#decorations-on-a-component-call\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<table>\n<thead>\n<tr>\n<th>Decoration</th>\n<th>Writes</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>.Param(selector, value)</code></td>\n<td>one <code>[Parameter]</code></td>\n</tr>\n<tr>\n<td><code>.Template(selector, template)</code></td>\n<td>a <code>RenderFragment&lt;T&gt;</code> parameter</td>\n</tr>\n<tr>\n<td><code>.Bind(selector, …)</code></td>\n<td>a two-way parameter binding (<a href=\"/docs/two-way-binding#binding-a-component-parameter\">two-way binding</a>)</td>\n</tr>\n<tr>\n<td><code>.Key(value)</code></td>\n<td>a diffing key</td>\n</tr>\n<tr>\n<td><code>.RenderMode(mode)</code></td>\n<td>the call-site render mode (<a href=\"/docs/installation-and-hosting#naming-a-render-mode\">installation and hosting</a>)</td>\n</tr>\n<tr>\n<td><code>.Ref(capture)</code></td>\n<td>a component reference</td>\n</tr>\n</tbody>\n</table>\n<p>Child content written in brackets sets <code>ChildContent</code>, and it counts as a binding of that parameter\n(<a href=\"/docs/diagnostics#bcf3007\">BCF3007</a>).</p>\n<h2 id=\"base-types\">Base types<a href=\"#base-types\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>For</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>BodyComponentBase</code></td>\n<td>a component, overriding <code>Body</code></td>\n</tr>\n<tr>\n<td><code>ChromeLayoutBase</code></td>\n<td>a layout, overriding <code>Chrome</code> (<a href=\"/docs/layouts\">layouts</a>)</td>\n</tr>\n<tr>\n<td><code>[ViewPart]</code></td>\n<td>a method whose markup expands into its caller</td>\n</tr>\n<tr>\n<td><code>SlotView</code></td>\n<td>the return type of a <code>[ViewPart]</code> that receives its caller's children</td>\n</tr>\n</tbody>\n</table>\n"),
        new DocEntry(
            "diagnostics",
            "Diagnostics",
            "Every diagnostic this compiler reports, what each one means, and what to write instead. Search the page for the ID the build printed.",
            100,
            "reference",
            "en",
            false,
            ["your-class-and-its-getter", "bcf1001", "bcf1002", "bcf1003", "bcf1004", "bcf1005", "where-the-surface-is-read", "bcf2001", "bcf3029", "bcf3030", "bcf3001", "bcf3015", "elements", "bcf3009", "bcf3016", "bcf3027", "decorations", "bcf3008", "bcf3026", "bcf3010", "bcf3011", "bcf3023", "bcf3024", "bcf3033", "bcf3034", "events", "bcf3019", "bcf3028", "bcf3035", "bcf3036", "bcf3038", "control-flow", "bcf3002", "bcf3003", "bcf3004", "bcf3032", "components", "bcf3005", "bcf3006", "bcf3007", "bcf3012", "bcf3013", "bcf3014", "bcf3022", "bcf3025", "two-way-binding", "bcf3017", "bcf3018", "bcf3020", "bcf3031", "next"],
            "<p>Every diagnostic this compiler reports, what it means, and what to write instead.</p>\n<p>The build prints the ID. Search this page for it.</p>\n<h2 id=\"your-class-and-its-getter\">Your class and its getter<a href=\"#your-class-and-its-getter\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf1001\">BCF1001<a href=\"#bcf1001\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The class declaring <code>Body</code> or <code>Chrome</code> is not <code>partial</code>, so there is nowhere to emit the\ngenerated <code>RenderView</code>.</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">class</span> Home : BodyComponentBase          <span class=\"comment\">// BCF1001</span>\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Home : BodyComponentBase  <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>Only the class that declares the override needs the modifier. A class that merely inherits a\nBlazorCodeFirst base without declaring one has nothing generated into it: an intermediate abstract\nbase, a leaf whose base already declares the override, and a re-abstraction are all left alone.</p>\n<p>Without this diagnostic the missing modifier would surface as CS0534 against the abstract\n<code>RenderView</code>, which names the missing member and never the modifier.</p>\n<h3 id=\"bcf1002\">BCF1002<a href=\"#bcf1002\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The expression names something the generated file cannot see, or a <code>[ViewPart]</code> method does\nnot satisfy the static-expansion contract.</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div.Attr(<span class=\"string\">&quot;data-found&quot;</span>, _rows.TryGetValue(_key, <span class=\"keyword\">out</span> <span class=\"keyword\">var</span> row))\n       .Attr(<span class=\"string\">&quot;title&quot;</span>, row.Name);                               <span class=\"comment\">// BCF1002: &#39;row&#39; cannot exist there</span>\n</pre></div>\n<p>The generator does not emit an element's parts in the order you wrote them, so a local declared in\none part of the expression does not reach a reference in another. Declare it in a statement ahead of\nthe return instead.</p>\n<p>Two positions do carry a declaration across, because each becomes a header in the generated code\nthat encloses whatever reads it: an <code>If</code> condition scopes over both branches, and a <code>ForEach</code> source\nover the content and the key.</p>\n<p>This is what separates BCF1002 from BCF1003. BCF1003 means the expression could not be sequenced;\nBCF1002 means it could, and named something the generated file cannot see.</p>\n<p>A <code>[ViewPart]</code> body follows the same reserved-name rule <a href=\"#bcf1004\">BCF1004</a> states for its getter.</p>\n<h3 id=\"bcf1003\">BCF1003<a href=\"#bcf1003\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The expression reached the model stage and could not be translated, because it uses a\nconstruct the generator does not analyze.</p>\n<div class=\"csharp\"><pre>\nDiv[_kids]                    <span class=\"comment\">// BCF1003: a child list passed whole</span>\nDiv[<span class=\"keyword\">new</span> View[] { … }]         <span class=\"comment\">// BCF1003: an explicit array</span>\nDiv[[..items]]                <span class=\"comment\">// BCF1003: a spread</span>\n</pre></div>\n<p>Use <a href=\"/docs/control-flow\"><code>ForEach</code></a> for repetition. Everything the generator reads is listed in\n<a href=\"/docs/elements-and-decorations\">elements and decorations</a> and <a href=\"/docs/control-flow\">control flow</a>:\nelement helpers, <code>Component&lt;T&gt;()</code>, <code>Fragment</code>, <code>Raw</code>, an inline expression lambda, and a call to a\nmethod marked <code>[ViewPart]</code>.</p>\n<p>Marking a <code>View</code>-returning method of your own <code>[ViewPart]</code> keeps the factoring rather than inlining\nits markup back into the caller.</p>\n<p>An <code>If</code> branch and a spliced projection (<code>.. source.Select(item =&gt; …)</code>) carry their body across\nunder the author's own names, the same way BCF1004's getter does, so <a href=\"#bcf1004\">BCF1004</a>'s\nreserved-name rule reaches them too.</p>\n<h3 id=\"bcf1004\">BCF1004<a href=\"#bcf1004\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The getter does not reach a single returned expression.</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div[H1[<span class=\"string\">&quot;Hello&quot;</span>]];              <span class=\"comment\">// fine</span>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body { <span class=\"keyword\">get</span> =&gt; Div[H1[<span class=\"string\">&quot;Hello&quot;</span>]]; }      <span class=\"comment\">// fine</span>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body { <span class=\"keyword\">get</span> { <span class=\"keyword\">return</span> Div[H1[<span class=\"string\">&quot;Hello&quot;</span>]]; } }   <span class=\"comment\">// fine</span>\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body { <span class=\"keyword\">get</span>; } = <span class=\"keyword\">default</span>;               <span class=\"comment\">// BCF1004</span>\n</pre></div>\n<p>Locals and expression statements may precede that return. They are copied into the generated\n<code>RenderView</code> ahead of the calls that emit render-tree frames:</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body\n{\n    <span class=\"keyword\">get</span>\n    {\n        <span class=\"keyword\">var</span> greeting = $<span class=\"string\">&quot;Hello, {_name}&quot;</span>;\n        <span class=\"keyword\">return</span> Div[H1[greeting]];\n    }\n}\n</pre></div>\n<p>A second return and native control flow each need a sequence space of their own, and an auto\nproperty declares no getter body at all. A local declared <code>__builder</code> or prefixed <code>__bcf_</code> cannot\nbe declared here either: the generator reserves both spellings everywhere a transplanted local can\nland. Rename the local. If the body genuinely cannot be written in this shape, override\n<code>RenderView</code> by hand: the design-time expression is then unused, and nothing is reported.</p>\n<p>BCF1004 reports the declaration, which is what separates it from BCF1003. A class can carry a\nmissing <code>partial</code> and an untranslatable getter at once, and only one is reported at a time: BCF1001\nruns first, and adding the modifier is what surfaces BCF1004.</p>\n<h3 id=\"bcf1005\">BCF1005<a href=\"#bcf1005\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. A nested class declares a design-time expression.</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Page\n{\n    <span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Row : BodyComponentBase   <span class=\"comment\">// BCF1005</span>\n    {\n    }\n}\n</pre></div>\n<p>Move the component to a top-level type. Reopening a nested class from the generated file would mean\nre-declaring every enclosing type, its type parameters included, so a nested component is rejected\nrather than half emitted. Without the diagnostic it would surface as CS0534, which names the missing\nmember and never the nesting.</p>\n<h2 id=\"where-the-surface-is-read\">Where the surface is read<a href=\"#where-the-surface-is-read\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf2001\">BCF2001<a href=\"#bcf2001\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Info. The call cannot be expanded statically, so this area renders through a runtime fragment and\nloses its static diff optimization.</p>\n<p>The generator expands what it can read: the design-time surface, and <code>[ViewPart]</code> methods declared\nin this compilation. A call it cannot read is correct and renders correctly. Its frames are rebuilt\nrather than diffed against a static template.</p>\n<p>A <code>[ViewPart]</code> in a referenced project or a NuGet package reaches this, because the generator\ncollects definitions from the current compilation's syntax and IL carries no body. Reuse across an\nassembly boundary belongs in a component.</p>\n<h3 id=\"bcf3029\">BCF3029<a href=\"#bcf3029\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. Design-time syntax is written where nothing reads it, so it renders nothing and wires up no\nhandler.</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">void</span> OnSomething()\n{\n    <span class=\"comment\">// BCF3029: renders nothing, and DoThing is never called</span>\n    <span class=\"keyword\">var</span> card = Div.Class(<span class=\"string\">&quot;card&quot;</span>).OnClick(DoThing)[Span[<span class=\"string\">&quot;hello&quot;</span>]];\n}\n</pre></div>\n<p><code>Html.Div</code>, <code>.Class(...)</code>, <code>.OnClick(...)</code> and every other factory and decoration are inert. <code>View</code>\nis an empty struct, an element helper returns nothing, and a decoration returns its receiver\nunchanged. The generator reads the <em>syntax</em> you wrote, never the value, and it reads it in three\nplaces: a component's <code>Body</code>, a layout's <code>Chrome</code>, and the body of a <code>[ViewPart]</code> method.</p>\n<p>The same API is callable from anywhere, and nothing reads it outside those three places. It\ncompiles, but it emits no render-tree frames, so nothing is rendered and no event handler is\nregistered.</p>\n<p>Caching a value into a field or property of a design-time type is left alone. Only a local, a\ndiscard, or an argument is reported.</p>\n<h3 id=\"bcf3030\">BCF3030<a href=\"#bcf3030\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The call reaches a <code>View</code>-returning method that builds from the design-time surface but\ncarries no <code>[ViewPart]</code>, so it renders nothing.</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">static</span> View Card(<span class=\"keyword\">string</span> title) =&gt; Div.Class(<span class=\"string\">&quot;card&quot;</span>)[H2[title]];\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div[Card(<span class=\"string\">&quot;Hello&quot;</span>)];   <span class=\"comment\">// BCF3030</span>\n</pre></div>\n<p>Mark the method <code>[ViewPart]</code> if it is static, or make it a component. Without the attribute the\nmethod's result carries no fragment, so the call emits no frames.</p>\n<p>This is BCF3029 seen from the other side of the call. BCF3029 reports design-time syntax written\nwhere nothing reads it; this reports a call whose callee wrote design-time syntax that nothing read.</p>\n<h3 id=\"bcf3001\">BCF3001<a href=\"#bcf3001\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. State is mutated inside the design-time expression.</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body\n{\n    <span class=\"keyword\">get</span>\n    {\n        _renderCount++;               <span class=\"comment\">// BCF3001</span>\n        <span class=\"keyword\">return</span> Div[Span[$<span class=\"string\">&quot;{_renderCount}&quot;</span>]];\n    }\n}\n</pre></div><div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">void</span> OnShown() =&gt; _renderCount++;                      <span class=\"comment\">// what to write instead</span>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div[Span[$<span class=\"string\">&quot;{_renderCount}&quot;</span>]];\n</pre></div>\n<p>The getter is a projection of state to UI, and it is translated rather than run. Move the mutation\nto an event handler.</p>\n<p>Statements ahead of the return are translated too, so a mutation written in one of them is BCF3001\nas it always was.</p>\n<h3 id=\"bcf3015\">BCF3015<a href=\"#bcf3015\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. A type name in a design-time value expression could not be resolved and its spelling depends\non the source file's lexical context.</p>\n<p>Values are copied into a generated file that has no <code>using</code> directives. Resolved type names are\nrewritten as <code>global::</code>-qualified names; an unresolved context-dependent one cannot be normalized\nsafely.</p>\n<p>Fix the name, fully qualify it, move a source-generated type to a referenced project, or replace it\nwith a hand-written C# type. A reference already rooted at <code>global::</code> is preserved and left to\nordinary C# resolution. Generic type arguments are checked independently.</p>\n<h2 id=\"elements\">Elements<a href=\"#elements\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3009\">BCF3009<a href=\"#bcf3009\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The <code>Element</code> tag is not a compile-time constant string spelled like a tag name.</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">const</span> <span class=\"keyword\">string</span> Widget = <span class=\"string\">&quot;my-widget&quot;</span>;\n\nElement(Widget)                  <span class=\"comment\">// fine</span>\nElement(_kind + <span class=\"string\">&quot;-widget&quot;</span>)       <span class=\"comment\">// BCF3009: not a constant</span>\nElement(<span class=\"string\">&quot;&quot;</span>)                      <span class=\"comment\">// BCF3009: empty</span>\nElement(<span class=\"string\">&quot;my widget&quot;</span>)             <span class=\"comment\">// BCF3009: not spelled like a tag name</span>\n</pre></div>\n<p>A tag name is an ASCII letter, then ASCII letters, digits, <code>-</code>, <code>_</code> or <code>.</code>.</p>\n<p>The constant half keeps the element declarative: a computed tag is neither an injection risk nor a\nsequencing problem, but the element no longer names its tag where you wrote it.</p>\n<p>The spelling half is a translation break. A tag no element can be named renders as two different\nthings: prerendering writes it into markup where the HTML parser reinterprets it, while interactive\nrendering hands it to <code>createElement</code>, which rejects it and ends the circuit.</p>\n<h3 id=\"bcf3016\">BCF3016<a href=\"#bcf3016\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. Children were written on a void element.</p>\n<div class=\"csharp\"><pre>\nImg.Src(<span class=\"string\">&quot;/logo.png&quot;</span>)[<span class=\"string\">&quot;Logo&quot;</span>]     <span class=\"comment\">// BCF3016</span>\nElement(<span class=\"string\">&quot;img&quot;</span>)[<span class=\"string\">&quot;Logo&quot;</span>]           <span class=\"comment\">// BCF3016, same rule</span>\nImg.Src(<span class=\"string\">&quot;/logo.png&quot;</span>).Alt(<span class=\"string\">&quot;Logo&quot;</span>) <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>The thirteen void elements are <code>area</code>, <code>base</code>, <code>br</code>, <code>col</code>, <code>embed</code>, <code>hr</code>, <code>img</code>, <code>input</code>, <code>link</code>,\n<code>meta</code>, <code>source</code>, <code>track</code>, <code>wbr</code>.</p>\n<p>The children do not survive a round trip through HTML. Prerendering serializes a closing tag the\nparser does not accept, so the parser moves the children out and they become the element's\nsiblings. A stray <code>&lt;/br&gt;</code> is re-read as a start tag, so <code>Br[&quot;x&quot;]</code> prerenders as two <code>&lt;br&gt;</code>\nelements.</p>\n<p>Interactive rendering has no parser in between and puts the same children inside. One expression\nproduces two different DOM trees, and the page changes shape at hydration.</p>\n<p>Configure a void element with decorations and put content beside it.</p>\n<p>Both spellings are checked, the helper and <code>Element</code> with a void tag. Custom elements and unknown\ntags are not: <code>Element(&quot;img-viewer&quot;)[&quot;child&quot;]</code> is accepted, because there is no standard to read\ntheir content model out of.</p>\n<p>This is the limit of what the surface checks about HTML, and the limit is deliberate. BCF3016 is\ndecidable from the element tag by itself. Whether a particular child is allowed inside a particular\nparent is not, so <code>Table[Div[&quot;x&quot;]]</code> is accepted along with attributes an element does not define.</p>\n<h3 id=\"bcf3027\">BCF3027<a href=\"#bcf3027\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. A declaration of your own took the simple name the element helper wanted.</p>\n<div class=\"csharp\"><pre>\n[Parameter] <span class=\"keyword\">public</span> <span class=\"keyword\">string</span> Data { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\nDiv[Data[<span class=\"string\">&quot;Heading&quot;</span>]]                          <span class=\"comment\">// BCF3027, a member</span>\n\n<span class=\"keyword\">public</span> <span class=\"keyword\">sealed</span> <span class=\"keyword\">class</span> Table;                    <span class=\"comment\">// Table[&quot;x&quot;]   — BCF3027, a type</span>\n<span class=\"keyword\">namespace</span> MyApp.Article { }                   <span class=\"comment\">// Article[&quot;x&quot;] — BCF3027, a namespace</span>\n<span class=\"keyword\">private</span> <span class=\"keyword\">string</span> Summary() =&gt; <span class=\"string\">&quot;&quot;</span>;               <span class=\"comment\">// Summary[&quot;x&quot;] — BCF3027, a method</span>\n\nDiv[Html.Data[<span class=\"string\">&quot;Heading&quot;</span>]]                     <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p><code>using static BlazorCodeFirst.Html;</code> imports every conforming HTML element name, and a declaration\nof your own wins simple-name lookup over an imported one. Blazor parameters named <code>Label</code>, <code>Data</code>,\n<code>Summary</code> or <code>Source</code> are ordinary, so this happens.</p>\n<p>C# has an error for every one of these — CS1503 on the index argument, CS0119, CS0118, CS0021 — and\nnone of them is reported. As long as the body does not translate, the component has no generated\n<code>RenderView</code>, so the compiler stops before it binds method bodies, which is where all four are\nfound.</p>\n<h2 id=\"decorations\">Decorations<a href=\"#decorations\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3008\">BCF3008<a href=\"#bcf3008\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. A decoration was applied to something that opens no element.</p>\n<div class=\"csharp\"><pre>\nIf(_open, () =&gt; Div[<span class=\"string\">&quot;x&quot;</span>]).Class(<span class=\"string\">&quot;card&quot;</span>)   <span class=\"comment\">// BCF3008</span>\nDiv[<span class=\"string\">&quot;text&quot;</span>].Class(<span class=\"string\">&quot;card&quot;</span>)                 <span class=\"comment\">// BCF3008: the brackets already produced a View</span>\nDiv.Class(<span class=\"string\">&quot;card&quot;</span>)[<span class=\"string\">&quot;text&quot;</span>]                 <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>A decoration folds into the owning element's attributes, so it needs an element to attach to.\n<code>If</code>, <code>ForEach</code>, <code>Fragment</code>, <code>Raw</code>, and a <code>[ViewPart]</code> or component result open none.</p>\n<h3 id=\"bcf3026\">BCF3026<a href=\"#bcf3026\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The name written in a decoration's position is not one this library declares.</p>\n<div class=\"csharp\"><pre>\nDiv.Clas(<span class=\"string\">&quot;card&quot;</span>)     <span class=\"comment\">// BCF3026</span>\nDiv.Class(<span class=\"string\">&quot;card&quot;</span>)    <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>A misspelling reaches this, and so does an extension method of your own that takes an element and\ngives one back. C# has an error for the misspelling, and the same declaration-stage stop prevents it\nbeing reported.</p>\n<h3 id=\"bcf3010\">BCF3010<a href=\"#bcf3010\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. An attribute or event is bound more than once on one element.</p>\n<div class=\"csharp\"><pre>\nInput.Type(<span class=\"string\">&quot;text&quot;</span>).Attr(<span class=\"string\">&quot;value&quot;</span>, _a).Attr(<span class=\"string\">&quot;value&quot;</span>, _b)   <span class=\"comment\">// BCF3010</span>\nInput.Type(<span class=\"string\">&quot;text&quot;</span>).Attr(<span class=\"string\">&quot;value&quot;</span>, _b)                     <span class=\"comment\">// what to write instead</span>\nDiv.Class(<span class=\"string\">&quot;card&quot;</span>).Class(<span class=\"string\">&quot;is-open&quot;</span>)                       <span class=\"comment\">// fine: class folds</span>\n</pre></div>\n<p>Two bindings in the attribute channel discard the earlier one, because the last write wins. One\nname bound through the attribute channel and once through the event channel keeps both, so an inline\nhandler and a C# handler each fire on every event. Neither is what you wrote.</p>\n<p><code>class</code> is the sole exception: <code>.Class</code> and <code>.Attr(&quot;class&quot;, …)</code> fold into one space-joined\nattribute. <code>style</code> is not an exception, so two of them on one element is BCF3010.</p>\n<h3 id=\"bcf3011\">BCF3011<a href=\"#bcf3011\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The <code>.Attr</code> name or <code>.On</code> event name is not a non-empty compile-time constant string.</p>\n<div class=\"csharp\"><pre>\nDiv.Attr(_name, <span class=\"string\">&quot;x&quot;</span>)          <span class=\"comment\">// BCF3011</span>\nDiv.Attr(<span class=\"string\">&quot;data-kind&quot;</span>, <span class=\"string\">&quot;x&quot;</span>)    <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>The name lowers to a literal, and holding it to a constant is also what makes class folding and\nduplicate-binding detection possible.</p>\n<h3 id=\"bcf3023\">BCF3023<a href=\"#bcf3023\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. A decoration written on <code>class</code> carries a value the class channel cannot join as text.</p>\n<div class=\"csharp\"><pre>\nDiv.Attr(<span class=\"string\">&quot;class&quot;</span>, _selected)                     <span class=\"comment\">// BCF3023</span>\nDiv.Attr(<span class=\"string\">&quot;class&quot;</span>)                                <span class=\"comment\">// BCF3023: a presence has no text</span>\nDiv.Class(_selected ? <span class=\"string\">&quot;is-selected&quot;</span> : <span class=\"keyword\">null</span>)      <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>The class channel joins its decorations into one value as text, so <code>class</code> takes a string and\nnothing else. The <code>bool</code> overload of <code>.Attr</code> is Blazor's conditional-attribute form, and the bare\n<code>.Attr(name)</code> spelling stands for a presence; neither is text.</p>\n<p>The value would otherwise translate two different ways. With one class decoration on the element the\nchannel emits the value alone, so <code>true</code> renders <code>class=&quot;&quot;</code> and empties the class list. With two or\nmore the channel joins them with <code>+</code>, so the same <code>true</code> renders <code>class=&quot;a True&quot;</code>. One spelling\nmeaning two things depending on a count written elsewhere in the chain is the defect.</p>\n<h3 id=\"bcf3024\">BCF3024<a href=\"#bcf3024\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. One element carries both a class-channel decoration and a <code>.Bind</code> on <code>class</code>.</p>\n<div class=\"csharp\"><pre>\nDiv.Class(<span class=\"string\">&quot;card&quot;</span>).Bind(<span class=\"string\">&quot;class&quot;</span>, <span class=\"string\">&quot;onchange&quot;</span>, () =&gt; _classes)   <span class=\"comment\">// BCF3024</span>\n</pre></div>\n<p><code>.Class</code> and <code>.Attr(&quot;class&quot;, …)</code> fold into a single attribute. A <code>.Bind</code> on the same name does not\njoin that fold; it emits its own frame, so the element is emitted with <code>class</code> twice.</p>\n<p>Which one survives has no single answer: prerendered markup is resolved by the HTML parser, which\nkeeps the first, while an interactive render applies them through the DOM, where the last write\nstands.</p>\n<p>Supply the whole class value from one place. Bind it alone and let the getter carry everything, or\ndrop the binding and use the decorations.</p>\n<h3 id=\"bcf3033\">BCF3033<a href=\"#bcf3033\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The same non-attribute decoration is written twice on one node.</p>\n<div class=\"csharp\"><pre>\nDiv.Key(row.Id).Key(row.Slug)[<span class=\"string\">&quot;x&quot;</span>]   <span class=\"comment\">// BCF3033</span>\nDiv.Key(row.Id)[<span class=\"string\">&quot;x&quot;</span>]                 <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p><code>.Key</code> and its siblings each occupy a channel that holds one value. All three break differently, and\nnone of them breaks visibly:</p>\n<ul>\n<li><code>SetKey</code> writes into the open frame, so the second call overwrites the first.</li>\n<li><code>AddComponentRenderMode</code> appends, and the renderer reads the first frame it finds, so there the\nsecond one is ignored.</li>\n<li>A reference capture appends too, and both actions run.</li>\n</ul>\n<p>Write the decoration once, with the value the node should carry. Two candidate keys mean the\nidentity is not decided, and the source is the only place where deciding it is visible.</p>\n<h3 id=\"bcf3034\">BCF3034<a href=\"#bcf3034\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The component's own declaration fixes its render mode, so the call site cannot set one.</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Counter&gt;().RenderMode(RenderMode.InteractiveWebAssembly)   <span class=\"comment\">// BCF3034 if Counter declares one</span>\n</pre></div>\n<p>The framework rejects the pair: <code>ComponentFactory</code> throws when a type carrying a\n<code>RenderModeAttribute</code> also receives a caller-specified mode. The call-site form exists for a\ncomponent that declares no mode of its own, which is the case where it is needed: the same component\nrendered interactively from one page and statically from another.</p>\n<p>Drop the <code>.RenderMode</code> at the call site and let the component's own attribute apply. If the mode\ngenuinely has to vary by caller, remove the attribute from the component instead, and then every\ncall site must name a mode.</p>\n<h2 id=\"events\">Events<a href=\"#events\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3019\">BCF3019<a href=\"#bcf3019\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The event name does not begin with <code>on</code>.</p>\n<div class=\"csharp\"><pre>\nInput.On(<span class=\"string\">&quot;input&quot;</span>, (ChangeEventArgs e) =&gt; …)     <span class=\"comment\">// BCF3019</span>\nInput.On(<span class=\"string\">&quot;oninput&quot;</span>, (ChangeEventArgs e) =&gt; …)   <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>Blazor's event attribute names always begin with <code>on</code>, and the prefix is never added for you. A name\nwithout it reaches <code>AddAttribute</code> as an ordinary attribute, so the handler is never called and\nnothing reports it at runtime.</p>\n<p>On <code>.Bind</code> this does a second job. The attribute name and the event name are adjacent string\narguments, so swapping them compiles; this is what stops a swapped pair.</p>\n<h3 id=\"bcf3028\">BCF3028<a href=\"#bcf3028\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The handler's argument type is not one the named event delivers.</p>\n<div class=\"csharp\"><pre>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (MouseEventArgs e) =&gt; Zoom(e.ClientX, e.ClientY))[<span class=\"string\">&quot;Zoom&quot;</span>]   <span class=\"comment\">// the delivered type</span>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (EventArgs e) =&gt; Save())[<span class=\"string\">&quot;Save&quot;</span>]                            <span class=\"comment\">// a base of it: fine</span>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (KeyboardEventArgs e) =&gt; Save())[<span class=\"string\">&quot;Save&quot;</span>]                    <span class=\"comment\">// BCF3028</span>\n</pre></div>\n<p>Blazor dispatches an event by casting its argument object to the handler's argument type, so a base\nof the delivered type is accepted and a sibling is not. A type that is not an <code>EventArgs</code> at all is\nthe same diagnostic.</p>\n<p>The mapping is read from the <code>[EventHandler]</code> metadata the framework ships and from any registration\nin the compilation being built. An event with no entry has no mapping and is not checked:</p>\n<div class=\"csharp\"><pre>\n[EventHandler(<span class=\"string\">&quot;onrate&quot;</span>, <span class=\"keyword\">typeof</span>(RatingEventArgs))]\n<span class=\"keyword\">public</span> <span class=\"keyword\">static</span> <span class=\"keyword\">class</span> AppEventHandlers;\n</pre></div><h3 id=\"bcf3035\">BCF3035<a href=\"#bcf3035\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. An event modifier has no event before it on the element.</p>\n<div class=\"csharp\"><pre>\nForm.PreventDefault().On(<span class=\"string\">&quot;onsubmit&quot;</span>, () =&gt; Save())   <span class=\"comment\">// BCF3035</span>\nForm.On(<span class=\"string\">&quot;onsubmit&quot;</span>, () =&gt; Save()).PreventDefault()   <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p><code>.PreventDefault</code> and <code>.StopPropagation</code> attach to the event written before them, which is the only\nreading a chain offers: the decorations carry no event name of their own.</p>\n<h3 id=\"bcf3036\">BCF3036<a href=\"#bcf3036\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The same event modifier is written twice for one event.</p>\n<div class=\"csharp\"><pre>\nForm.On(<span class=\"string\">&quot;onsubmit&quot;</span>, () =&gt; Save()).PreventDefault().PreventDefault()   <span class=\"comment\">// BCF3036</span>\nForm.On(<span class=\"string\">&quot;onsubmit&quot;</span>, () =&gt; Save()).PreventDefault()                    <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>One of the two has no effect whichever way the model takes it, and which one is not visible at the\ncall site.</p>\n<p>Write the modifier once. It is a flag rather than a value, so a second one requests nothing the\nfirst did not already do.</p>\n<h3 id=\"bcf3038\">BCF3038<a href=\"#bcf3038\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The event's own <code>[EventHandler]</code> registration disables that modifier.</p>\n<p>Blazor gates each modifier per event, and the renderer ignores an attribute the registration\ndisabled. Remove the modifier; the event itself is correct and stays.</p>\n<h2 id=\"control-flow\">Control flow<a href=\"#control-flow\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3002\">BCF3002<a href=\"#bcf3002\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Warning. The <code>ForEach</code> key selector does not reference its item, so it cannot identify one.</p>\n<div class=\"csharp\"><pre>\nForEach(rows, key: r =&gt; <span class=\"number\">0</span>, content: r =&gt; Li[r.Name])          <span class=\"comment\">// BCF3002</span>\nForEach(rows, key: r =&gt; r.Id, content: r =&gt; Li[r.Name])       <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>A key derived from the item is what lets Blazor preserve per-row state across insertion, removal,\nand reordering. A constant, an external index, or another list's item forces a full re-render.</p>\n<p>The check is deliberately conservative: it does not detect an item-derived key that is index-like in\npractice.</p>\n<h3 id=\"bcf3003\">BCF3003<a href=\"#bcf3003\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The <code>ForEach</code> content root is not a single element or component, so the key has nothing to\nattach to.</p>\n<div class=\"csharp\"><pre>\nForEach(rows, key: r =&gt; r.Id, content: r =&gt; If(r.Visible, () =&gt; Li[r.Name]))   <span class=\"comment\">// BCF3003</span>\nForEach(rows, key: r =&gt; r.Id, content: r =&gt; Li[If(r.Visible, () =&gt; Span[r.Name])])   <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>The key is applied to the content root's frame, and <code>SetKey</code> keys the currently open element or\ncomponent frame. A bare <code>If</code>, a nested <code>ForEach</code>, bare text, a <code>Fragment</code>, a <code>Raw</code>, and an\nexternally supplied <code>RenderFragment</code> all open no single keyable frame.</p>\n<p>Wrap the content in a container element. A <code>ForEach</code> that declines its key with <code>key: null</code> emits no\n<code>SetKey</code>, so those roots are allowed there.</p>\n<h3 id=\"bcf3004\">BCF3004<a href=\"#bcf3004\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The <code>ForEach</code> key or content has a shape the generator cannot sequence.</p>\n<p>The key body is copied into the <code>SetKey</code> call, so it has to be an expression. The content is given\none static sequence space that every iteration reuses, which a second return or a native control\nstatement would each need their own copy of.</p>\n<p>Content accepts an expression lambda, a block with one trailing <code>return</code>, and a single-parameter\n<code>View</code>-returning method group.</p>\n<p>The key body and the content body follow the same reserved-name rule <a href=\"#bcf1004\">BCF1004</a> states\nfor its getter.</p>\n<h3 id=\"bcf3032\">BCF3032<a href=\"#bcf3032\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The <code>ForEach</code> content root writes its own <code>.Key</code> while the loop also applies one.</p>\n<div class=\"csharp\"><pre>\nForEach(rows, key: r =&gt; r.Id, content: r =&gt; Li.Key(r.Id)[r.Name])   <span class=\"comment\">// BCF3032</span>\n</pre></div>\n<p>Two <code>SetKey</code> calls land on one frame, of which the second wins, so which key is authoritative\ndepends on emission order rather than on anything at the call site. Key the root or key the loop.</p>\n<h2 id=\"components\">Components<a href=\"#components\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3005\">BCF3005<a href=\"#bcf3005\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The parameter selector is not a simple property selection on its own lambda parameter.</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Card&gt;().Param(c =&gt; (<span class=\"keyword\">string</span>)c.Label, <span class=\"string\">&quot;x&quot;</span>)   <span class=\"comment\">// BCF3005</span>\nComponent&lt;Card&gt;().Param(c =&gt; c.Label, <span class=\"string\">&quot;x&quot;</span>)           <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>The generator reads the parameter's name out of the selector's spelling, so a cast, a method call, a\nnull-conditional access, or a member of a captured variable has no name to read. <code>.Param</code>,\n<code>.Template</code>, and <code>.Bind</code> all take that same selector.</p>\n<h3 id=\"bcf3006\">BCF3006<a href=\"#bcf3006\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The selected property is not a settable <code>[Parameter]</code>.</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">string</span> Label { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }              <span class=\"comment\">// BCF3006: no [Parameter]</span>\n[Parameter] <span class=\"keyword\">public</span> <span class=\"keyword\">string</span> Label { <span class=\"keyword\">get</span>; }       <span class=\"comment\">// BCF3006: no setter</span>\n\n[Parameter] <span class=\"keyword\">public</span> <span class=\"keyword\">string</span> Label { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }  <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>Only a property marked <code>[Parameter]</code> with an accessible setter can be bound. Setting anything else\nwould throw when Blazor applies the parameters.</p>\n<p>Mark the property <code>[Parameter]</code> and give it an accessible setter. A value the component should not\nreceive from its caller belongs in a field rather than in a parameter.</p>\n<h3 id=\"bcf3007\">BCF3007<a href=\"#bcf3007\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The chain binds the same parameter more than once.</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Card&gt;().Param(c =&gt; c.Label, <span class=\"string\">&quot;a&quot;</span>).Param(c =&gt; c.Label, <span class=\"string\">&quot;b&quot;</span>)   <span class=\"comment\">// BCF3007</span>\nComponent&lt;Card&gt;().Param(c =&gt; c.Label, <span class=\"string\">&quot;b&quot;</span>)                            <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>Every channel counts: <code>.Param</code>, <code>.Template</code>, <code>.Bind</code>, and child content written in brackets. Blazor\napplies the last write, so the earlier value is discarded.</p>\n<p>Bind the parameter once, with the value the component should end up with. A value that depends on\nstate belongs in the expression you pass, not in a second <code>.Param</code>.</p>\n<h3 id=\"bcf3012\">BCF3012<a href=\"#bcf3012\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The type argument did not resolve while the generator ran.</p>\n<p>The usual cause is a <code>.razor</code> component declared in the same project. The Razor compiler is itself a\nsource generator, and source generators cannot observe each other's output, so the type is\nunresolved here even though it exists in the final compilation.</p>\n<p>Move it to a referenced project, write it as a hand-authored C# component, or fix the name. The same\ncomponent in a referenced project or a NuGet package resolves normally.</p>\n<p>A typo, an inaccessible type, an ambiguous name, or a missing <code>using</code> reaches this too, and a C#\nresolution error is reported at the same position.</p>\n<h3 id=\"bcf3013\">BCF3013<a href=\"#bcf3013\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. Child content was written in brackets on a component that cannot receive it.</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Panel&gt;()[<span class=\"string\">&quot;body&quot;</span>]                                  <span class=\"comment\">// BCF3013 if Panel has no ChildContent</span>\nComponent&lt;Panel&gt;().Param(c =&gt; c.Content, Span[<span class=\"string\">&quot;body&quot;</span>])      <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>Brackets bind to a parameter named <code>ChildContent</code>, mirroring how Razor lowers nested content. It has\nto be a settable <code>[Parameter]</code> typed <code>RenderFragment</code> or <code>RenderFragment&lt;TContext&gt;</code>; the generic one\nreceives the children with its context discarded.</p>\n<h3 id=\"bcf3014\">BCF3014<a href=\"#bcf3014\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. An inert design-time value was passed to the generic <code>Param</code>.</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Card&gt;().Param(c =&gt; c.Body, Div[<span class=\"string\">&quot;x&quot;</span>])              <span class=\"comment\">// BCF3014</span>\nComponent&lt;Card&gt;().Param(c =&gt; c.Body, () =&gt; Div[<span class=\"string\">&quot;x&quot;</span>])        <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p><code>View</code> and <code>ComponentView&lt;T&gt;</code> are empty markers read by the generator, not runtime values. The\ngeneric <code>Param</code> emits its value expression verbatim, so binding one assigns the marker: an\n<code>object</code>-typed parameter accepts it with no exception and renders wrong output, while a typed\nparameter throws an invalid cast when Blazor applies parameters.</p>\n<h3 id=\"bcf3022\">BCF3022<a href=\"#bcf3022\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The contextual <code>.Template</code> content is not an inline expression lambda.</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Grid&lt;Row&gt;&gt;().Template(c =&gt; c.RowTemplate, RenderRow)          <span class=\"comment\">// BCF3022</span>\nComponent&lt;Grid&lt;Row&gt;&gt;().Template(c =&gt; c.RowTemplate, row =&gt; Td[row.Name]) <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>A method group, an anonymous method, and a block-bodied lambda all hide the content behind a call,\nleaving no expression to sequence and no parameter symbol to substitute the generated context\nvariable for.</p>\n<p>The content follows the same reserved-name rule <a href=\"#bcf1004\">BCF1004</a> states for its getter.</p>\n<h3 id=\"bcf3025\">BCF3025<a href=\"#bcf3025\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. <code>Slot</code> is written outside the body of a content-taking <code>[ViewPart]</code>, or named other than\nexactly once.</p>\n<div class=\"csharp\"><pre>\n[ViewPart]\n<span class=\"keyword\">public</span> <span class=\"keyword\">static</span> SlotView Panel(View heading) =&gt;\n    Section[heading, Div.Class(<span class=\"string\">&quot;body&quot;</span>)[Slot]];   <span class=\"comment\">// fine</span>\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div[Slot];       <span class=\"comment\">// BCF3025: Body receives no brackets</span>\n</pre></div>\n<p><code>Slot</code> marks where a part places the content its caller supplied in brackets, so it means nothing\nwhere there is no caller content: a component's <code>Body</code> or <code>Chrome</code> receives no brackets, and a part\nreturning <code>View</code> is called without them.</p>\n<p>A part that takes content declares <code>SlotView</code> as its return type and names <code>Slot</code> exactly once.\nNaming it twice would emit the caller's content twice; not naming it at all would discard content\nthe caller was required to supply.</p>\n<h2 id=\"two-way-binding\">Two-way binding<a href=\"#two-way-binding\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3017\">BCF3017<a href=\"#bcf3017\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The <code>.Bind</code> getter is not an inline lambda with an expression body.</p>\n<div class=\"csharp\"><pre>\nInput.Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, GetName)          <span class=\"comment\">// BCF3017</span>\nInput.Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _name)      <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>The getter's body is copied into two places, once as the bound attribute's value and once as the\nbinder's current value, so it has to be available as an expression. A block-bodied lambda and a\nmethod group both hide it behind a call.</p>\n<p>The setter argument carries no such restriction, because it is handed to <code>EventCallback</code> whole and\nnever taken apart.</p>\n<h3 id=\"bcf3018\">BCF3018<a href=\"#bcf3018\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The getter-only <code>.Bind</code>'s getter body cannot be assigned to, so no setter can be derived.</p>\n<div class=\"csharp\"><pre>\nInput.Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; Name.Trim())                          <span class=\"comment\">// BCF3018</span>\nInput.Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; Name, v =&gt; Name = v.Trim())           <span class=\"comment\">// what to write instead</span>\n</pre></div>\n<p>The getter-only form derives its setter by placing the getter's body on the left of an assignment,\nso that body has to be a field, a settable property, or an element access whose indexer has a\nsetter.</p>\n<p>A setter existing is not the same as the derived assignment being able to call it. The derived\nsetter is a lambda, so an <code>init</code> accessor is out of reach: C# admits one only in an object\ninitializer, a constructor, or another <code>init</code> accessor. A setter declared narrower than the property\nthat carries it is out of reach too, this time depending on where the assignment lands.\n<code>{ get; private set; }</code> on the component itself is accepted, because the generated <code>RenderView</code> is\nemitted into a partial of that same class; the same property on another type is not.</p>\n<p>A local, a parameter, and a <code>ForEach</code> iteration variable are rejected even though C# would assign to\nthem: the design-time expression is a property getter, so those go out of scope with each render and\nthe write-back would not survive to the next one. A member of an iteration variable is accepted,\nbecause it writes through to the element in the source list.</p>\n<h3 id=\"bcf3020\">BCF3020<a href=\"#bcf3020\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. The component declares no matching change callback, so a two-way binding has nowhere to write\nback.</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Field&gt;().Bind(c =&gt; c.Value, () =&gt; _query)   <span class=\"comment\">// BCF3020 without ValueChanged</span>\nComponent&lt;Field&gt;().Param(c =&gt; c.Value, _query)        <span class=\"comment\">// what to write instead, one way</span>\n</pre></div>\n<p>Component binding derives its parameter names rather than taking them from you, which is the\nopposite of the element surface. That is sound only because the derivation can be checked: the\ncomponent's type is known, so the generator looks up <code>{name}Changed</code> and reports this when it is\nabsent or carries the wrong type.</p>\n<p>Element binding has no such check available, which is why it makes you write both names.</p>\n<h3 id=\"bcf3031\">BCF3031<a href=\"#bcf3031\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. <code>.Bind</code> writes a format for a value type the framework declares no format-taking converter\nfor.</p>\n<div class=\"csharp\"><pre>\nInput.Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _count, format: <span class=\"string\">&quot;N0&quot;</span>)   <span class=\"comment\">// BCF3031</span>\n</pre></div>\n<p><code>BindConverter.FormatValue</code> and <code>CreateBinder</code> declare their format-taking overloads for <code>DateTime</code>,\n<code>DateTimeOffset</code>, <code>DateOnly</code>, <code>TimeOnly</code> and their nullable forms only. A format on anything else\nwould leave the generated file with a call that does not bind, and that C# error is raised inside\ngenerated code rather than in the source you wrote.</p>\n<p>Drop the format, or format the value in the getter and parse it in an explicit setter. The set is\nread from the framework's own metadata rather than enumerated by this compiler, and the culture is\nnot in question: every type this surface binds may carry one.</p>\n<h2 id=\"next\">Next<a href=\"#next\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Back to <a href=\"/docs/getting-started\">getting started</a>, or read the <a href=\"/docs/elements-and-decorations\">element\nvocabulary</a>.</p>\n"),
        new DocEntry(
            "faq",
            "FAQ",
            "Questions this surface's shape raises, such as why there is no VStack or typed padding, and where each answer is settled.",
            110,
            "reference",
            "en",
            false,
            ["why-is-there-no-vstack-padding-or-text", "can-i-keep-my-razor-files", "does-it-work-with-mudblazor-radzen-or-any-other-component-library", "what-does-it-cost-at-runtime", "why-must-the-class-be-partial-and-top-level", "why-cant-i-write-a-normal-if-or-foreach-in-body", "why-does-foreach-make-me-pass-a-key", "is-raw-safe", "the-build-stopped-and-i-do-not-recognize-the-id", "where-do-i-look-when-something-renders-differently-from-what-i-wrote"],
            "<p>Questions this surface's shape raises, and where each answer is settled.</p>\n<h2 id=\"why-is-there-no-vstack-padding-or-text\">Why is there no <code>VStack</code>, <code>.Padding()</code> or <code>Text()</code>?<a href=\"#why-is-there-no-vstack-padding-or-text\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Because this is not that kind of code-first. The surface mirrors HTML: every element you write is\nthe element it produces, CSS does the layout, and a bare string is a text node.</p>\n<p>A second vocabulary would mean learning it, mapping it back to HTML when something renders wrong,\nand maintaining it as HTML and CSS move. <code>DESIGN.md</code> §4.1 records the lineage this follows and why\nthe SwiftUI one was declined.</p>\n<h2 id=\"can-i-keep-my-razor-files\">Can I keep my <code>.razor</code> files?<a href=\"#can-i-keep-my-razor-files\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Yes, in both directions. A <code>.razor</code> file names one of these components as an ordinary tag, and one\nof these calls a <code>.razor</code> component through <code>Component&lt;T&gt;()</code>.</p>\n<p>The one restriction is same-project: <code>Component&lt;T&gt;()</code> cannot name a <code>.razor</code> type declared in the\nsame project, because source generators cannot observe each other's output\n(<a href=\"/docs/diagnostics#bcf3012\">BCF3012</a>). The same component in a referenced project resolves normally.\nSee <a href=\"/docs/components-and-reuse#calling-an-existing-razor-or-third-party-component\">components and reuse</a>.</p>\n<h2 id=\"does-it-work-with-mudblazor-radzen-or-any-other-component-library\">Does it work with MudBlazor, Radzen, or any other component library?<a href=\"#does-it-work-with-mudblazor-radzen-or-any-other-component-library\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Yes. Those are ordinary Blazor components in referenced assemblies, which is exactly the case\n<code>Component&lt;T&gt;()</code> is for. Parameters go through <code>.Param</code>, templates through <code>.Template</code>, and child\ncontent in brackets.</p>\n<h2 id=\"what-does-it-cost-at-runtime\">What does it cost at runtime?<a href=\"#what-does-it-cost-at-runtime\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Nothing beyond what a <code>.razor</code> component costs. The generator emits a <code>RenderTreeBuilder</code> method\nwith statically assigned sequence numbers, which is what the Razor compiler emits too.</p>\n<p>There is no runtime UI tree, no reflection, and no expression compilation. The design-time API you\nwrote the component with does not ship: the IL trimmer removes it.</p>\n<h2 id=\"why-must-the-class-be-partial-and-top-level\">Why must the class be <code>partial</code> and top-level?<a href=\"#why-must-the-class-be-partial-and-top-level\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>partial</code> because the generator writes the rendering into your class\n(<a href=\"/docs/diagnostics#bcf1001\">BCF1001</a>). Top-level because reopening a nested class from the generated\nfile would mean re-declaring every enclosing type, its type parameters included\n(<a href=\"/docs/diagnostics#bcf1005\">BCF1005</a>).</p>\n<h2 id=\"why-cant-i-write-a-normal-if-or-foreach-in-body\">Why can't I write a normal <code>if</code> or <code>foreach</code> in <code>Body</code>?<a href=\"#why-cant-i-write-a-normal-if-or-foreach-in-body\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Because each one would need a sequence space of its own, and the whole point of the compilation is\nthat every template position gets its number at build time. <code>If</code> and <code>ForEach</code> are that same control\nflow with the space made explicit.</p>\n<p>The getter reaches one returned expression, with locals allowed ahead of it\n(<a href=\"/docs/getting-started#the-getter-reaches-one-expression\">getting started</a>). If a body genuinely\ncannot be written that way, override <code>RenderView</code> by hand.</p>\n<h2 id=\"why-does-foreach-make-me-pass-a-key\">Why does <code>ForEach</code> make me pass a key?<a href=\"#why-does-foreach-make-me-pass-a-key\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Because a list that diffs by position reuses the wrong element state the moment it reorders, and\nthat is invisible until a user notices their input moved. The parameter has no default, so a list\neither identifies its items or writes <code>key: null</code> and accepts the cost explicitly\n(<a href=\"/docs/control-flow#declining-the-key\">declining the key</a>).</p>\n<h2 id=\"is-raw-safe\">Is <code>Raw</code> safe?<a href=\"#is-raw-safe\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Only for content you trust. It writes to the DOM without escaping, which is what <code>MarkupString</code>\ndoes in Razor. Never flow user input or an external response through it\n(<a href=\"/docs/control-flow#raw\">Raw</a>).</p>\n<h2 id=\"the-build-stopped-and-i-do-not-recognize-the-id\">The build stopped and I do not recognize the ID<a href=\"#the-build-stopped-and-i-do-not-recognize-the-id\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Every diagnostic has an entry in the <a href=\"/docs/diagnostics\">reference</a>, giving what it means and what to\nwrite instead. The build prints the ID; search that page for it.</p>\n<h2 id=\"where-do-i-look-when-something-renders-differently-from-what-i-wrote\">Where do I look when something renders differently from what I wrote<a href=\"#where-do-i-look-when-something-renders-differently-from-what-i-wrote\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>That is the case the compiler is built to prevent, so start with the diagnostics: it reports what it\ncannot translate rather than emitting something that differs. If nothing fired, the difference is\nbetween your expression and the HTML you expected, and\n<a href=\"/docs/elements-and-decorations\">elements and decorations</a> is where that correspondence is written\ndown.</p>\n"),
        new DocEntry(
            "getting-started",
            "はじめに",
            "ランタイムとソースジェネレーターを導入し、BodyComponentBase から派生したコンポーネントを描画するまで。",
            10,
            "start",
            "ja",
            false,
            ["導入", "最初のコンポーネント", "ゲッターが返すのは1つの式", "この-api-が読まれる場所", "ビルドが止まる理由", "次に読むもの"],
            "<p>BlazorCodeFirst を使うと、Blazor の UI を通常の C# として書けます。</p>\n<h2 id=\"導入\">導入<a href=\"#%E5%B0%8E%E5%85%A5\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>ランタイムとソースジェネレーターをプロジェクトに追加し、コンポーネントを <code>BodyComponentBase</code>\nから派生させます。</p>\n<pre><code>dotnet add package BlazorCodeFirst --prerelease\n</code></pre>\n<p>公開しているバージョンには prerelease の接尾辞が付いています。<code>--prerelease</code> を外すと、コマンドは最新の安定版を探します。安定版はまだないので、パッケージは復元されません。</p>\n<h2 id=\"最初のコンポーネント\">最初のコンポーネント<a href=\"#%E6%9C%80%E5%88%9D%E3%81%AE%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>コンポーネントは、プロパティを1つオーバーライドした <code>partial</code> クラスです。<code>partial</code> が必要なのは、ジェネレーターがそのクラスの中に描画を書き込むためです。トップレベルである必要があるのは、入れ子のクラスを生成ファイル側で開き直すには、外側の型の宣言を型引数まで含めて書き直さねばならないためです。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">using</span> Microsoft.AspNetCore.Components;\n<span class=\"keyword\">using</span> BlazorCodeFirst;\n<span class=\"keyword\">using</span> <span class=\"keyword\">static</span> BlazorCodeFirst.Html;\n\n[Route(<span class=\"string\">&quot;/&quot;</span>)]\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Home : BodyComponentBase\n{\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n        Div[\n            H1[<span class=\"string\">&quot;Hello&quot;</span>],\n            Span[<span class=\"string\">&quot;Welcome to BlazorCodeFirst.&quot;</span>]];\n}\n</pre></div>\n<p>この式は、生成される HTML をそのまま表します。属性は要素に繋げ、子ノードは角括弧に入れます。文字列をそのまま書くとテキストノードになります。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        H1[<span class=\"string\">&quot;Hello&quot;</span>],\n        Span[<span class=\"string\">&quot;Welcome to BlazorCodeFirst.&quot;</span>]];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">h1</span><span class=\"htmlTagDelimiter\">&gt;</span>Hello<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">h1</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">span</span><span class=\"htmlTagDelimiter\">&gt;</span>Welcome to BlazorCodeFirst.<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">span</span><span class=\"htmlTagDelimiter\">&gt;</span>\n<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div><h2 id=\"ゲッターが返すのは1つの式\">ゲッターが返すのは1つの式<a href=\"#%E3%82%B2%E3%83%83%E3%82%BF%E3%83%BC%E3%81%8C%E8%BF%94%E3%81%99%E3%81%AE%E3%81%AF1%E3%81%A4%E3%81%AE%E5%BC%8F\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>書き方は3通りあり、どれも同じものへ翻訳されます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div[H1[<span class=\"string\">&quot;Hello&quot;</span>]];                    <span class=\"comment\">// これでよい</span>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body { <span class=\"keyword\">get</span> =&gt; Div[H1[<span class=\"string\">&quot;Hello&quot;</span>]]; }            <span class=\"comment\">// これでもよい</span>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body { <span class=\"keyword\">get</span> { <span class=\"keyword\">return</span> Div[H1[<span class=\"string\">&quot;Hello&quot;</span>]]; } }    <span class=\"comment\">// これでもよい</span>\n</pre></div>\n<p>その <code>return</code> の手前には、ローカル変数の宣言と式文を置けます。これらのステートメントは、生成される <code>RenderView</code> の中で、レンダーツリーのフレームを発行する呼び出しより前にそのまま出力されます。<code>ForEach</code> の <code>content</code> に書いたステートメントも、同じ位置に出力されます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body\n{\n    <span class=\"keyword\">get</span>\n    {\n        <span class=\"keyword\">var</span> greeting = $<span class=\"string\">&quot;Hello, {_name}&quot;</span>;\n        <span class=\"keyword\">return</span> Div[H1[greeting]];\n    }\n}\n</pre></div>\n<p>2つ目の <code>return</code> と C# 本来の制御構文は、それぞれ専用のシーケンス空間を必要とするため、どちらも受け付けません（<a href=\"/docs/ja/diagnostics#bcf1004\">BCF1004</a>）。本体がどうしてもこの形にならないなら、\n<code>RenderView</code> を手で書いてください。そのとき設計時の式は使われなくなり、何も報告されません。</p>\n<h2 id=\"この-api-が読まれる場所\">この API が読まれる場所<a href=\"#%E3%81%93%E3%81%AE-api-%E3%81%8C%E8%AA%AD%E3%81%BE%E3%82%8C%E3%82%8B%E5%A0%B4%E6%89%80\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>Html.Div</code>、<code>.Class(...)</code>、<code>.OnClick(...)</code> をはじめ、要素のファクトリと装飾は、それ自体では何もしません。<code>View</code> は空の構造体で、要素ヘルパーは何も返さず、装飾はレシーバーをそのまま返すだけです。ジェネレーターが読むのは書かれた <em>構文</em> であって、値ではありません。読む場所も3つしかありません。コンポーネントの <code>Body</code>、レイアウトの <code>Chrome</code>、そして <code>[ViewPart]</code> メソッドの本体です。</p>\n<p>同じ API はどこからでも呼べますが、この3か所の外では誰も読みません。イベントハンドラー、サービス、ヘルパーメソッドのどこに書いてもコンパイルは通ります。ただしレンダーツリーのフレームを\n1つも出さないので、何も描画されず、イベントハンドラーも登録されません。これが\n<a href=\"/docs/ja/diagnostics#bcf3029\">BCF3029</a> で、呼び出し側から見た同じ誤りが\n<a href=\"/docs/ja/diagnostics#bcf3030\">BCF3030</a> です。</p>\n<h2 id=\"ビルドが止まる理由\">ビルドが止まる理由<a href=\"#%E3%83%93%E3%83%AB%E3%83%89%E3%81%8C%E6%AD%A2%E3%81%BE%E3%82%8B%E7%90%86%E7%94%B1\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>コンパイラは、<code>RenderTreeBuilder</code> の呼び出しへ翻訳できない式を報告します。書いたものと違う描画になるコードを出すより、そこで止めるためです。診断はすべて<a href=\"/docs/ja/diagnostics\">リファレンス</a>に項があり、よく出るのは次の5つです。</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><a href=\"/docs/ja/diagnostics#bcf1001\">BCF1001</a></td>\n<td>クラスが <code>partial</code> でない</td>\n</tr>\n<tr>\n<td><a href=\"/docs/ja/diagnostics#bcf1005\">BCF1005</a></td>\n<td>クラスが入れ子になっている</td>\n</tr>\n<tr>\n<td><a href=\"/docs/ja/diagnostics#bcf1004\">BCF1004</a></td>\n<td>ゲッターが1つの返り値の式に収まらない</td>\n</tr>\n<tr>\n<td><a href=\"/docs/ja/diagnostics#bcf1002\">BCF1002</a></td>\n<td>生成ファイルから見えないローカル変数を式が参照している</td>\n</tr>\n<tr>\n<td><a href=\"/docs/ja/diagnostics#bcf1003\">BCF1003</a></td>\n<td>ジェネレーターが読まない構文を式が使っている</td>\n</tr>\n</tbody>\n</table>\n<p>1つのクラスが <code>partial</code> の欠落とゲッターの問題を同時に持つことはありますが、報告されるのは一度に1つです。<code>partial</code> の検査が先に実行されるので、まず BCF1001 だけが出ます。修飾子を足すと、次に\nBCF1004 が出ます。</p>\n<h2 id=\"次に読むもの\">次に読むもの<a href=\"#%E6%AC%A1%E3%81%AB%E8%AA%AD%E3%82%80%E3%82%82%E3%81%AE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<ul>\n<li><a href=\"/counter\">カウンターの実例</a>で、イベント、<code>If</code>、キー付き <code>ForEach</code> の動きを見る。</li>\n<li><a href=\"/docs/ja/elements-and-decorations\">要素と装飾</a>で書ける要素の一覧を、<a href=\"/docs/ja/control-flow#if\">制御構文</a>で条件分岐とリストを学ぶ。</li>\n</ul>\n"),
        new DocEntry(
            "installation-and-hosting",
            "導入とホスティング",
            "導入するパッケージ、必要なターゲットフレームワーク、そしてホスティングの判断のうち Blazor に委ねている部分。",
            20,
            "start",
            "ja",
            false,
            ["インストール", "必要なもの", "ホスティング方式はこのライブラリが決めるものではありません", "レンダーモードを指定する", "トリミングして配信する", "次に"],
            "<p>パッケージは1つ、ターゲットフレームワークも1つで、ホスティング方式ごとの設定もありません。このページでは、インストールの手順と、このライブラリが決めずに Blazor へ任せている事柄を説明します。</p>\n<h2 id=\"インストール\">インストール<a href=\"#%E3%82%A4%E3%83%B3%E3%82%B9%E3%83%88%E3%83%BC%E3%83%AB\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<pre><code>dotnet add package BlazorCodeFirst --prerelease\n</code></pre>\n<p>公開しているバージョンには prerelease の接尾辞が付いています。<code>--prerelease</code> を外すと、コマンドは最新の安定版を探します。安定版はまだないので、パッケージは復元されません。</p>\n<p>1つのパッケージに両方が入っています。ランタイムは <code>lib/net10.0</code> に、ジェネレーターとアナライザーは\n<code>analyzers/dotnet/cs</code> に入っています。追加するパッケージは他にありません。</p>\n<h2 id=\"必要なもの\">必要なもの<a href=\"#%E5%BF%85%E8%A6%81%E3%81%AA%E3%82%82%E3%81%AE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<ul>\n<li>.NET SDK 10.0.100 以降。</li>\n<li>IDE を使うなら Visual Studio 2026 バージョン 18.0 以降。</li>\n</ul>\n<p>ジェネレーターは Roslyn 5.0 のアナライザーとして配られ、それより古いコンパイラは読み込みを拒みます。</p>\n<p>ターゲットフレームワークのベースラインは <code>net10.0</code> で、全機能を備えています。</p>\n<h2 id=\"ホスティング方式はこのライブラリが決めるものではありません\">ホスティング方式はこのライブラリが決めるものではありません<a href=\"#%E3%83%9B%E3%82%B9%E3%83%86%E3%82%A3%E3%83%B3%E3%82%B0%E6%96%B9%E5%BC%8F%E3%81%AF%E3%81%93%E3%81%AE%E3%83%A9%E3%82%A4%E3%83%96%E3%83%A9%E3%83%AA%E3%81%8C%E6%B1%BA%E3%82%81%E3%82%8B%E3%82%82%E3%81%AE%E3%81%A7%E3%81%AF%E3%81%82%E3%82%8A%E3%81%BE%E3%81%9B%E3%82%93\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>作成したコンポーネントは、通常の <code>ComponentBase</code> 派生クラスの <code>RenderView</code> オーバーライドへコンパイルされます。Blazor はそれを Razor コンポーネントと同じように差分計算します。Server、\nWebAssembly、静的なサーバーサイドレンダリングは <code>.razor</code> の場合と同じように動作し、方式ごとの設定も不要です。</p>\n<p>このドキュメントサイト自体が実例です。WebAssembly アプリをビルド時にプリレンダリングし、静的ファイルとして配信しています。</p>\n<h2 id=\"レンダーモードを指定する\">レンダーモードを指定する<a href=\"#%E3%83%AC%E3%83%B3%E3%83%80%E3%83%BC%E3%83%A2%E3%83%BC%E3%83%89%E3%82%92%E6%8C%87%E5%AE%9A%E3%81%99%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>呼び出し側から、呼ぶコンポーネントのレンダーモードを指定できます。</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Counter&gt;().RenderMode(RenderMode.InteractiveWebAssembly)\n</pre></div>\n<p>この形は、自分ではモードを宣言しないコンポーネントのためにあります。必要になるのは、同じコンポーネントをあるページからは対話的に、別のページからは静的に描くときです。自身の宣言でモードを固定しているコンポーネントは、呼び出し側からの指定を拒みます（<a href=\"/docs/ja/diagnostics#bcf3034\">BCF3034</a>）。</p>\n<h2 id=\"トリミングして配信する\">トリミングして配信する<a href=\"#%E3%83%88%E3%83%AA%E3%83%9F%E3%83%B3%E3%82%B0%E3%81%97%E3%81%A6%E9%85%8D%E4%BF%A1%E3%81%99%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>実行時の UI ツリーはなく、リフレクションもなく、式のコンパイルもありません。そのためトリミングのルートも AOT のヒントも不要です。コンポーネントを書いた設計時の API は、配布物に残りません。ジェネレーターがその構文を読み、IL トリマーが本体を削ります。</p>\n<p>実測してある唯一のコストはバインドで、増えるのは配布サイズです。バインドの個数には比例せず、一度きりのおよそ 10 KB です。<a href=\"/docs/ja/two-way-binding#%E3%83%88%E3%83%AA%E3%83%A0%E3%81%97%E3%81%A6%E9%85%8D%E5%B8%83%E3%81%99%E3%82%8B%E5%A0%B4%E5%90%88\">双方向バインド</a>を読んでください。</p>\n<h2 id=\"次に\">次に<a href=\"#%E6%AC%A1%E3%81%AB\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<ul>\n<li><code>.razor</code> を書いてきたなら <a href=\"/docs/ja/from-razor\">Razor からの移行</a>。</li>\n<li>そうでなければ<a href=\"/docs/ja/getting-started\">はじめる</a>から。</li>\n</ul>\n"),
        new DocEntry(
            "from-razor",
            "Razor からの移行",
            "Razor 構文からこの API への対応表と、置き換えでは済まず、コンポーネントの形そのものが変わる4箇所。",
            30,
            "start",
            "ja",
            false,
            ["変わらないもの", "対応表", "置き換えでは済まない4点", "属性が子より先に来る", "ゲッターが返すのは1つの式", "キーは必須で外すなら明示する", "覚える名前は-html-の名前だけ", "コンポーネントを1つ書き直す", "次に読むもの"],
            "<p>このページには、Razor の書き方をこの API へ置き換える対応表と、その置き換えでは済まず、コンポーネントの形そのものが変わる4点を載せます。</p>\n<h2 id=\"変わらないもの\">変わらないもの<a href=\"#%E5%A4%89%E3%82%8F%E3%82%89%E3%81%AA%E3%81%84%E3%82%82%E3%81%AE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>ここで書くコンポーネントは Blazor のコンポーネントです。<code>BodyComponentBase</code> は <code>ComponentBase</code>\nから派生します。ライフサイクルメソッド、<code>[Parameter]</code>、<code>[Inject]</code>、<code>[CascadingParameter]</code> は、いま使っているものがそのまま使えます。<code>StateHasChanged</code> と <code>IDisposable</code> も同じです。<code>.razor</code>\nファイルからこのコンポーネントを呼べますし、その逆もできます（<a href=\"/docs/ja/components-and-reuse#%E6%97%A2%E5%AD%98%E3%81%AE-razor-%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%82%84%E3%82%B5%E3%83%BC%E3%83%89%E3%83%91%E3%83%BC%E3%83%86%E3%82%A3%E3%81%AE%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%82%92%E5%91%BC%E3%81%B6\">コンポーネントと再利用</a>）。</p>\n<h2 id=\"対応表\">対応表<a href=\"#%E5%AF%BE%E5%BF%9C%E8%A1%A8\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<table>\n<thead>\n<tr>\n<th>Razor</th>\n<th>ここ</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>@page &quot;/counter&quot;</code></td>\n<td><code>[Route(&quot;/counter&quot;)]</code></td>\n</tr>\n<tr>\n<td><code>@inject IJSRuntime Js</code></td>\n<td><code>[Inject] private IJSRuntime Js { get; set; }</code></td>\n</tr>\n<tr>\n<td><code>@code { … }</code></td>\n<td>通常のクラスメンバー</td>\n</tr>\n<tr>\n<td><code>&lt;div class=&quot;card&quot;&gt;…&lt;/div&gt;</code></td>\n<td><code>Div.Class(&quot;card&quot;)[…]</code></td>\n</tr>\n<tr>\n<td><code>&lt;img src=&quot;/x.png&quot; /&gt;</code></td>\n<td><code>Img.Src(&quot;/x.png&quot;)</code></td>\n</tr>\n<tr>\n<td><code>@onclick=&quot;Save&quot;</code></td>\n<td><code>.OnClick(() =&gt; Save())</code></td>\n</tr>\n<tr>\n<td><code>@bind=&quot;_name&quot;</code></td>\n<td><code>.Bind(&quot;value&quot;, &quot;oninput&quot;, () =&gt; _name)</code></td>\n</tr>\n<tr>\n<td><code>@if (x) { … } else { … }</code></td>\n<td><code>If(x, () =&gt; …, () =&gt; …)</code></td>\n</tr>\n<tr>\n<td><code>@foreach (var r in rows) { … }</code></td>\n<td><code>ForEach(rows, key: r =&gt; r.Id, content: r =&gt; …)</code></td>\n</tr>\n<tr>\n<td><code>@key=&quot;r.Id&quot;</code></td>\n<td><code>ForEach</code> の <code>key</code> 引数、または <code>.Key(…)</code></td>\n</tr>\n<tr>\n<td><code>@ref=&quot;_el&quot;</code></td>\n<td><code>.Ref(…)</code></td>\n</tr>\n<tr>\n<td><code>&lt;Card Title=&quot;x&quot; /&gt;</code></td>\n<td><code>Component&lt;Card&gt;().Param(c =&gt; c.Title, &quot;x&quot;)</code></td>\n</tr>\n<tr>\n<td><code>&lt;Card&gt;…&lt;/Card&gt;</code></td>\n<td><code>Component&lt;Card&gt;()[…]</code></td>\n</tr>\n<tr>\n<td><code>&lt;CascadingValue Value=&quot;@_t&quot;&gt;</code></td>\n<td><code>Component&lt;CascadingValue&lt;T&gt;&gt;().Param(c =&gt; c.Value, _t)[…]</code></td>\n</tr>\n<tr>\n<td><code>@((MarkupString)html)</code></td>\n<td><code>Raw(html)</code></td>\n</tr>\n<tr>\n<td><code>&lt;text&gt;…&lt;/text&gt;</code></td>\n<td><code>Fragment(…)</code></td>\n</tr>\n<tr>\n<td><code>@layout MainLayout</code></td>\n<td><code>[Layout(typeof(MainLayout))]</code>、そのまま</td>\n</tr>\n<tr>\n<td>レイアウトの <code>@Body</code></td>\n<td>オーバーライドした <code>Chrome</code> の中の <code>Body</code>（<a href=\"/docs/ja/layouts\">レイアウト</a>）</td>\n</tr>\n</tbody>\n</table>\n<h2 id=\"置き換えでは済まない4点\">置き換えでは済まない4点<a href=\"#%E7%BD%AE%E3%81%8D%E6%8F%9B%E3%81%88%E3%81%A7%E3%81%AF%E6%B8%88%E3%81%BE%E3%81%AA%E3%81%844%E7%82%B9\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"属性が子より先に来る\">属性が子より先に来る<a href=\"#%E5%B1%9E%E6%80%A7%E3%81%8C%E5%AD%90%E3%82%88%E3%82%8A%E5%85%88%E3%81%AB%E6%9D%A5%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Razor では、属性を開始タグのどこに書いてもよく、子はその後に続きます。この API では、装飾を要素に繋げてから、子を角括弧に入れます。角括弧はその時点で <code>View</code> を作り終えているので、その後ろに装飾を繋ぐことはできません（<a href=\"/docs/ja/diagnostics#bcf3008\">BCF3008</a>）。</p>\n<h3 id=\"ゲッターが返すのは1つの式\">ゲッターが返すのは1つの式<a href=\"#%E3%82%B2%E3%83%83%E3%82%BF%E3%83%BC%E3%81%8C%E8%BF%94%E3%81%99%E3%81%AE%E3%81%AF1%E3%81%A4%E3%81%AE%E5%BC%8F\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>.razor</code> ファイルは、文を書けるテンプレートです。<code>Body</code> が返すのは1つの式で、その手前にローカル変数を置けます。2つ目の <code>return</code> と C# の <code>if</code> 文は、それぞれ専用のシーケンス空間を必要とするため、どちらも受け付けません（<a href=\"/docs/ja/diagnostics#bcf1004\">BCF1004</a>）。</p>\n<p><code>If</code> と <code>ForEach</code> が C# のキーワードではなく構文として用意されているのも、同じ理由です。分岐のあるテンプレートを書き直す前に<a href=\"/docs/ja/control-flow\">制御構文</a>を読んでください。</p>\n<h3 id=\"キーは必須で外すなら明示する\">キーは必須で、外すなら明示する<a href=\"#%E3%82%AD%E3%83%BC%E3%81%AF%E5%BF%85%E9%A0%88%E3%81%A7%E5%A4%96%E3%81%99%E3%81%AA%E3%82%89%E6%98%8E%E7%A4%BA%E3%81%99%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Razor の <code>@key</code> は省略でき、書き忘れても気づきません。<code>ForEach</code> の <code>key</code> に既定値はないので、リストは項目を識別するか、<code>key: null</code> と書いて代償を引き受けるかのどちらかです。後者が<a href=\"/docs/ja/control-flow#%E3%82%AD%E3%83%BC%E3%82%92%E4%BD%BF%E3%82%8F%E3%81%AA%E3%81%84\">キーを使わない</a>書き方です。</p>\n<h3 id=\"覚える名前は-html-の名前だけ\">覚える名前は HTML の名前だけ<a href=\"#%E8%A6%9A%E3%81%88%E3%82%8B%E5%90%8D%E5%89%8D%E3%81%AF-html-%E3%81%AE%E5%90%8D%E5%89%8D%E3%81%A0%E3%81%91\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>どの要素も同じ名前の HTML 要素で、レイアウトは CSS が担います。<code>VStack</code> と <code>.Padding()</code> はありません。<code>Text()</code> もなく、文字列をそのまま書けばテキストノードです。HTML を知っていれば、要素について覚えることは他にありません。</p>\n<h2 id=\"コンポーネントを1つ書き直す\">コンポーネントを1つ書き直す<a href=\"#%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%82%921%E3%81%A4%E6%9B%B8%E3%81%8D%E7%9B%B4%E3%81%99\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>書き直すのはマークアップだけで、C# はそのままにします。<code>@code</code> のメンバーをクラス本体へ移し、テンプレートを <code>Body</code> ゲッターに書き換えます。置き換えられないものは、ビルドが指摘します。どの診断も代わりに書くコードを示し、<a href=\"/docs/ja/diagnostics\">リファレンス</a>に1件ずつ項があります。</p>\n<p>最初に出る間違いは機械的な2つです。1つはクラスに <code>partial</code> が付いていないこと（<a href=\"/docs/ja/diagnostics#bcf1001\">BCF1001</a>）、もう1つはゲッターの <code>return</code> の後ろに文が残っていること（<a href=\"/docs/ja/diagnostics#bcf1004\">BCF1004</a>）です。</p>\n<h2 id=\"次に読むもの\">次に読むもの<a href=\"#%E6%AC%A1%E3%81%AB%E8%AA%AD%E3%82%80%E3%82%82%E3%81%AE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<ul>\n<li>要素をひととおり見るなら<a href=\"/docs/ja/elements-and-decorations\">要素と装飾</a>。</li>\n<li>2種類のコンポーネントを1つのプロジェクトで混ぜるなら<a href=\"/docs/ja/components-and-reuse#razor-%E3%81%8B%E3%82%89-blazorcodefirst-%E3%81%AE%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%82%92%E4%BD%BF%E3%81%86\">コンポーネントと再利用</a>。</li>\n</ul>\n"),
        new DocEntry(
            "elements-and-decorations",
            "要素と装飾",
            "書いた要素がそのまま出力される要素になる。ヘルパーへの属性の連結と、角括弧に置く子要素の書き方。",
            40,
            "write",
            "ja",
            false,
            ["要素", "子に置けるもの", "空要素は子を取らない", "名前が衝突する場合", "装飾", "ハンドラー", "class-のチャネル", "装飾を書ける場所", "次に読むもの"],
            "<p>BlazorCodeFirst は HTML を直に写します。<code>Body</code> の式に書いた要素の名前が、そのまま出力される要素の名前です。HTML の要素名とは別に独自の部品名を覚える必要はなく、実行時の UI ツリーもありません。</p>\n<h2 id=\"要素\">要素<a href=\"#%E8%A6%81%E7%B4%A0\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>HTML の要素にはヘルパーがあります。名前はタグ名の先頭1文字だけを大文字にしたもので、<code>FigCaption</code>\nではなく <code>Figcaption</code>、同じく <code>Colgroup</code> と <code>Textarea</code> です。属性は要素に繋げ、子は角括弧に入れます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Figure[\n        Img.Src(<span class=\"string\">&quot;/diagram.png&quot;</span>).Alt(<span class=\"string\">&quot;Architecture&quot;</span>),\n        Figcaption[<span class=\"string\">&quot;The compilation pipeline&quot;</span>]];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">figure</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">img</span> <span class=\"htmlAttributeName\">src</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;/diagram.png&quot;</span> <span class=\"htmlAttributeName\">alt</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;Architecture&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">figcaption</span><span class=\"htmlTagDelimiter\">&gt;</span>The compilation pipeline<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">figcaption</span><span class=\"htmlTagDelimiter\">&gt;</span>\n<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">figure</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>HTML Living Standard が適合と認める要素には、すべて専用のヘルパーがあります。</p>\n<p><code>Element</code> は、ヘルパーの無い要素を受け持ちます。対象は2種類です。ひとつはカスタム要素と Web\nComponents で、そのタグ名にヘルパーはありません。もうひとつは、ヘルパーが用意されていない数少ない標準要素です。</p>\n<ul>\n<li>文書そのものと <code>&lt;head&gt;</code> の中だけに現れる要素。\n<code>html</code>、<code>head</code>、<code>body</code>、<code>title</code>、<code>base</code>、<code>meta</code>、<code>link</code></li>\n<li>生テキスト要素。<code>script</code>、<code>style</code>、<code>noscript</code></li>\n<li>レンダーツリーでは意味を持たない要素。<code>template</code>、<code>slot</code></li>\n<li><code>object</code>。C# のキーワードと名前が重なります</li>\n<li>外来要素の <code>svg</code> と <code>math</code>。その配下すべて</li>\n</ul>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">const</span> <span class=\"keyword\">string</span> Widget = <span class=\"string\">&quot;my-widget&quot;</span>;\n\nElement(Widget).Attr(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;42&quot;</span>)        <span class=\"comment\">// カスタム要素</span>\nElement(<span class=\"string\">&quot;svg&quot;</span>)[Element(<span class=\"string\">&quot;circle&quot;</span>)]          <span class=\"comment\">// 外来要素</span>\nElement(_kind + <span class=\"string\">&quot;-widget&quot;</span>)                 <span class=\"comment\">// BCF3009: 定数ではない</span>\nElement(<span class=\"string\">&quot;my widget&quot;</span>)                       <span class=\"comment\">// BCF3009: タグ名の形ではない</span>\n</pre></div>\n<p>タグは、タグ名の形をしたコンパイル時定数である必要があります。そうでなければ\n<a href=\"/docs/ja/diagnostics#bcf3009\">BCF3009</a> を報告します。</p>\n<h2 id=\"子に置けるもの\">子に置けるもの<a href=\"#%E5%AD%90%E3%81%AB%E7%BD%AE%E3%81%91%E3%82%8B%E3%82%82%E3%81%AE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>文字列をそのまま書くと、テキストノードになります。そのため <code>Text()</code> のような構文は用意していません。子ノードの無い要素は角括弧ごと省きます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        <span class=\"string\">&quot;plain text, then &quot;</span>,\n        A.Href(<span class=\"string\">&quot;/docs&quot;</span>)[<span class=\"string\">&quot;a link&quot;</span>],\n        Br,\n        Img.Src(<span class=\"string\">&quot;/logo.png&quot;</span>).Alt(<span class=\"string\">&quot;Logo&quot;</span>)];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>plain text, then <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">a</span> <span class=\"htmlAttributeName\">href</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;/docs&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>a link<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">a</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">br</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">img</span> <span class=\"htmlAttributeName\">src</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;/logo.png&quot;</span> <span class=\"htmlAttributeName\">alt</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;Logo&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>Blazor の <code>RenderFragment</code> は、ほかの子と同じように子の並びへ置けます。</p>\n<div class=\"csharp\"><pre>\n[Parameter] <span class=\"keyword\">public</span> RenderFragment? ChildContent { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div[<span class=\"string\">&quot;before&quot;</span>, ChildContent];\n</pre></div>\n<p>ジェネレーターは、子のひとつひとつを独立した式として読めなければ、シーケンス番号を振れません。子をコレクション式で入れ子に書くのは受け付けます。C# がそれを同じ呼び出しへ展開するからです。</p>\n<div class=\"csharp\"><pre>\nDiv[[<span class=\"string\">&quot;a&quot;</span>, <span class=\"string\">&quot;b&quot;</span>]]     <span class=\"comment\">// Div[&quot;a&quot;, &quot;b&quot;] と同じ。書くならこちら</span>\n</pre></div>\n<p>ジェネレーターが読み取れない子の並びを渡すと、<a href=\"/docs/ja/diagnostics#bcf1003\">BCF1003</a> を報告します。繰り返しには <a href=\"/docs/ja/control-flow#foreach-%E3%81%A8%E3%81%9D%E3%81%AE%E3%82%AD%E3%83%BC\"><code>ForEach</code></a> を使ってください。</p>\n<h2 id=\"空要素は子を取らない\">空要素は子を取らない<a href=\"#%E7%A9%BA%E8%A6%81%E7%B4%A0%E3%81%AF%E5%AD%90%E3%82%92%E5%8F%96%E3%82%89%E3%81%AA%E3%81%84\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>HTML 標準の空要素は13個あり、どれも閉じタグを持ちません。そのため子を書くと\n<a href=\"/docs/ja/diagnostics#bcf3016\">BCF3016</a> を報告します。</p>\n<div class=\"csharp\"><pre>\nImg.Src(<span class=\"string\">&quot;/logo.png&quot;</span>)[<span class=\"string\">&quot;Logo&quot;</span>]     <span class=\"comment\">// BCF3016</span>\nElement(<span class=\"string\">&quot;img&quot;</span>)[<span class=\"string\">&quot;Logo&quot;</span>]           <span class=\"comment\">// BCF3016。同じ規則</span>\nImg.Src(<span class=\"string\">&quot;/logo.png&quot;</span>).Alt(<span class=\"string\">&quot;Logo&quot;</span>) <span class=\"comment\">// こう書く</span>\n</pre></div>\n<p>空要素は装飾で設定して、内容はその隣に置いてください。この API が HTML について検査するのは、ここまでです。この線引きは意図したものです。<code>Table[Div[&quot;x&quot;]]</code> もハイドレーションの後で表示が変わりますが受け付けますし、要素が定義していない属性（<code>Div.Href(&quot;/x&quot;)</code>）も同じです。方針の全体は\n<code>DESIGN.md</code> §4.1 にあります。</p>\n<h2 id=\"名前が衝突する場合\">名前が衝突する場合<a href=\"#%E5%90%8D%E5%89%8D%E3%81%8C%E8%A1%9D%E7%AA%81%E3%81%99%E3%82%8B%E5%A0%B4%E5%90%88\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>using static BlazorCodeFirst.Html;</code> は、適合する HTML 要素の名前をすべて取り込みます。単純名の解決では、自分で宣言した名前が取り込まれた名前に勝ちます。<code>Label</code>、<code>Data</code>、<code>Summary</code>、<code>Source</code>\nという Blazor のパラメーター名はありふれているので、この衝突は実際に起きます。</p>\n<div class=\"csharp\"><pre>\n[Parameter] <span class=\"keyword\">public</span> <span class=\"keyword\">string</span> Data { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\nDiv[Data[<span class=\"string\">&quot;Heading&quot;</span>]]                          <span class=\"comment\">// BCF3027</span>\nDiv[Html.Data[<span class=\"string\">&quot;Heading&quot;</span>]]                     <span class=\"comment\">// こう書く</span>\n</pre></div>\n<p>自分の型、名前空間、メソッドも、同じように要素ヘルパーの名前を奪います。どれも\n<a href=\"/docs/ja/diagnostics#bcf3027\">BCF3027</a> で、奪ったものが何かを示します。</p>\n<h2 id=\"装飾\">装飾<a href=\"#%E8%A3%85%E9%A3%BE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>装飾は、それが属する要素に、子より前に繋げて書きます。HTML が属性をタグの中に書くのと同じ並びです。装飾はラッパーのノードを作らず、所有する要素の属性へ畳み込まれます。<code>class</code> は畳み込まれるので、<code>.Class</code> を2回以上繋げると値は1つの属性にまとまります。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Button\n        .Class(<span class=\"string\">&quot;btn&quot;</span>)\n        .Class(<span class=\"string\">&quot;btn-primary&quot;</span>)\n        .Title(<span class=\"string\">&quot;Save the current document&quot;</span>)[<span class=\"string\">&quot;Save&quot;</span>];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">button</span> <span class=\"htmlAttributeName\">class</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;btn btn-primary&quot;</span> <span class=\"htmlAttributeName\">title</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;Save the current document&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>Save<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">button</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>使える装飾は <code>.Class</code>、<code>.Id</code>、<code>.Href</code>、<code>.Src</code>、<code>.Alt</code>、<code>.Type</code>、<code>.Title</code>、<code>.Role</code>、<code>.OnClick</code> です。汎用の手段として <code>.Attr(name, value)</code> と <code>.On(eventName, handler)</code> もあります。</p>\n<p><code>.On</code> には <code>on</code> を含んだ属性名をそのまま渡します（<code>.On(&quot;onmouseenter&quot;, …)</code>）。接頭辞をこちらで補うことはなく、<code>on</code> の無い名前は <a href=\"/docs/ja/diagnostics#bcf3019\">BCF3019</a> です。<code>.Attr</code> や <code>.On</code> に渡す名前は、空でないコンパイル時定数である必要があります（<a href=\"/docs/ja/diagnostics#bcf3011\">BCF3011</a>）。</p>\n<p><code>.Attr</code> は <code>string?</code> か <code>bool</code> を取ります。<code>bool</code> は Blazor の条件付き属性です。<code>true</code> なら値の空な属性として出力します。HTML が <code>disabled</code>、<code>checked</code>、<code>hidden</code> を有効と読むのは、この形です。\n<code>false</code> なら属性ごと出しません。いつも付く属性は、HTML と同じように値なしで書いてください。\n<code>bool</code> は、付いたり付かなかったりする場合のためにあります。</p>\n<div class=\"csharp\"><pre>\nInput.Type(<span class=\"string\">&quot;checkbox&quot;</span>).Attr(<span class=\"string\">&quot;checked&quot;</span>)                    <span class=\"comment\">// &lt;input type=&quot;checkbox&quot; checked&gt;</span>\nButton.Attr(<span class=\"string\">&quot;disabled&quot;</span>, _submitting)[<span class=\"string\">&quot;Save&quot;</span>]              <span class=\"comment\">// 条件付き</span>\n</pre></div>\n<p>文字列の <code>null</code> も属性を出しません。そのため、値が付くこともあれば付かないこともある属性のために、要素を分岐で囲む必要はありません。</p>\n<div class=\"csharp\"><pre>\nSpan.Attr(<span class=\"string\">&quot;title&quot;</span>, _hasTip ? _tip : <span class=\"keyword\">null</span>)[<span class=\"string\">&quot;Hover me&quot;</span>]\n</pre></div>\n<p><code>null</code> と <code>&quot;&quot;</code> は別の値です。フレームでも、プリレンダリングされた HTML でも、再レンダリングでも変わりません。<code>&quot;&quot;</code> は <code>title=&quot;&quot;</code> になり、<code>null</code> では <code>title</code> そのものが出ません。再レンダリングで値が null になったとき、Blazor は要素を差し替えるのではなく、すでに DOM にある要素から属性を取り除きます。値を1つ取る装飾は、どれもこの意味で <code>null</code> を受け付けます。</p>\n<p><code>object</code> のオーバーロードは、あえて用意していません。ほかの型の値は、レンダリングの時点で文字列になります。そのとき使われるのは書式化を実行するスレッドのカルチャーで、コンポーネントが動いたときのカルチャーではありません。どのカルチャーを選んだかがコードに現れるよう、自分で文字列にしてください。</p>\n<div class=\"csharp\"><pre>\nDiv.Attr(<span class=\"string\">&quot;tabindex&quot;</span>, index.ToString(CultureInfo.InvariantCulture))\n</pre></div><h3 id=\"ハンドラー\">ハンドラー<a href=\"#%E3%83%8F%E3%83%B3%E3%83%89%E3%83%A9%E3%83%BC\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Action</code> や <code>Func&lt;Task&gt;</code> として書いたハンドラーは、何も受け取りません。イベントを読むには、ラムダの引数に型を書きます。すると <code>.On</code> が型付きのオーバーロードを選びます。</p>\n<div class=\"csharp\"><pre>\nInput.Type(<span class=\"string\">&quot;text&quot;</span>).Attr(<span class=\"string\">&quot;value&quot;</span>, _name)\n     .On(<span class=\"string\">&quot;oninput&quot;</span>, (ChangeEventArgs e) =&gt; _name = e.Value?.ToString() ?? <span class=\"string\">&quot;&quot;</span>)\n</pre></div>\n<p>Razor と違って、引数の型はイベント名から推論されません。オーバーロードを選ぶのは、引数に書いた型です。<code>ChangeEventArgs</code> は <code>Microsoft.AspNetCore.Components</code> にあります。<code>MouseEventArgs</code>、\n<code>KeyboardEventArgs</code>、<code>FocusEventArgs</code> は <code>Microsoft.AspNetCore.Components.Web</code> です。\n<code>.Web</code> のほうも、Blazor のアプリがすでに参照している名前空間です。</p>\n<p>型は推論されませんが、検査はされます。そのイベントが渡さない型を書くと\n<a href=\"/docs/ja/diagnostics#bcf3028\">BCF3028</a> を報告します。判断のもとは、Razor が使うのと同じ\n<code>[EventHandler]</code> のメタデータです。渡される型の基底クラスは受け付けます。ハンドラーが実際に受け取れるのがそれだからです。</p>\n<div class=\"csharp\"><pre>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (MouseEventArgs e) =&gt; Zoom(e.ClientX, e.ClientY))[<span class=\"string\">&quot;Zoom&quot;</span>]   <span class=\"comment\">// 渡される型</span>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (EventArgs e) =&gt; Save())[<span class=\"string\">&quot;Save&quot;</span>]                            <span class=\"comment\">// その基底。これでよい</span>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (KeyboardEventArgs e) =&gt; Save())[<span class=\"string\">&quot;Save&quot;</span>]                    <span class=\"comment\">// BCF3028</span>\n</pre></div>\n<p><code>[EventHandler]</code> の登録が無いイベントには、照合する対応表がありません。そのため登録していないカスタムイベントは検査しません。登録は Blazor の標準の仕組みで、自分のプロジェクトでの登録も読みます。</p>\n<div class=\"csharp\"><pre>\n[EventHandler(<span class=\"string\">&quot;onrate&quot;</span>, <span class=\"keyword\">typeof</span>(RatingEventArgs))]\n<span class=\"keyword\">public</span> <span class=\"keyword\">static</span> <span class=\"keyword\">class</span> AppEventHandlers;\n</pre></div>\n<p>属性を出してイベントを受け取る、この対をひとつの装飾で書くのが\n<a href=\"/docs/ja/two-way-binding\"><code>.Bind</code></a>です。</p>\n<h3 id=\"class-のチャネル\">class のチャネル<a href=\"#class-%E3%81%AE%E3%83%81%E3%83%A3%E3%83%8D%E3%83%AB\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>class のチャネルは値をテキストとして繋ぐので、<code>class</code> は文字列しか取らない唯一の名前です。\n<code>.Attr(&quot;class&quot;, flag)</code> は <a href=\"/docs/ja/diagnostics#bcf3023\">BCF3023</a> を報告します。\n<code>.Attr(&quot;class&quot;)</code> も同じです。値を書かない形は、属性があることを表すだけで、繋ぐ文字列を持ちません。条件付きのクラスは文字列で書き、消したい項には <code>null</code> を渡してください。</p>\n<div class=\"csharp\"><pre>\nDiv.Class(<span class=\"string\">&quot;card&quot;</span>).Class(_selected ? <span class=\"string\">&quot;is-selected&quot;</span> : <span class=\"string\">&quot;&quot;</span>)\n</pre></div>\n<p><code>null</code> の項は連結から外れるので、class の装飾を1つだけ持つ要素は、その項が null のとき属性ごと消えます。連結する項がもう1つあるときは、区切りだけが残ります。たとえば\n<code>Div.Class(&quot;card&quot;).Class(_selected ? &quot;is-selected&quot; : null)</code> を考えます。<code>_selected</code> が false のあいだ、出力は <code>class=&quot;card &quot;</code> です。ブラウザーはこれを <code>card</code> 1つのクラスとして読みます。</p>\n<p>ほかの属性とイベントは、どれも1回しかバインドできません。同じ要素に2度書くと\n<a href=\"/docs/ja/diagnostics#bcf3010\">BCF3010</a> を報告します。<code>style</code> もそのひとつで、<code>.Attr(&quot;style&quot;, …)</code> と書きます。<code>.Bind(&quot;class&quot;, …)</code> は、この名前を書く3つ目の方法で、畳み込まれない唯一の方法です。そのため <code>.Class</code> と併せて書いた要素は <a href=\"/docs/ja/diagnostics#bcf3024\">BCF3024</a> を報告します。</p>\n<h3 id=\"装飾を書ける場所\">装飾を書ける場所<a href=\"#%E8%A3%85%E9%A3%BE%E3%82%92%E6%9B%B8%E3%81%91%E3%82%8B%E5%A0%B4%E6%89%80\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>装飾は、単一の要素を対象にしなければなりません。<code>If</code>、<code>ForEach</code>、<code>Fragment</code>、<code>Raw</code>、コンポーネントの結果に付けると <a href=\"/docs/ja/diagnostics#bcf3008\">BCF3008</a> を報告します。子の後ろに繋げて書いた場合（<code>Div[&quot;text&quot;].Class(&quot;card&quot;)</code>）も同じです。角括弧は、もう <code>View</code> を作り終えています。</p>\n<p>装飾は、このライブラリが宣言しているものである必要もあります。綴り違い（<code>Div.Clas(&quot;card&quot;)</code>）や、要素を取って要素を返す自作の拡張メソッドは <a href=\"/docs/ja/diagnostics#bcf3026\">BCF3026</a> を報告します。</p>\n<h2 id=\"次に読むもの\">次に読むもの<a href=\"#%E6%AC%A1%E3%81%AB%E8%AA%AD%E3%82%80%E3%82%82%E3%81%AE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<ul>\n<li><a href=\"/docs/ja/getting-started#%E5%B0%8E%E5%85%A5\">はじめに</a>に戻る。</li>\n<li>条件分岐とリストは<a href=\"/docs/ja/control-flow\">制御構文</a>へ。</li>\n</ul>\n"),
        new DocEntry(
            "control-flow",
            "制御構文",
            "If と ForEach。テンプレートの各位置にコンパイル時のシーケンス番号を割り当てるための構文。",
            50,
            "write",
            "ja",
            false,
            ["if", "foreach-とそのキー", "キーを使わない", "select-の結果を子に展開する", "fragment", "raw", "次に読むもの"],
            "<p>条件分岐とリストには、専用の構文があります。テンプレートのどの位置にも、ジェネレーターがコンパイル時にシーケンス番号を振れるようにするためです。</p>\n<h2 id=\"if\">If<a href=\"#if\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>If</code> は、条件と内容のサンクを取ります。else の分岐は省けます。1回の描画は1つの状態なので、下の出力は <code>_items.Length == 0</code> が選ばなかった側です。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        If(_items.Length == <span class=\"number\">0</span>,\n            () =&gt; P[<span class=\"string\">&quot;Nothing here yet.&quot;</span>],\n            () =&gt; Span[$<span class=\"string\">&quot;{_items.Length} items&quot;</span>])];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">span</span><span class=\"htmlTagDelimiter\">&gt;</span>2 items<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">span</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>互いに排他な分岐には、重ならないシーケンス番号の範囲を割り当てます。そのため分岐が切り替わっても、周りにある兄弟の位置は動きません。</p>\n<h2 id=\"foreach-とそのキー\">ForEach とそのキー<a href=\"#foreach-%E3%81%A8%E3%81%9D%E3%81%AE%E3%82%AD%E3%83%BC\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>ForEach</code> は、位置ではなく要素そのものを見分けるキーを取ります。キーはマークアップに出力されません。属性ではなく、差分計算への指示だからです。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Ul[\n        ForEach(_items,\n            key: item =&gt; item.Id,\n            content: item =&gt; Li[item.Name])];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">ul</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">li</span><span class=\"htmlTagDelimiter\">&gt;</span>Alpha<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">li</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">li</span><span class=\"htmlTagDelimiter\">&gt;</span>Beta<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">li</span><span class=\"htmlTagDelimiter\">&gt;</span>\n<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">ul</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>シーケンス番号はテンプレートの位置を、キーはデータの実体を見分けます。インデックスをキーに渡すと、差分の計算は意味を失います。並び替えたときに、Blazor が別の要素の状態を使い回すからです。</p>\n<p>自分の要素をまったく参照しないキーは報告します。次の3つは、どれも\n<a href=\"/docs/ja/diagnostics#bcf3002\">BCF3002</a> です。</p>\n<ul>\n<li><code>key: _ =&gt; 0</code></li>\n<li>ラムダの外にあるカウンターから読んだキー</li>\n<li>入れ子のループで、外側の要素しか参照していない内側のキー</li>\n</ul>\n<div class=\"csharp\"><pre>\nForEach(_groups, key: g =&gt; g.Id, content: g =&gt;\n    Div[ForEach(g.Items, key: i =&gt; g.Id, content: i =&gt; Span[i.Name])])   <span class=\"comment\">// 内側のキーで BCF3002</span>\n</pre></div>\n<p>これはエラーではなく警告で、コンポーネントの出力は止めません。リストの表示そのものは正しく、差分の計算だけが非効率になるからです。検査もあえて控えめです。見るのは要素を参照したかどうかだけで、その値が要素を見分けられるかは検査しません。要素から作ってはいても実際には位置と変わらないキーは、この検査を通ります。BCF3002 は保証ではなく下限です。</p>\n<p>どちらのラムダも、その場に書いた式のラムダである必要があります。メソッドをそのまま渡さず、呼び出しで包んでください。<code>Row</code> ではなく <code>item =&gt; Row(item)</code> と書きます（<a href=\"/docs/ja/diagnostics#bcf3004\">BCF3004</a>）。内容のルートは単一の要素かコンポーネントである必要があり（<a href=\"/docs/ja/diagnostics#bcf3003\">BCF3003</a>）、そのルートが自分でキーを書くこともできません（<a href=\"/docs/ja/diagnostics#bcf3032\">BCF3032</a>）。</p>\n<h2 id=\"キーを使わない\">キーを使わない<a href=\"#%E3%82%AD%E3%83%BC%E3%82%92%E4%BD%BF%E3%82%8F%E3%81%AA%E3%81%84\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>キーの引数に既定値はありません。見分ける材料を持たないリストは、<code>key: null</code> と明示します。</p>\n<div class=\"csharp\"><pre>\nUl[ForEach(_columns, key: <span class=\"keyword\">null</span>, content: c =&gt; Li[c.Header])]\n</pre></div>\n<p>固定のメニュー、決まった列の集合、並び替わらない <code>Select</code> の結果には、この書き方が適します。代償は、BCF3002 が警告しているものと同じです。差分の計算はインデックスをキーにしたときと同じになり、先頭に1件挿入すると全行が書き直され、行ごとの状態が失われます。<code>SetKey</code> を出さないので、BCF3002 は検査する対象を持たず、BCF3003 も適用されません。内容のルートには、\n<code>Fragment</code>、<code>Raw</code>、単独の <code>If</code> のいずれも置けます。</p>\n<h2 id=\"select-の結果を子に展開する\"><code>Select</code> の結果を子に展開する<a href=\"#select-%E3%81%AE%E7%B5%90%E6%9E%9C%E3%82%92%E5%AD%90%E3%81%AB%E5%B1%95%E9%96%8B%E3%81%99%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>子のリストには、通常の射影、つまり <code>Select</code> の結果をスプレッドで展開する書き方もあります。</p>\n<div class=\"csharp\"><pre>\nUl[[.. _columns.Select(c =&gt; Li[c.Header])]]\n</pre></div>\n<p>上のキーを使わない <code>ForEach</code> の、2つ目の書き方です。同じ <code>foreach</code> になります。展開した項目はその位置に並ぶので、手で書いた子と混ぜられます。</p>\n<div class=\"csharp\"><pre>\nUl[[Li[<span class=\"string\">&quot;先頭&quot;</span>], .. _columns.Select(c =&gt; Li[c.Header]), Li[<span class=\"string\">&quot;末尾&quot;</span>]]]\n</pre></div>\n<p>畳めるのは <code>&lt;source&gt;.Select(&lt;その場に書いた式のラムダ&gt;)</code> だけです。それ以外のスプレッド、たとえば保存した <code>View</code> の配列や、それを返すメソッドは、静的に順序付けできる子ではないので\n<a href=\"/docs/ja/diagnostics#bcf1003\">BCF1003</a> を報告します。保存した <code>View</code> を子として1つ書いたときと同じ結果です。</p>\n<h2 id=\"fragment\">Fragment<a href=\"#fragment\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>Fragment</code> は、ラッパーの要素を出さずに、複数の子を1つの <code>View</code> にまとめます。</p>\n<div class=\"csharp\"><pre>\nFragment(H2[<span class=\"string\">&quot;Title&quot;</span>], P[<span class=\"string\">&quot;Body&quot;</span>])\n</pre></div>\n<p>要素を開かないので、装飾は付けられず（<a href=\"/docs/ja/diagnostics#bcf3008\">BCF3008</a>）、<code>ForEach</code> の内容のルートにもできません（<a href=\"/docs/ja/diagnostics#bcf3003\">BCF3003</a>）。</p>\n<h2 id=\"raw\">Raw<a href=\"#raw\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>Raw</code> は、HTML の文字列をそのまま流し込みます。<code>MarkupString</code> にあたるものです。</p>\n<div class=\"warning\" role=\"note\"><p><code>Raw</code> はエスケープせずに DOM へ書き込みます。渡してよいのは、自分で作った内容だけです。利用者が入力した文字列や、外部のサービスから返ってきた文字列を渡すと、そのまま HTML として解釈され、含まれていたスクリプトが動きます。</p>\n</div>\n<p>このページも <code>Raw</code> で表示しています。Markdown をビルド時に HTML へ変換し、その結果を <code>Raw</code> に渡しています。変換するのは、このリポジトリにあるツールです。</p>\n<div class=\"csharp\"><pre>\nArticle.Class(<span class=\"string\">&quot;prose&quot;</span>)[Raw(entry.Html)]\n</pre></div><h2 id=\"次に読むもの\">次に読むもの<a href=\"#%E6%AC%A1%E3%81%AB%E8%AA%AD%E3%82%80%E3%82%82%E3%81%AE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<ul>\n<li>書ける要素の一覧は<a href=\"/docs/ja/elements-and-decorations#%E8%A3%85%E9%A3%BE\">要素と装飾</a>へ。</li>\n<li>コンポーネントから別のコンポーネントを呼ぶ方法は<a href=\"/docs/ja/components-and-reuse\">コンポーネントと再利用</a>へ。</li>\n</ul>\n"),
        new DocEntry(
            "components-and-reuse",
            "コンポーネントと再利用",
            "コンポーネントから別のコンポーネントを呼ぶ方法、Razor コンポーネントとの双方向の相互運用、ViewPart の用途。",
            60,
            "write",
            "ja",
            false,
            ["blazorcodefirst-のコンポーネントを呼ぶ", "子の内容を渡す", "ジェネリックなフラグメントのパラメーター", "既存の-razor-コンポーネントやサードパーティのコンポーネントを呼ぶ", "値をカスケードする", "razor-から-blazorcodefirst-のコンポーネントを使う", "コンポーネントを作らずに分ける-viewpart", "コンポーネントの呼び出しに名前を付ける", "内容を包む", "次に読むもの"],
            "<p>再利用の単位はコンポーネントです。BlazorCodeFirst のコンポーネントから別のコンポーネントを呼ぶには <code>Component&lt;T&gt;()</code> を使います。既存の Razor コンポーネントも、サードパーティのコンポーネントも、まったく同じ呼び方です。逆に <code>.razor</code> のファイルからは、BlazorCodeFirst のコンポーネントを通常のタグとして書けます。<code>[ViewPart]</code> は用途の違う別の仕組みで、このページの終わりで扱います。</p>\n<h2 id=\"blazorcodefirst-のコンポーネントを呼ぶ\">BlazorCodeFirst のコンポーネントを呼ぶ<a href=\"#blazorcodefirst-%E3%81%AE%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%82%92%E5%91%BC%E3%81%B6\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>Component&lt;T&gt;()</code> は、コンポーネントをツリーに置きます。パラメーターは <code>.Param</code> でバインドし、対象のプロパティはラムダで指定します。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div.Class(<span class=\"string\">&quot;dashboard&quot;</span>)[\n        Component&lt;StatusBadge&gt;()\n            .Param(b =&gt; b.Status, _status)\n            .Param(b =&gt; b.Compact, <span class=\"keyword\">true</span>)];\n</pre></div>\n<p>ジェネレーターは <code>.Param</code> のひとつひとつを静的なパラメーターの設定に変え、\n<code>AddComponentParameter</code> の呼び出しとして書き出します。リフレクションは使わず、実行時に式ツリーをコンパイルすることもありません。この経路がトリミングと AOT に対して安全なのは、そのためです。</p>\n<p>書ける形を診断で縛っているのも、それが理由です。セレクターのラムダでパラメーターを指定するチャネルは、どれもこの診断で検査します。<code>.Param</code> だけでなく、<code>.Template</code> も、コンポーネントに対する\n<code>.Bind</code> も同じです。</p>\n<ul>\n<li>セレクターは、プロパティを選ぶだけの式である必要があります（<a href=\"/docs/ja/diagnostics#bcf3005\">BCF3005</a>）。</li>\n<li>対象は、設定できる <code>[Parameter]</code> のプロパティである必要があります（<a href=\"/docs/ja/diagnostics#bcf3006\">BCF3006</a>）。</li>\n<li>1つのチェーンで、各プロパティをバインドできるのは1回までです。チャネルはすべて数えます（<a href=\"/docs/ja/diagnostics#bcf3007\">BCF3007</a>）。</li>\n</ul>\n<h2 id=\"子の内容を渡す\">子の内容を渡す<a href=\"#%E5%AD%90%E3%81%AE%E5%86%85%E5%AE%B9%E3%82%92%E6%B8%A1%E3%81%99\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>入れ子に書いた子は <code>ChildContent</code> にバインドされます。入れ子の内容は <code>ChildContent</code> にしかならない、という Razor の規則をそのまま写しています。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;Card&gt;()[\n        H2[<span class=\"string\">&quot;Heading&quot;</span>],\n        P[<span class=\"string\">&quot;Body text&quot;</span>]];\n</pre></div>\n<p>これには <code>Card</code> の側に、フラグメント型で設定できる <code>[Parameter] ChildContent</code> が必要です。無ければ\n<a href=\"/docs/ja/diagnostics#bcf3013\">BCF3013</a> を報告します。<code>RenderFragment&lt;TContext&gt;</code> も対象です。角括弧はコンテキストを捨ててバインドします。角括弧の中には、コンテキストを読むための名前が無いからです。\n<code>ChildContent</code> 以外の名前を持つジェネリックなフラグメントは <code>.Template</code> で指定します。下の<a href=\"#%E3%82%B8%E3%82%A7%E3%83%8D%E3%83%AA%E3%83%83%E3%82%AF%E3%81%AA%E3%83%95%E3%83%A9%E3%82%B0%E3%83%A1%E3%83%B3%E3%83%88%E3%81%AE%E3%83%91%E3%83%A9%E3%83%A1%E3%83%BC%E3%82%BF%E3%83%BC\">ジェネリックなフラグメントのパラメーター</a>を見てください。</p>\n<p>ジェネリックでないほかの <code>RenderFragment</code> パラメーターは、<code>Footer</code> や <code>Header</code> などです。これらは\n<code>.Param(c =&gt; c.Footer, content)</code> と書き、パラメーターを明示してバインドします。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;Card&gt;()\n        .Param(c =&gt; c.Title, <span class=\"string\">&quot;Card title&quot;</span>)\n        .Param(c =&gt; c.Footer, Span[<span class=\"string\">&quot;Footer note&quot;</span>])[\n            H2[<span class=\"string\">&quot;Heading&quot;</span>],\n            P[<span class=\"string\">&quot;Body text&quot;</span>]];\n</pre></div>\n<p><code>ChildContent</code> を <code>.Param</code> で指定するのも正しい書き方です。冗長ですが、Razor の属性の形（<code>&lt;Card&gt;&lt;ChildContent&gt;...&lt;/ChildContent&gt;&lt;/Card&gt;</code>）に対応します。同じパラメーターを両方のチャネルからバインドすると <a href=\"/docs/ja/diagnostics#bcf3007\">BCF3007</a> です。</p>\n<p>本物の <code>RenderFragment</code> の値は、BlazorCodeFirst の <code>View</code> の式とは違います。ジェネリックな\n<code>.Param&lt;TValue&gt;</code> のオーバーロードでバインドし、そのまま書き出されます。</p>\n<p>どちらのオーバーロードが使われるかは、対象のパラメーターの型で決まります。<code>RenderFragment?</code> のパラメーターなら内容のオーバーロード、それ以外ならジェネリックなほうです。そのため\n<code>RenderFragment</code> でないパラメーターに向けた内容は、ジェネリックなオーバーロードに落ち、値がそのまま書き出されます。ただし設計時の式は、実行時には空の目印でしかありません。これが\n<a href=\"/docs/ja/diagnostics#bcf3014\">BCF3014</a> です。</p>\n<div class=\"csharp\"><pre>\n[Parameter] <span class=\"keyword\">public</span> <span class=\"keyword\">object</span>? Payload { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\n\nComponent&lt;Card&gt;().Param(c =&gt; c.Payload, Div[<span class=\"string\">&quot;x&quot;</span>])   <span class=\"comment\">// BCF3014</span>\n</pre></div>\n<p><code>View</code>、<code>ElementView</code>、<code>ComponentView&lt;T&gt;</code>、<code>SlotView</code> は、どれも同じように報告します。内容を渡したいなら、受け取る側のコンポーネントに <code>RenderFragment</code> のパラメーターを持たせてください。</p>\n<p>パラメーターの値の中で型名が解決できない場合は、<a href=\"/docs/ja/diagnostics#bcf3015\">BCF3015</a>を見てください。</p>\n<h2 id=\"ジェネリックなフラグメントのパラメーター\">ジェネリックなフラグメントのパラメーター<a href=\"#%E3%82%B8%E3%82%A7%E3%83%8D%E3%83%AA%E3%83%83%E3%82%AF%E3%81%AA%E3%83%95%E3%83%A9%E3%82%B0%E3%83%A1%E3%83%B3%E3%83%88%E3%81%AE%E3%83%91%E3%83%A9%E3%83%A1%E3%83%BC%E3%82%BF%E3%83%BC\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>RenderFragment&lt;TContext&gt;</code> のパラメーターが取るのは <em>テンプレート</em> です。コンポーネントは、描きたいコンテキストの値ごとに、それを1回ずつ呼び出します。よくある例が <code>EditForm.ChildContent</code> で、これは <code>RenderFragment&lt;EditContext&gt;</code> です。</p>\n<p>こうしたパラメーターを指定するのが <code>.Template</code> です。書き方は2通りあり、どちらを使うかは、内容がコンテキストを読むかどうかだけで決まります。グリッドの <code>RowTemplate</code> のように\n<code>ChildContent</code> 以外の名前を持つものには、常に <code>.Template</code> が必要です。角括弧では指定できません。</p>\n<p>コンテキストを読まない <code>ChildContent</code> は角括弧で書きます。上に出した形であり、\n<code>.Template(form =&gt; form.ChildContent, content)</code> と同じものを発行します。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;EditForm&gt;()\n        .Param(form =&gt; form.Model, _model)[\n            Component&lt;NameFields&gt;().Param(fields =&gt; fields.Value, _model)];\n</pre></div>\n<p>使うなら、コンテキストから内容へのラムダで指定します。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;EditForm&gt;()\n        .Param(form =&gt; form.Model, _model)\n        .Template(form =&gt; form.ChildContent, editContext =&gt;\n            Fragment(\n                Span[editContext.IsModified() ? <span class=\"string\">&quot;Unsaved changes&quot;</span> : <span class=\"string\">&quot;No changes&quot;</span>],\n                Component&lt;NameFields&gt;().Param(fields =&gt; fields.Value, _model)));\n</pre></div>\n<p>2つ目の例には、注意点が1つあります。これを踏まえないと、バッジは一度も変わりません。\n<code>IsModified()</code> はテンプレートの実行時に読まれます。しかし <code>EditForm</code> と <code>CascadingValue</code> の連なりには、<code>OnFieldChanged</code> で再レンダリングするものがありません。フィールドに入力すれば\n<code>EditContext</code> に通知は届きます。ただ、その通知を誰も購読していないので、テンプレートを持つコンポーネントは再レンダリングされず、バッジは最初に描かれた文字のままです。これは Blazor のレンダリングの伝わり方に起因するもので、テンプレートが受け取るコンテキストの制限ではありません。テンプレートには、実行のたびに最新の <code>EditContext</code> が渡されます。</p>\n<p>テンプレートが変化するコンテキストの状態を読むなら、再レンダリングはフォームを持つコンポーネント自身が行います。<code>Model</code> に作らせるのではなく、<code>EditContext</code> を自分で組み立てます。そして\n<code>OnFieldChanged</code> を購読し、<code>StateHasChanged</code> を呼び、<code>Dispose</code> で購読を解きます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> ContextReadingForm()\n{\n    _editContext = <span class=\"keyword\">new</span> EditContext(_model);\n    _editContext.OnFieldChanged += OnFieldChanged;\n}\n\n<span class=\"keyword\">private</span> <span class=\"keyword\">void</span> OnFieldChanged(<span class=\"keyword\">object</span>? sender, FieldChangedEventArgs e) =&gt; StateHasChanged();\n\n<span class=\"keyword\">public</span> <span class=\"keyword\">void</span> Dispose() =&gt; _editContext.OnFieldChanged -= OnFieldChanged;\n\n<span class=\"comment\">// ...そのうえで .Param(form =&gt; form.Model, …) ではなく .Param(form =&gt; form.EditContext, _editContext) を渡す</span>\n</pre></div>\n<p>コンテキストを使わないテンプレートや、フォームが開いているあいだ変わらない状態しか読まないテンプレートに、この準備は不要です。</p>\n<p><code>RenderFragment&lt;TContext&gt;</code> のラムダはジェネレーターが書くので、その内容は通常の\nBlazorCodeFirst で、シーケンス番号も周りから続きます。コンテキストの引数の名前は自由に決められます。生成コードは自前の名前を使い、参照していた箇所を書き換えるので、たまたま同じ名前のフィールドがあっても壊れません。</p>\n<p>2つ目の引数は、その場に書いたラムダである必要があります。メソッドグループや、変数やフィールドに持っているデリゲートは <a href=\"/docs/ja/diagnostics#bcf3022\">BCF3022</a> を報告します。生成コードに写されるのはラムダの本体の構文で、宣言が別の場所にあるデリゲートには写す本体がないからです。</p>\n<p>すでに <code>RenderFragment&lt;TContext&gt;</code> の <em>値</em> を持っているなら、スカラーの <code>.Param</code> で渡してください。どちらのチャネルも同じパラメーターに届きますが、デリゲートの同一性が違い、その違いは動作に現れます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"comment\">// コンストラクターで一度だけ組み立てる。パラメーターの参照はレンダリングをまたいで変わらない。</span>\n<span class=\"keyword\">private</span> <span class=\"keyword\">readonly</span> RenderFragment&lt;EditContext&gt; _fields;\n</pre></div>\n<p>状態を読む <code>.Template</code> の内容は、その状態を捕捉するので、ラムダはレンダリングのたびに新しいデリゲートへ変わります。受け取る側のコンポーネントはパラメーターが変わったと見て、テンプレートを描き直します。<code>.Param</code> で渡したキャッシュ済みのデリゲートは変わらないので、描き直しません。キャッシュする形を使うのは、その安定が欲しいときだけにしてください。ほかの場面では <code>.Template</code>\nのほうが短く、安全です。キャッシュのように忘れることがないからです。</p>\n<h2 id=\"既存の-razor-コンポーネントやサードパーティのコンポーネントを呼ぶ\">既存の Razor コンポーネントやサードパーティのコンポーネントを呼ぶ<a href=\"#%E6%97%A2%E5%AD%98%E3%81%AE-razor-%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%82%84%E3%82%B5%E3%83%BC%E3%83%89%E3%83%91%E3%83%BC%E3%83%86%E3%82%A3%E3%81%AE%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%82%92%E5%91%BC%E3%81%B6\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>書き方は変わりません。<code>.razor</code> で書いたコンポーネントも、MudBlazor や QuickGrid のようなパッケージのコンポーネントも、同じ <code>Component&lt;T&gt;()</code> で置きます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        Span[<span class=\"string\">&quot;Data Grid&quot;</span>],\n        Component&lt;MudDataGrid&lt;Order&gt;&gt;()\n            .Param(g =&gt; g.Items, _orders)\n            .Param(g =&gt; g.Dense, <span class=\"keyword\">true</span>)];\n</pre></div>\n<p>制限が1つあり、多くの場合これが最初の障害になります。型引数は <code>OpenComponent&lt;T&gt;</code> のリテラルとしてそのまま生成コードへ出るので、ジェネレーターの実行時点で解決できなければなりません。Razor のコンパイラ自身がソースジェネレーターで、ソースジェネレーターは互いの出力を見られません。そのため <em>同じプロジェクト</em> で宣言した <code>.razor</code> のコンポーネントは、BlazorCodeFirst のジェネレーターの実行時点ではまだ存在しません。型引数に書くと <a href=\"/docs/ja/diagnostics#bcf3012\">BCF3012</a> を報告します。</p>\n<p>回避する方法は2つです。</p>\n<ul>\n<li><code>.razor</code> のコンポーネントを、参照しているプロジェクトかパッケージへ移す。型はメタデータから来るようになり、通常どおり解決します。</li>\n<li>コンポーネントを C# で手書きする。手書きのコンポーネントは通常のソースなので、同じプロジェクトの中でも必ず解決します。</li>\n</ul>\n<p>綴り違いや <code>using</code> の書き忘れも同じ BCF3012 になり、同じ位置に CS0246 が並びます。</p>\n<h2 id=\"値をカスケードする\">値をカスケードする<a href=\"#%E5%80%A4%E3%82%92%E3%82%AB%E3%82%B9%E3%82%B1%E3%83%BC%E3%83%89%E3%81%99%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>CascadingValue&lt;T&gt;</code> もその既存のコンポーネントの1つです。カスケードのために、この API が足すものはありません。<code>Component&lt;T&gt;()</code> で置き、<code>Value</code> を <code>.Param</code> で渡し、それを読む部分木を角括弧に入れます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;CascadingValue&lt;ThemeInfo&gt;&gt;()\n        .Param(c =&gt; c.Value, _theme)[\n            Component&lt;Toolbar&gt;(),\n            Component&lt;Editor&gt;()];\n</pre></div>\n<p><code>Name</code> と <code>IsFixed</code> も、ほかと変わらない <code>.Param</code> の対象です。名前つきのカスケードなら、渡す側は <code>.Param(c =&gt; c.Name, &quot;locale&quot;)</code> です。受け取る側は <code>[CascadingParameter(Name = &quot;locale&quot;)]</code> になります。</p>\n<p>その受け取る側は通常の Blazor で、ジェネレーターはそこを見ません。<code>[CascadingParameter]</code> はクラスのプロパティで、<code>.razor</code> のコンポーネントとまったく同じです。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Toolbar : BodyComponentBase\n{\n    [CascadingParameter]\n    <span class=\"keyword\">public</span> ThemeInfo? Theme { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\n\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n        Div.Class(<span class=\"string\">&quot;toolbar&quot;</span>)[Span[Theme?.Name ?? <span class=\"string\">&quot;default&quot;</span>]];\n}\n</pre></div>\n<p>値を差し替えると、それを読む子孫はすべて再レンダリングされます。自分のフレームが変わらなかった子孫も含みます。購読しているのは Blazor 自身です。上の呼び出しからジェネレーターが出すフレームは、<code>&lt;CascadingValue Value=&quot;@_theme&quot;&gt;</code> が出すものと同じです。</p>\n<h2 id=\"razor-から-blazorcodefirst-のコンポーネントを使う\">Razor から BlazorCodeFirst のコンポーネントを使う<a href=\"#razor-%E3%81%8B%E3%82%89-blazorcodefirst-%E3%81%AE%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%82%92%E4%BD%BF%E3%81%86\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>逆向きには、この制限がありません。BlazorCodeFirst のコンポーネントは、ただの Blazor のコンポーネントです。<code>BodyComponentBase</code> は <code>ComponentBase</code> から派生しているので、<code>.razor</code> のファイルは、これを通常のタグとして書けます。</p>\n<pre><code class=\"language-razor\">@* ExistingPage.razor *@\n&lt;div class=&quot;legacy-layout&quot;&gt;\n    &lt;StatusBadge Status=&quot;@currentStatus&quot; /&gt;\n&lt;/div&gt;\n</code></pre>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> StatusBadge : BodyComponentBase\n{\n    [Parameter] <span class=\"keyword\">public</span> Status Status { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; } = <span class=\"keyword\">default</span>!;\n\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n        Span.Class(Status.IsHealthy ? <span class=\"string\">&quot;badge badge-ok&quot;</span> : <span class=\"string\">&quot;badge badge-alert&quot;</span>)[Status.Label];\n}\n</pre></div>\n<p>これは同じプロジェクトでも動作します。BCF3012 との非対称がなぜあるのかは、知っておくと役に立ちます。ここで Razor が解決しなければならないのは <em>クラス名</em> で、そのクラスの宣言は手で書いたソースです。ジェネレーターがその中に書き入れるのは <code>RenderView</code> だけで、Razor はそれを見る必要がありません。BCF3012 の向きでは、型そのものが生成された出力です。これは別の問題です。</p>\n<p>このサイトがそうしています。<code>App.razor</code> が <code>NotFoundPage</code> を参照しています。これは同じプロジェクトの通常の <code>.cs</code> ファイルで宣言した、BlazorCodeFirst のコンポーネントです。</p>\n<h2 id=\"コンポーネントを作らずに分ける-viewpart\">コンポーネントを作らずに分ける: <code>[ViewPart]</code><a href=\"#%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%82%92%E4%BD%9C%E3%82%89%E3%81%9A%E3%81%AB%E5%88%86%E3%81%91%E3%82%8B-viewpart\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>Body</code> の式のどの部分にも、コンポーネントが必要なわけではありません。<code>[ViewPart]</code> のメソッドは\nUI の断片で、ジェネレーターはこれを、コンポーネントの境界越しに描くのではなく、<em>呼び出した側の中へ</em> 展開します。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        AppHeader(<span class=\"string\">&quot;My Application&quot;</span>),\n        BodyContent()];\n\n[ViewPart]\n<span class=\"keyword\">private</span> <span class=\"keyword\">static</span> View AppHeader(<span class=\"keyword\">string</span> title) =&gt;\n    Div.Class(<span class=\"string\">&quot;app-header&quot;</span>)[\n        Span[title]];\n</pre></div>\n<p>呼び出し側に生成される <code>RenderView</code> は、ヘッダーのフレームを直接持ちます。コンポーネントの実体も、パラメーターも、ライフサイクルも、差分の境界もありません。その場にマークアップを書いたのと同じです。</p>\n<h3 id=\"コンポーネントの呼び出しに名前を付ける\">コンポーネントの呼び出しに名前を付ける<a href=\"#%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%81%AE%E5%91%BC%E3%81%B3%E5%87%BA%E3%81%97%E3%81%AB%E5%90%8D%E5%89%8D%E3%82%92%E4%BB%98%E3%81%91%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>パーツの本体は通常の設計時の構文なので、要素と同じようにコンポーネントの呼び出しも書けます。そうするとコンポーネントの呼び出しに固有の名前が付き、呼び出し側からは <code>Component&lt;T&gt;()</code> と\n<code>.Param</code> が消えます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">static</span> <span class=\"keyword\">class</span> Widgets\n{\n    [ViewPart]\n    <span class=\"keyword\">public</span> <span class=\"keyword\">static</span> View Badge(<span class=\"keyword\">string</span> label, <span class=\"keyword\">bool</span> compact = <span class=\"keyword\">false</span>) =&gt;\n        Component&lt;StatusBadge&gt;()\n            .Param(b =&gt; b.Label, label)\n            .Param(b =&gt; b.Compact, compact);\n}\n\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Dashboard : BodyComponentBase\n{\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n        Div[\n            Widgets.Badge(<span class=\"string\">&quot;hello&quot;</span>),\n            Widgets.Badge(<span class=\"string\">&quot;x&quot;</span>, compact: <span class=\"keyword\">true</span>)];\n}\n</pre></div>\n<p>呼び出し側は通常の C# の呼び出しなので、名前付き引数と省略可能な引数が使えます。呼び出し側に生成される <code>RenderView</code> は、呼び出しのたびに <code>StatusBadge</code> を直接開きます。描かれるツリーは、\n<code>Component&lt;StatusBadge&gt;()</code> を2回書いたときと同じものです。\n<code>.Param</code> の規則を検査するのは、セレクターを書いた場所です。<a href=\"/docs/ja/diagnostics#bcf3006\">BCF3006</a>\nと BCF3007 は、呼び出す箇所がいくつあっても、パーツの宣言で1回だけ報告されます。</p>\n<p>名前を付ける対象のコンポーネントは、パッケージのものを含めてどこにあってもかまいません。\n<code>MudDataGrid&lt;Order&gt;</code> も、自分で書いたコンポーネントと同じ条件で名前を持てます。パーツのほうは違います。宣言のソース構文から展開するので、呼び出すプロジェクトの中に置く必要があります（後述の <a href=\"/docs/ja/diagnostics#bcf1002\">BCF1002</a>）。そのためコンポーネントのライブラリが配れるのはコンポーネントまでで、名前を付けるパーツは配れません。使う側のプロジェクトがそれぞれ書きます。\nBCF3012 の非対称を裏返した形です。</p>\n<h3 id=\"内容を包む\">内容を包む<a href=\"#%E5%86%85%E5%AE%B9%E3%82%92%E5%8C%85%E3%82%80\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>呼び出し側が渡す内容を包むパーツは、<code>View</code> ではなく <code>SlotView</code> を返し、その内容が入る場所に\n<code>Slot</code> を書きます。呼び出し側は、要素の子を渡すのとまったく同じように、角括弧で渡します。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        Card(<span class=\"string\">&quot;Profile&quot;</span>)[P[<span class=\"string\">&quot;Body text&quot;</span>]],\n        Section.Class(<span class=\"string\">&quot;body&quot;</span>)[P[<span class=\"string\">&quot;…&quot;</span>]]];\n\n[ViewPart]\n<span class=\"keyword\">private</span> <span class=\"keyword\">static</span> SlotView Card(<span class=\"keyword\">string</span> title) =&gt;\n    Div.Class(<span class=\"string\">&quot;card&quot;</span>)[\n        H2[title],\n        Slot];\n</pre></div>\n<p>この書き方の狙いはそこにあります。切り出したパーツが、はじめからある要素と同じ形で読めることです。\n<code>Card(&quot;Profile&quot;)[…]</code> と <code>Section.Class(&quot;body&quot;)[…]</code> は同じように読め、どちらが自作かは表れません。</p>\n<p>角括弧は省けません。そしてそれを強制しているのは C# だけです。<code>SlotView</code> から <code>View</code> への変換はないので、角括弧を忘れた <code>Div[Card(&quot;Profile&quot;)]</code> は、黙って空のカードを描くのではなくコンパイルエラーになります。同じ性質が、2つの書き方を排除します。装飾（<code>Card(&quot;t&quot;).Class(&quot;x&quot;)</code>。該当する拡張メソッドがない）と、引数で渡す書き方（<code>Card(&quot;t&quot;, P[&quot;x&quot;])</code>。バインドする引数がない）です。</p>\n<p>2つ目のスロットは、通常の <code>View</code> の引数です。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Panel(H2[<span class=\"string\">&quot;Title&quot;</span>])[\n        P[<span class=\"string\">&quot;Body text&quot;</span>]];\n\n[ViewPart]\n<span class=\"keyword\">private</span> <span class=\"keyword\">static</span> SlotView Panel(View header) =&gt;\n    Div.Class(<span class=\"string\">&quot;panel&quot;</span>)[\n        Div.Class(<span class=\"string\">&quot;panel-head&quot;</span>)[header],\n        Div.Class(<span class=\"string\">&quot;panel-body&quot;</span>)[Slot]];\n</pre></div>\n<p>名前の付いたチャネルが先、主な内容は角括弧の中です。<code>Div.Class(&quot;card&quot;)[…]</code> や\n<code>Component&lt;T&gt;().Template(…)[…]</code> が、この API で既に取っている形です。</p>\n<p>スロットは、要素の角括弧と同じようにコンポーネントの角括弧にも置けます。名前を付けたコンポーネントの呼び出しが内容を受け取るのは、この形です。</p>\n<div class=\"csharp\"><pre>\n[ViewPart]\n<span class=\"keyword\">private</span> <span class=\"keyword\">static</span> SlotView Framed(<span class=\"keyword\">string</span> title) =&gt;\n    Component&lt;Card&gt;().Param(c =&gt; c.Title, title)[Slot];\n</pre></div>\n<p>呼び出し側の内容は、<a href=\"#%E5%AD%90%E3%81%AE%E5%86%85%E5%AE%B9%E3%82%92%E6%B8%A1%E3%81%99\">子の内容を渡す</a>の規則どおり <code>Card.ChildContent</code> に届きます。</p>\n<p>規則が2つあります。<code>SlotView</code> のパーツは、<code>Slot</code> を <strong>ちょうど1回</strong> 書く必要があります。2回書けば、\n1つの角括弧から呼び出し側の内容を2度出すことになります。一度も書かなければ、呼び出し側が渡すよう義務づけられた内容を捨てることになります。どちらも <a href=\"/docs/ja/diagnostics#bcf3025\">BCF3025</a> です。呼び出し側の内容が来ない場所に書いた <code>Slot</code> も同じで、コンポーネント自身の <code>Body</code> や、<code>View</code> を返すパーツがこれにあたります。</p>\n<p>対して <code>View</code> の引数は、何度参照してもかまいません。通常の引数だからです。何も捕捉せず、共有もしません。参照するたびに呼び出し側の式を展開し直すので、副作用のある引数は参照の数だけ実行されます。Blazor の <code>RenderFragment</code> を2回呼んだときと同じ振る舞いです。</p>\n<p>ただし、どちらも内容であって、内容に値はありません。式ではなくフレームになるからです。そのためスロットは、子として <em>置く</em> ことしかできません。値が必要な場所で読むと <strong>BCF1002</strong> です。<code>ForEach</code>\nのキーや、属性の値の中がそれにあたります。</p>\n<p>トレードオフの全体を、観点ごとに並べます。</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th><code>[ViewPart]</code></th>\n<th>コンポーネント</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>状態とライフサイクル</td>\n<td>持たない。メソッドだから</td>\n<td>Blazor のコンポーネントとして自前で持つ</td>\n</tr>\n<tr>\n<td>再レンダリング</td>\n<td>自分の境界がないので、呼び出し側と一緒に</td>\n<td>自分の差分境界で、自分だけで</td>\n</tr>\n<tr>\n<td>呼び出し側のフレームが持つもの</td>\n<td>パーツのフレームが、その場に展開される</td>\n<td>コンポーネントを開くフレーム 1 つ</td>\n</tr>\n<tr>\n<td>引数</td>\n<td>値渡しの引数。名前付きも省略可能も使える</td>\n<td><code>[Parameter]</code> のプロパティを <code>.Param</code> で渡す</td>\n</tr>\n<tr>\n<td>別のアセンブリから</td>\n<td>使えない (BCF1002)</td>\n<td>使える</td>\n</tr>\n</tbody>\n</table>\n<p><code>[ViewPart]</code> は、ジェネレーターが展開できる宣言の契約を満たす必要があります。満たさなければ\n<strong>BCF1002</strong> です。メソッドは次の形でなければなりません。</p>\n<ul>\n<li>静的である</li>\n<li>ジェネリックでなく、ジェネリックでない型で宣言されている</li>\n<li>返り値の式1つに収まる。その手前にはローカル宣言と式文を置ける。<code>Body</code> のゲッターと同じ形</li>\n<li><code>View</code> を返す。内容を取るなら <code>SlotView</code></li>\n</ul>\n<p>引数は、通常の値渡しの引数である必要があります。型は、生成コードから名前を書けるものに限ります。<code>params</code>、参照渡しの引数、<code>ElementView</code> の引数は、どれも拒否します。子を持たない要素を内容として渡すには、<code>Div[…]</code> か <code>Fragment(Div)</code> と書きます。どちらも <code>View</code> です。<code>View</code> の引数は内容のスロットなので、返り値の型は <code>SlotView</code> でなければなりません。<code>View</code> を返すパーツに書けば\nBCF1002 で、省略可能にはできません。</p>\n<p>拡張メンバーであってもいけません。<code>this</code> 引数も、<code>extension</code> ブロックのメンバーも同じです。呼び出しは、通常の呼び出しとして書きます（<code>AppHeader(&quot;My Application&quot;)</code>）。この API が、要素への装飾でない呼び出しを、すべてそう書いているからです。メソッドチェーンで書くと、装飾でないものが、この API が装飾のために空けている位置へ入ります。そのレシーバーは、必ずほかの型の値になります。それでは <code>[ViewPart]</code> は、<code>Body</code> を分ける手段ではなく、<em>その型</em> の API を増やす手段になってしまいます。</p>\n<p>BCF1002 は <em>呼び出し側</em> でも出ます。その条件の1つは、はっきり書いておく価値があります。</p>\n<p><strong><code>[ViewPart]</code> はアセンブリの境界を越えられません。</strong> 呼び出しを展開するには宣言のソースの構文が必要で、ジェネレーターは自身が動作しているコンパイルから宣言を集めます。IL は本体の構文を持たないので、参照しているプロジェクトやパッケージにある <code>[ViewPart]</code> は、呼び出した場所で必ず BCF1002 になります。展開が再帰して循環する場合と、展開する場所から見えない <code>private</code> や <code>protected</code> のメンバーに本体が触れている場合も、同じ診断です。</p>\n<p>そのパーツを別のプロジェクトで使いたいなら、コンポーネントにして <code>Component&lt;T&gt;()</code> から使ってください。</p>\n<p>BCF1002 は <code>[ViewPart]</code> だけの診断ではありません。コンポーネント自身の <code>Body</code> とレイアウトの\n<code>Chrome</code> も同じ検査を通ります。そちらから出た報告は、メソッドではなく式を指します。\n<a href=\"/docs/ja/diagnostics#bcf1002\">BCF1002</a>を見てください。</p>\n<h2 id=\"次に読むもの\">次に読むもの<a href=\"#%E6%AC%A1%E3%81%AB%E8%AA%AD%E3%82%80%E3%82%82%E3%81%AE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<ul>\n<li><code>If</code> とキー付き <code>ForEach</code> は<a href=\"/docs/ja/control-flow\">制御構文</a>へ。</li>\n<li>ルーティングされたページを共通の外枠で包む方法は<a href=\"/docs/ja/layouts\">レイアウト</a>へ。</li>\n<li>パラメーターを渡すもう1つの方法である <code>.Bind</code> は、<a href=\"/docs/ja/two-way-binding#%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%81%AE%E3%83%91%E3%83%A9%E3%83%A1%E3%83%BC%E3%82%BF%E3%83%BC%E3%82%92%E3%83%90%E3%82%A4%E3%83%B3%E3%83%89%E3%81%99%E3%82%8B\">双方向バインディング</a>へ。</li>\n</ul>\n"),
        new DocEntry(
            "layouts",
            "レイアウト",
            "ChromeLayoutBase から派生したレイアウトで、ルーティングされたページを共通の外枠で包む。",
            70,
            "write",
            "ja",
            false,
            ["chrome-と-body", "body-ではなく-chrome-である理由", "レイアウトを入れ子にする", "renderfragment-はそのまま内容になる", "読めるが書き換えられない", "次に読むもの"],
            "<p>レイアウトは、ルーティングされたページを共通の外枠で包みます。ヘッダー、ナビゲーション、フッターといったものです。BlazorCodeFirst のレイアウトは、コンポーネントと同じように書きます。\n<code>ChromeLayoutBase</code> から派生し、設計時の UI の式を宣言し、レンダリングはソースジェネレーターに作らせます。</p>\n<h2 id=\"chrome-と-body\">Chrome と Body<a href=\"#chrome-%E3%81%A8-body\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>ChromeLayoutBase</code> は Blazor の <code>LayoutComponentBase</code> から派生しています。そのため、ルーティングされたページを受け取る <code>Body</code> パラメーターを既に備えています。レイアウト自身が描く外枠は、\n<code>Chrome</code> という別のプロパティをオーバーライドして書きます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">using</span> BlazorCodeFirst;\n<span class=\"keyword\">using</span> <span class=\"keyword\">static</span> BlazorCodeFirst.Html;\n\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> MainLayout : ChromeLayoutBase\n{\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Chrome =&gt;\n        Div.Class(<span class=\"string\">&quot;shell&quot;</span>)[\n            Header[H1[<span class=\"string\">&quot;My App&quot;</span>]],\n            Main.Class(<span class=\"string\">&quot;content&quot;</span>)[Body],\n            Footer[<span class=\"string\">&quot;&#169; 2026&quot;</span>]];\n}\n</pre></div>\n<p>ここの <code>Main[Body]</code> は、Razor の <code>&lt;main&gt;@Body&lt;/main&gt;</code> そのものです。ルーティングされたページを、要素の内容として置いています。下の出力は、ページが入る位置にプレースホルダーを置いたものです。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Chrome =&gt;\n    Div.Class(<span class=\"string\">&quot;shell&quot;</span>)[\n        Header[H1[<span class=\"string\">&quot;My App&quot;</span>]],\n        Main.Class(<span class=\"string\">&quot;content&quot;</span>)[Body],\n        Footer[<span class=\"string\">&quot;&#169; 2026&quot;</span>]];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">div</span> <span class=\"htmlAttributeName\">class</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;shell&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">header</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">h1</span><span class=\"htmlTagDelimiter\">&gt;</span>My App<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">h1</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">header</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">main</span> <span class=\"htmlAttributeName\">class</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;content&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>the routed page<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">main</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">footer</span><span class=\"htmlTagDelimiter\">&gt;</span>&#169; 2026<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">footer</span><span class=\"htmlTagDelimiter\">&gt;</span>\n<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div><h2 id=\"body-ではなく-chrome-である理由\">Body ではなく Chrome である理由<a href=\"#body-%E3%81%A7%E3%81%AF%E3%81%AA%E3%81%8F-chrome-%E3%81%A7%E3%81%82%E3%82%8B%E7%90%86%E7%94%B1\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Blazor は、レイアウトが包む内容を <code>Body</code> という名前のパラメーターで公開するよう求めます。名前は\n<code>Body</code> ちょうどでなければなりません。一方 C# は、1つの型に同じ名前のメンバーを2つ宣言できません。そこで <code>Body</code> は Razor での意味、つまり包まれる側のページのまま残し、レイアウト自身の設計時の式には <code>Chrome</code> という別の名前を付けました。</p>\n<h2 id=\"レイアウトを入れ子にする\">レイアウトを入れ子にする<a href=\"#%E3%83%AC%E3%82%A4%E3%82%A2%E3%82%A6%E3%83%88%E3%82%92%E5%85%A5%E3%82%8C%E5%AD%90%E3%81%AB%E3%81%99%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>レイアウト自身を、別のレイアウトの中に置けます。ページに付けるのとまったく同じように、レイアウトの型に <code>[Layout]</code> を付けます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">using</span> BlazorCodeFirst;\n<span class=\"keyword\">using</span> Microsoft.AspNetCore.Components;\n<span class=\"keyword\">using</span> <span class=\"keyword\">static</span> BlazorCodeFirst.Html;\n\n[Layout(<span class=\"keyword\">typeof</span>(SiteLayout))]\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> DocsLayout : ChromeLayoutBase\n{\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Chrome =&gt; Div.Class(<span class=\"string\">&quot;docs&quot;</span>)[Aside[TableOfContents()], Main[Body]];\n}\n</pre></div>\n<p>入れ子を解決するのは Blazor で、BlazorCodeFirst ではありません。<code>LayoutView</code> がレイアウトの型から属性を読み、それを自分のレイアウトで包みます。BlazorCodeFirst のレイアウトは、通常の\n<code>LayoutComponentBase</code> の子孫です。どの段の <code>Body</code> も、その1つ下の段を受け取ります。<code>SiteLayout</code>\nの <code>Body</code> は描かれた <code>DocsLayout</code> で、その <code>DocsLayout</code> の <code>Body</code> がルーティングされたページです。</p>\n<h2 id=\"renderfragment-はそのまま内容になる\">RenderFragment はそのまま内容になる<a href=\"#renderfragment-%E3%81%AF%E3%81%9D%E3%81%AE%E3%81%BE%E3%81%BE%E5%86%85%E5%AE%B9%E3%81%AB%E3%81%AA%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>Body</code> は BlazorCodeFirst の型ではなく、ただの Blazor の <code>RenderFragment?</code> です。それでも上の\n<code>Main[Body]</code> は、専用の構文なしにコンパイルできます。<code>View</code> が <code>RenderFragment?</code> からの暗黙の変換を持っているからです。そのためフラグメントは、要素の内容が来る場所ならどこにでも書けます。変換元はジェネリックでない <code>RenderFragment</code> だけで、<code>RenderFragment&lt;T&gt;</code> は変換されません。\n<code>Fragment</code> や <code>Raw</code> と同じように、<code>RenderFragment</code> はキーを付けられるフレームを開きません。よって\n<code>ForEach</code> の内容のルートにはできず（<a href=\"/docs/ja/diagnostics#bcf3003\">BCF3003</a>）、装飾も付けられません（<a href=\"/docs/ja/diagnostics#bcf3008\">BCF3008</a>）。</p>\n<p>同じ仕組みで、BlazorCodeFirst のコンポーネントは Razor から渡された子を描けます。\n<code>[Parameter] public RenderFragment? ChildContent</code> を持つコンポーネントは、それを <code>Body</code> とまったく同じように使います。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">using</span> BlazorCodeFirst;\n<span class=\"keyword\">using</span> Microsoft.AspNetCore.Components;\n<span class=\"keyword\">using</span> <span class=\"keyword\">static</span> BlazorCodeFirst.Html;\n\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Card : BodyComponentBase\n{\n    [Parameter]\n    <span class=\"keyword\">public</span> RenderFragment? ChildContent { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\n\n    <span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div.Class(<span class=\"string\">&quot;card&quot;</span>)[ChildContent];\n}\n</pre></div>\n<p>逆向き、つまり BlazorCodeFirst のコードから Razor や手書きのコンポーネントへ内容を渡す場合は、\n<code>Component&lt;T&gt;()</code> を使います。<a href=\"/docs/ja/components-and-reuse#%E5%AD%90%E3%81%AE%E5%86%85%E5%AE%B9%E3%82%92%E6%B8%A1%E3%81%99\">子の内容を渡す</a>を見てください。</p>\n<h2 id=\"読めるが書き換えられない\">読めるが、書き換えられない<a href=\"#%E8%AA%AD%E3%82%81%E3%82%8B%E3%81%8C%E6%9B%B8%E3%81%8D%E6%8F%9B%E3%81%88%E3%82%89%E3%82%8C%E3%81%AA%E3%81%84\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>Chrome</code> と <code>Body</code> は、どちらもコンポーネントの状態を読めます。状態を UI へ映すことが、そもそもの役目だからです。ただし、どちらも状態を書き換えられません。ここでの <code>Body</code> は\n<code>BodyComponentBase</code> のもので、レイアウトがルーティングされたページを受け取るパラメーターではありません。どちらの中で状態を書き換えても <a href=\"/docs/ja/diagnostics#bcf3001\">BCF3001</a> を報告します。通常のコンポーネントの <code>Body</code> に当てはまるのと同じ診断です。</p>\n<h2 id=\"次に読むもの\">次に読むもの<a href=\"#%E6%AC%A1%E3%81%AB%E8%AA%AD%E3%82%80%E3%82%82%E3%81%AE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<ul>\n<li>コンポーネントから別のコンポーネントを呼ぶ方法は<a href=\"/docs/ja/components-and-reuse\">コンポーネントと再利用</a>へ。</li>\n<li>上で使った要素については<a href=\"/docs/ja/elements-and-decorations\">要素と装飾</a>へ。</li>\n</ul>\n"),
        new DocEntry(
            "two-way-binding",
            "双方向バインディング",
            ".Bind は Razor の bind ディレクティブを、属性・イベント・現在値を読むラムダとして明示的に書いたもの。",
            80,
            "write",
            "ja",
            false,
            ["要素をバインドする", "名前を2つとも書く理由", "チェックボックスは-checked-をバインドする", "セッターを明示して正規化する", "数値日付enum", "number-と-date-には不変カルチャーを書く", "解析できない値は元に戻る", "日付には書式が必要", "トリムして配布する場合", "変換を自分で書く", "コンポーネントのパラメーターをバインドする", "何が検査されるか", "次に読むもの"],
            "<p>双方向バインディングは、値を DOM へ書き出し、利用者の編集を自分の状態へ読み戻す、1つの装飾です。<code>.Bind</code> は Razor の <code>@bind</code> にあたります。必要なものが、すべて目に見える引数として並ぶ書き方になっています。ジェネレーターはこれを、属性のフレームと、Blazor 自身の <code>CreateBinder</code>\nを運ぶイベントのフレームへ変換します。生成されたコードが実行時に式ツリーをコンパイルすることはなく、リフレクションを使うこともありません。enum をバインドしたときだけ、フレームワーク自身の変換器の中で1つだけリフレクションによる参照が起きます。</p>\n<h2 id=\"要素をバインドする\">要素をバインドする<a href=\"#%E8%A6%81%E7%B4%A0%E3%82%92%E3%83%90%E3%82%A4%E3%83%B3%E3%83%89%E3%81%99%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>値を運ぶ属性、変化を知らせるイベント、そして今の値を読むラムダを指定します。この3つのうち、マークアップに現れるのは最初の1つだけです。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div[\n        Input.Type(<span class=\"string\">&quot;text&quot;</span>).Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _name),\n        P[$<span class=\"string\">&quot;Hello, {_name}&quot;</span>]];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">input</span> <span class=\"htmlAttributeName\">type</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;text&quot;</span> <span class=\"htmlAttributeName\">value</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;Ada&quot;</span><span class=\"htmlTagDelimiter\">&gt;</span>\n    <span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">p</span><span class=\"htmlTagDelimiter\">&gt;</span>Hello, Ada<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">p</span><span class=\"htmlTagDelimiter\">&gt;</span>\n<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">div</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p>このラムダは両方向に読まれます。本体は属性の値になり、ゲッターだけのこの形では、同じ本体が、ジェネレーターの書く代入の左辺にもなります。そのため対象は代入できるものでなければなりません。フィールド、セッターを持つプロパティ、あるいはそのどちらかを通る経路（<code>_form.Name</code>、\n<code>Model.Items[0].Title</code>、<code>_dict[&quot;k&quot;]</code>）です。<code>() =&gt; _name.ToUpper()</code> のような計算した式は\n<a href=\"/docs/ja/diagnostics#bcf3018\">BCF3018</a> を報告します。そう書きたいときは、下のセッターを明示する形を使います。</p>\n<p>キー入力のたびにバインドするなら <code>&quot;oninput&quot;</code>、要素からフォーカスが外れたときにバインドするなら\n<code>&quot;onchange&quot;</code> を使います。通常使うのはこの2つですが、組み合わせを縛る一覧はありません。制約は次の3つの規則だけです。</p>\n<ul>\n<li>どちらの名前も、空でないコンパイル時定数であること（<a href=\"/docs/ja/diagnostics#bcf3011\">BCF3011</a>）</li>\n<li>イベントの名前が <code>on</code> で始まること（<a href=\"/docs/ja/diagnostics#bcf3019\">BCF3019</a>）</li>\n<li>どちらも、同じ要素の別の装飾で既にバインドされていないこと（<a href=\"/docs/ja/diagnostics#bcf3010\">BCF3010</a>）</li>\n</ul>\n<p>名前を HTML と照合する検査はありません。</p>\n<h2 id=\"名前を2つとも書く理由\">名前を2つとも書く理由<a href=\"#%E5%90%8D%E5%89%8D%E3%82%922%E3%81%A4%E3%81%A8%E3%82%82%E6%9B%B8%E3%81%8F%E7%90%86%E7%94%B1\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>Razor は属性をマークアップから推論します。<code>.razor</code> のファイルからリテラルの <code>type=&quot;checkbox&quot;</code> を読み取り、<code>value</code> ではなく <code>checked</code> をバインドします。この API には、読み取れるリテラルがありません。タグは文字列で、<code>type</code> は式です。<code>Input.Type(kind)</code> は通常の C# の呼び出しで、その値は実行するまで決まらないこともあります。そのため推論を照合する対象がありません。</p>\n<p><code>value</code> を既定にすると、もっとも避けたい失敗が起こります。チェックボックスが間違った属性にバインドされ、それが黙って起き、知らせる診断も出ない、という失敗です。そのためこの API 全体の規則は <strong>確かめられることだけを推論する</strong> です。要素の側は確かめられないので推論せず、代わりに短い文字列を2つ書きます。</p>\n<p>この間違いのうち、確かめ <em>られる</em> 半分は検出します。<code>on</code> で始まらないイベントの名前は BCF3019 を報告します。そのため2つの引数を取り違えても、何もしない属性が増えるのではなく、コンパイル時に止まります。</p>\n<p><code>.Bind</code> のコンポーネント側は名前を推論します。同じ規則が、そちらでは推論を許すからです。<a href=\"#%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%81%AE%E3%83%91%E3%83%A9%E3%83%A1%E3%83%BC%E3%82%BF%E3%83%BC%E3%82%92%E3%83%90%E3%82%A4%E3%83%B3%E3%83%89%E3%81%99%E3%82%8B\">コンポーネントのパラメーターをバインドする</a>を見てください。</p>\n<h2 id=\"チェックボックスは-checked-をバインドする\">チェックボックスは <code>checked</code> をバインドする<a href=\"#%E3%83%81%E3%82%A7%E3%83%83%E3%82%AF%E3%83%9C%E3%83%83%E3%82%AF%E3%82%B9%E3%81%AF-checked-%E3%82%92%E3%83%90%E3%82%A4%E3%83%B3%E3%83%89%E3%81%99%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>チェックボックスは、<code>bool</code> を <code>checked</code> 属性へ、<code>onchange</code> でバインドします。同じ装飾で、最初の引数だけが違い、出力に出る属性も違います。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Label[\n        Input.Type(<span class=\"string\">&quot;checkbox&quot;</span>).Bind(<span class=\"string\">&quot;checked&quot;</span>, <span class=\"string\">&quot;onchange&quot;</span>, () =&gt; _agreed),\n        <span class=\"string\">&quot; I agree&quot;</span>];\n</pre></div><div class=\"html\"><pre>\n<span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">label</span><span class=\"htmlTagDelimiter\">&gt;</span><span class=\"htmlTagDelimiter\">&lt;</span><span class=\"htmlElementName\">input</span> <span class=\"htmlAttributeName\">type</span><span class=\"htmlOperator\">=</span><span class=\"htmlAttributeValue\">&quot;checkbox&quot;</span> <span class=\"htmlAttributeName\">checked</span><span class=\"htmlTagDelimiter\">&gt;</span> I agree<span class=\"htmlTagDelimiter\">&lt;/</span><span class=\"htmlElementName\">label</span><span class=\"htmlTagDelimiter\">&gt;</span>\n</pre></div>\n<p><code>bool</code> は HTML の真偽値属性の形で、<a href=\"/docs/ja/elements-and-decorations#%E8%A3%85%E9%A3%BE\"><code>.Attr</code> が取る</a>のと同じものです。<code>true</code> なら値の空な属性として出力し、<code>false</code> なら属性ごと出しません。</p>\n<h2 id=\"セッターを明示して正規化する\">セッターを明示して正規化する<a href=\"#%E3%82%BB%E3%83%83%E3%82%BF%E3%83%BC%E3%82%92%E6%98%8E%E7%A4%BA%E3%81%97%E3%81%A6%E6%AD%A3%E8%A6%8F%E5%8C%96%E3%81%99%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>4つ目の引数を渡すと、生成される代入の代わりに自分のセッターが使われます。検証や正規化、編集のたびに実行したい処理は、ここに置きます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">string</span> _name = <span class=\"string\">&quot;&quot;</span>;\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Input.Type(<span class=\"string\">&quot;text&quot;</span>).Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _name, v =&gt; _name = v.Trim());\n</pre></div>\n<p>これは Razor が <code>@bind:get</code> / <code>@bind:set</code> と <code>@bind:after</code> に分けているものを、まとめて引き受けます。セッターが書き込みそのものなので、後で実行したかった処理も同じラムダに入ります。ただし書き込みは自分で行います。セッターを渡した時点で、代わりに代入する処理はなくなります。メソッドグループ（<code>SetName</code>）も使え、ラムダの本体はブロックでもよく、<code>Task</code> を返せば <code>async</code>\nの形も使えます。</p>\n<div class=\"csharp\"><pre>\nInput.Type(<span class=\"string\">&quot;text&quot;</span>).Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _query, <span class=\"keyword\">async</span> v =&gt;\n{\n    _query = v;\n    <span class=\"keyword\">await</span> SearchAsync(v);\n});\n</pre></div>\n<p>代入できるゲッターが必要なのは、ゲッターだけの形のときだけです。セッターがあれば、ゲッターは読まれるだけなので、どんな式でもかまいません。ただしゲッター自身は、どちらの形でも、その場に書いた式本体のラムダである必要があります（<a href=\"/docs/ja/diagnostics#bcf3017\">BCF3017</a>）。その本体が、属性の値とバインダーの両方へ写されるからです。</p>\n<p>正規化するセッターは、ずれを生みます。要素は入力した文字を表示し、フィールドは切り詰めた値を持ちます。通常の差分計算は何も書きません。前回のレンダリングからレンダーツリーが変わっていないからです。<code>value</code> か <code>checked</code> のバインドなら、<code>.Bind</code> はその属性を DOM の再同期に登録してこのずれを埋め、要素の表示は正規化した値に直ります。設定は不要です。</p>\n<p>登録される名前はこの2つだけです。Blazor のクライアントが返してくるのは、フォーム要素自身の\n<code>value</code>、チェックボックスなら <code>checked</code> で、それ以外は返ってきません。ほかの属性へのバインドは何も登録しません。カスタム要素での <code>.Bind(&quot;hue&quot;, &quot;onhuechange&quot;, () =&gt; _hue, Normalize)</code> が、よくある形です。セッターは変わらず実行され、新しい値も次のレンダリングで通常の差分計算によって\nDOM へ届きます。行われないのは、上に書いた修復だけです。この修復は、正規化してもレンダーツリーが変わらず、要素が入力した文字を表示し続ける場合のためにあります。</p>\n<p>テキスト入力を空にしたとき、セッターが受け取るのは <code>&quot;&quot;</code> で、<code>null</code> ではありません。そのため引数の型は null 許容でない <code>string</code> です。セッターから自分の状態へ書き込むのは許されています。<code>Body</code>\nのほかの場所で書き込めば <a href=\"/docs/ja/diagnostics#bcf3001\">BCF3001</a> になります。セッターだけが例外なのは、<code>.OnClick</code> のラムダと同じ遅延したハンドラーで、ツリーを組み立てている最中には実行されないためです。</p>\n<h2 id=\"数値日付enum\">数値、日付、enum<a href=\"#%E6%95%B0%E5%80%A4%E6%97%A5%E4%BB%98enum\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>カルチャーを書けば、どの型でもバインドできます。カルチャーは最後の引数で、省略はできません。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">int</span> _age;\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Input.Type(<span class=\"string\">&quot;number&quot;</span>).Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _age, CultureInfo.InvariantCulture);\n</pre></div>\n<p>このカルチャーが、出ていく値を書式化し、戻ってきた値を解析します。通るのは Blazor 自身の\n<code>BindConverter</code> です。数値、日付、時刻、<code>Guid</code>、enum、そしてそれらの null 許容形が、どれも動きます。変換がこのライブラリのものではなく、フレームワークのものだからです。</p>\n<p>既定値ではなく引数にしているのは、既定値にすれば、見えないところでカルチャーが選ばれるからです。\nRazor は要素のリテラルな <code>type</code> から選びます。この API はそのリテラルを読みません。属性の名前を推論しないのと同じ理由です。そのため選択は、呼び出し側へ移してあります。</p>\n<h3 id=\"number-と-date-には不変カルチャーを書く\"><code>number</code> と <code>date</code> には不変カルチャーを書く<a href=\"#number-%E3%81%A8-date-%E3%81%AB%E3%81%AF%E4%B8%8D%E5%A4%89%E3%82%AB%E3%83%AB%E3%83%81%E3%83%A3%E3%83%BC%E3%82%92%E6%9B%B8%E3%81%8F\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>&lt;input type=&quot;number&quot;&gt;</code> と <code>&lt;input type=&quot;date&quot;&gt;</code> は、利用者のロケールではなく固定の書式で定義されています。ここで <code>CultureInfo.CurrentCulture</code> を使うと、小数点にコンマを使うロケールで、要素の受け取れない値になります。</p>\n<p><strong>これは診断しません。</strong> 検査するには <code>type</code> を読む必要がありますが、ここでの <code>type</code> は式です。リテラルを書いたときだけ発火する規則は、同じ誤りをある書き方では捕まえ、別の書き方では見逃します。この2つには <code>CultureInfo.InvariantCulture</code> を書いてください。利用者が文章として読む値には現在のカルチャーを使います。</p>\n<h3 id=\"解析できない値は元に戻る\">解析できない値は元に戻る<a href=\"#%E8%A7%A3%E6%9E%90%E3%81%A7%E3%81%8D%E3%81%AA%E3%81%84%E5%80%A4%E3%81%AF%E5%85%83%E3%81%AB%E6%88%BB%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>入力された文字を変換器が読めない場合、セッターは呼ばれません。フィールドと要素は、どちらも前の値に戻ります。これは Blazor の挙動で、<code>.Bind</code> でも、上に書いた DOM の再同期を通じて同じ結果になります。</p>\n<p>ここでイベントをどちらにするかは、意識して選ぶ必要があります。<code>&quot;oninput&quot;</code> では巻き戻しがキー入力のたびに実行されるので、<code>int</code> のバインドに入力した小数点は残りません。<code>4.</code> が拒否され、<code>.</code> がそのまま取り去られます。数値の入力では、多くの場合これは望ましくありません。</p>\n<div class=\"csharp\"><pre>\n<span class=\"comment\">// フォーカスが外れたときに巻き戻すので、入力途中の数値が消えません。</span>\nInput.Type(<span class=\"string\">&quot;number&quot;</span>).Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;onchange&quot;</span>, () =&gt; _amount, CultureInfo.InvariantCulture);\n</pre></div>\n<p><code>&quot;oninput&quot;</code> が正しいのは、途中の値がどれも意味を持つときです。range のスライダーや、入力できる文字をすべて受け付ける text の欄がこれにあたります。</p>\n<p>欄を空にした場合は事情が異なり、これは拒否ではありません。Blazor は空文字列をその型の既定値として読むので、<code>int</code> のバインドを空にすると前の値が残るのではなく <code>0</code> になります。値が本当に任意なら\n<code>int?</code> をバインドしてください。そちらは <code>null</code> を受け取ります。</p>\n<h3 id=\"日付には書式が必要\">日付には書式が必要<a href=\"#%E6%97%A5%E4%BB%98%E3%81%AB%E3%81%AF%E6%9B%B8%E5%BC%8F%E3%81%8C%E5%BF%85%E8%A6%81\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>date の入力は <code>yyyy-MM-dd</code> を要求します。Razor と違い、この API はそれを <code>type</code> から補えません。カルチャーの1つ手前の引数として書きます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> DateOnly _due = <span class=\"keyword\">new</span>(<span class=\"number\">2026</span>, <span class=\"number\">8</span>, <span class=\"number\">14</span>);\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Input.Type(<span class=\"string\">&quot;date&quot;</span>).Bind(\n        <span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _due, <span class=\"string\">&quot;yyyy-MM-dd&quot;</span>, CultureInfo.InvariantCulture);\n</pre></div>\n<p>書式を受け取るのは <code>DateTime</code> / <code>DateTimeOffset</code> / <code>DateOnly</code> / <code>TimeOnly</code> とその null 許容形だけで、ほかの型は受け取りません。フレームワークが書式付きの変換器を宣言しているのが、その8つだからです。<code>int</code> に書けば <a href=\"/docs/ja/diagnostics#bcf3031\">BCF3031</a> です。数値を書式化したい場合は、ゲッターで書式化し、セッターを明示して解析してください。</p>\n<h3 id=\"トリムして配布する場合\">トリムして配布する場合<a href=\"#%E3%83%88%E3%83%AA%E3%83%A0%E3%81%97%E3%81%A6%E9%85%8D%E5%B8%83%E3%81%99%E3%82%8B%E5%A0%B4%E5%90%88\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>値型を1つでもバインドすると、Blazor の <code>BindConverter</code> が丸ごと保持されます。自分がバインドしない型の変換器も残ります。トリム済みの self-contained な publish で実測しました。\n<code>Microsoft.AspNetCore.Components.dll</code> のおよそ 10 KB にあたります。<code>string</code> と <code>bool</code> だけをバインドするアプリに、このコストはかかりません。バインドの個数ではなく、一度きりのコストです。</p>\n<h3 id=\"変換を自分で書く\">変換を自分で書く<a href=\"#%E5%A4%89%E6%8F%9B%E3%82%92%E8%87%AA%E5%88%86%E3%81%A7%E6%9B%B8%E3%81%8F\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>明示する書き方も、これまでどおり使えます。変換ではなく検証をしたいときは、そちらが向いています。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">decimal</span> _amount;\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Input.Type(<span class=\"string\">&quot;text&quot;</span>).Bind(\n        <span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;onchange&quot;</span>,\n        () =&gt; _amount.ToString(CultureInfo.InvariantCulture),\n        v =&gt; _amount = <span class=\"keyword\">decimal</span>.TryParse(v, NumberStyles.Number, CultureInfo.InvariantCulture, <span class=\"keyword\">out</span> <span class=\"keyword\">var</span> d)\n            ? d\n            : _amount);\n</pre></div>\n<p>ここでは <code>Parse</code> ではなく <code>TryParse</code> を使ってください。セッターから投げられた例外は、フレームワークが値を拒否する経路ではありません。描画そのものが失敗します。</p>\n<h2 id=\"コンポーネントのパラメーターをバインドする\">コンポーネントのパラメーターをバインドする<a href=\"#%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%81%AE%E3%83%91%E3%83%A9%E3%83%A1%E3%83%BC%E3%82%BF%E3%83%BC%E3%82%92%E3%83%90%E3%82%A4%E3%83%B3%E3%83%89%E3%81%99%E3%82%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>コンポーネントでは、名前を書く代わりに導きます。導いた名前を確かめられるからです。<code>.Bind</code> はラムダでパラメーターを選び、ジェネレーターが <code>{Name}Changed</code> を、コンポーネントが宣言していれば <code>{Name}Expression</code> も足します。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">using</span> Microsoft.AspNetCore.Components.Forms;\n\n<span class=\"keyword\">private</span> <span class=\"keyword\">readonly</span> NameModel _model = <span class=\"keyword\">new</span>();\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;InputText&gt;().Bind(c =&gt; c.Value, () =&gt; _model.Name);\n</pre></div>\n<p>この1回の呼び出しが、<code>Value</code>、<code>ValueChanged</code>、<code>ValueExpression</code> を渡します。導いた名前はどれもコンポーネントの型から探すので、<code>{Name}Changed</code> が無かったり綴りが違ったりすれば、何もバインドしないのではなく <a href=\"/docs/ja/diagnostics#bcf3020\">BCF3020</a> を報告します。要素側との非対称が、行き当たりばったりではなく規則だと言えるのは、この検査があるからです。</p>\n<p>対象を参照渡しではなくゲッターのラムダとして書くのは、<code>{Name}Expression</code> のためです。<code>EditForm</code>\nの下にあるコンポーネントは、その式から <code>FieldIdentifier</code> を解決します。この識別子が入力をモデルのプロパティに結び付けるので、検証のメッセージが正しいフィールドに届きます。ほかの書き方では、これを渡せません。</p>\n<p>周りの <code>EditForm</code> も同じ書き方です。<code>EditForm.ChildContent</code> は <code>RenderFragment&lt;EditContext&gt;</code> で、角括弧はコンテキストを捨てて、そこへ内容を渡します。下の内容には、ほかに必要なものがありません。\n<code>EditContext</code> を読む内容だけ、<code>.Template</code> で指定します。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Component&lt;EditForm&gt;()\n        .Param(form =&gt; form.Model, _model)[\n            Component&lt;NameFields&gt;().Param(fields =&gt; fields.Value, _model)];\n</pre></div>\n<p>バインドした入力は、角括弧の中に直接置いても、独立したコンポーネントに置いてもかまいません。上のバインドと、それが渡す <code>ValueExpression</code> は、どちらでも変わりません。<code>EditContext</code> を読む書き方と、<code>.Param</code> でキャッシュしたデリゲートを渡すほうがよい場面については、<a href=\"/docs/ja/components-and-reuse#%E3%82%B8%E3%82%A7%E3%83%8D%E3%83%AA%E3%83%83%E3%82%AF%E3%81%AA%E3%83%95%E3%83%A9%E3%82%B0%E3%83%A1%E3%83%B3%E3%83%88%E3%81%AE%E3%83%91%E3%83%A9%E3%83%A1%E3%83%BC%E3%82%BF%E3%83%BC\">ジェネリックなフラグメントのパラメーター</a>を見てください。</p>\n<p>セッターを明示する形と <code>async</code> のセッターは、こちらでも使えます。意味は要素のときと同じです。\n<code>TValue</code> は、カルチャーと書式のどちらも取りません。値が向かう先は DOM ではなくパラメーターです。途中で書式化や解析が入らないので、引数に書き添える選択がそもそもありません。</p>\n<p><code>Component&lt;T&gt;()</code> が、同じプロジェクトで宣言した <code>.razor</code> のコンポーネントを指定できないことは覚えておいてください（<a href=\"/docs/ja/diagnostics#bcf3012\">BCF3012</a>）。\n<code>InputText</code> のようなフレームワークのコンポーネントと、手書きの C# のコンポーネントは、いつでも解決します。</p>\n<h2 id=\"何が検査されるか\">何が検査されるか<a href=\"#%E4%BD%95%E3%81%8C%E6%A4%9C%E6%9F%BB%E3%81%95%E3%82%8C%E3%82%8B%E3%81%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>.Bind</code> を読む診断は6つあり、どれも<a href=\"/docs/ja/diagnostics\">リファレンス</a>に項があります。</p>\n<ul>\n<li><a href=\"/docs/ja/diagnostics#bcf3017\">BCF3017</a> はゲッターの形を見る</li>\n<li><a href=\"/docs/ja/diagnostics#bcf3018\">BCF3018</a> は、ゲッターだけの形で代入できない対象を見る</li>\n<li><a href=\"/docs/ja/diagnostics#bcf3019\">BCF3019</a> は <code>on</code> の無いイベント名を見る</li>\n<li><a href=\"/docs/ja/diagnostics#bcf3020\">BCF3020</a> は、対応する変更コールバックの無いコンポーネントを見る</li>\n<li><a href=\"/docs/ja/diagnostics#bcf3024\">BCF3024</a> は、<code>.Class</code> と並んだ <code>class</code> のバインドを見る</li>\n<li><a href=\"/docs/ja/diagnostics#bcf3031\">BCF3031</a> は、値の型に変換器の無い書式を見る</li>\n</ul>\n<p>1つの要素が <code>.Bind</code> を複数持つことはできます。そのうち2つが属性の名前かイベントの名前を共有すれば <a href=\"/docs/ja/diagnostics#bcf3010\">BCF3010</a> で、どの装飾を2つ重ねても出るのと同じ重複です。\nDOM の再同期の対象は <code>value</code> と <code>checked</code> だけです。利用者が入力した文字の上に、正規化した値を置き直す修復のことです。ブラウザーがイベントと一緒に返してくるのが、その2つだけだからです。</p>\n<h2 id=\"次に読むもの\">次に読むもの<a href=\"#%E6%AC%A1%E3%81%AB%E8%AA%AD%E3%82%80%E3%82%82%E3%81%AE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<ul>\n<li>これが組み立てられている、一方向の <code>.Attr</code> と <code>.On</code> は<a href=\"/docs/ja/elements-and-decorations#%E8%A3%85%E9%A3%BE\">要素と装飾</a>へ。</li>\n<li><code>.Param</code> とコンポーネント周りの残りは<a href=\"/docs/ja/components-and-reuse\">コンポーネントと再利用</a>へ。</li>\n</ul>\n"),
        new DocEntry(
            "element-reference",
            "要素リファレンス",
            "この API が宣言する要素ヘルパー、装飾、制御構文の一覧。空要素には印を付けている。",
            90,
            "reference",
            "ja",
            false,
            ["要素", "セクション", "グルーピング", "テキストレベル", "編集", "埋め込み", "表", "フォーム", "対話", "それ以外-elementtag", "要素に付ける装飾", "構文", "コンポーネントの呼び出しに付ける装飾", "基底型"],
            "<p>この API が宣言するものの一覧です。それぞれの意味は<a href=\"/docs/ja/elements-and-decorations\">要素と装飾</a>と<a href=\"/docs/ja/control-flow\">制御構文</a>にあります。</p>\n<h2 id=\"要素\">要素<a href=\"#%E8%A6%81%E7%B4%A0\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>ヘルパーの名前はタグ名の先頭1文字だけを大文字にしたものです。<code>FigCaption</code> ではなく\n<code>Figcaption</code> です。アスタリスクは空要素の印で、子を取りません（<a href=\"/docs/ja/diagnostics#bcf3016\">BCF3016</a>）。</p>\n<p>100個あります。HTML Living Standard が準拠要素として挙げ、かつレンダーツリーで意味を持つ要素のすべてです。</p>\n<h3 id=\"セクション\">セクション<a href=\"#%E3%82%BB%E3%82%AF%E3%82%B7%E3%83%A7%E3%83%B3\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Address</code>, <code>Article</code>, <code>Aside</code>, <code>Footer</code>, <code>H1</code>, <code>H2</code>, <code>H3</code>, <code>H4</code>, <code>H5</code>, <code>H6</code>, <code>Header</code>, <code>Hgroup</code>,\n<code>Main</code>, <code>Nav</code>, <code>Search</code>, <code>Section</code></p>\n<h3 id=\"グルーピング\">グルーピング<a href=\"#%E3%82%B0%E3%83%AB%E3%83%BC%E3%83%94%E3%83%B3%E3%82%B0\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Blockquote</code>, <code>Dd</code>, <code>Div</code>, <code>Dl</code>, <code>Dt</code>, <code>Figcaption</code>, <code>Figure</code>, <code>Hr</code>*, <code>Li</code>, <code>Menu</code>, <code>Ol</code>, <code>P</code>,\n<code>Pre</code>, <code>Ul</code></p>\n<h3 id=\"テキストレベル\">テキストレベル<a href=\"#%E3%83%86%E3%82%AD%E3%82%B9%E3%83%88%E3%83%AC%E3%83%99%E3%83%AB\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>A</code>, <code>Abbr</code>, <code>B</code>, <code>Bdi</code>, <code>Bdo</code>, <code>Br</code>*, <code>Cite</code>, <code>Code</code>, <code>Data</code>, <code>Dfn</code>, <code>Em</code>, <code>I</code>, <code>Kbd</code>, <code>Mark</code>,\n<code>Q</code>, <code>Rp</code>, <code>Rt</code>, <code>Ruby</code>, <code>S</code>, <code>Samp</code>, <code>Small</code>, <code>Span</code>, <code>Strong</code>, <code>Sub</code>, <code>Sup</code>, <code>Time</code>, <code>U</code>, <code>Var</code>,\n<code>Wbr</code>*</p>\n<h3 id=\"編集\">編集<a href=\"#%E7%B7%A8%E9%9B%86\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Del</code>, <code>Ins</code></p>\n<h3 id=\"埋め込み\">埋め込み<a href=\"#%E5%9F%8B%E3%82%81%E8%BE%BC%E3%81%BF\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Area</code>*, <code>Audio</code>, <code>Canvas</code>, <code>Embed</code>*, <code>Iframe</code>, <code>Img</code>*, <code>Map</code>, <code>Picture</code>, <code>Source</code>*, <code>Track</code>*,\n<code>Video</code></p>\n<h3 id=\"表\">表<a href=\"#%E8%A1%A8\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Caption</code>, <code>Col</code>*, <code>Colgroup</code>, <code>Table</code>, <code>Tbody</code>, <code>Td</code>, <code>Tfoot</code>, <code>Th</code>, <code>Thead</code>, <code>Tr</code></p>\n<h3 id=\"フォーム\">フォーム<a href=\"#%E3%83%95%E3%82%A9%E3%83%BC%E3%83%A0\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Button</code>, <code>Datalist</code>, <code>Fieldset</code>, <code>Form</code>, <code>Input</code>*, <code>Label</code>, <code>Legend</code>, <code>Meter</code>, <code>Optgroup</code>,\n<code>Option</code>, <code>Output</code>, <code>Progress</code>, <code>Select</code>, <code>Selectedcontent</code>, <code>Textarea</code></p>\n<h3 id=\"対話\">対話<a href=\"#%E5%AF%BE%E8%A9%B1\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Details</code>, <code>Dialog</code>, <code>Summary</code></p>\n<h3 id=\"それ以外-elementtag\">それ以外: <code>Element(tag)</code><a href=\"#%E3%81%9D%E3%82%8C%E4%BB%A5%E5%A4%96-elementtag\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p><code>Element(&quot;my-widget&quot;)</code> は、ヘルパーの無い要素を書くための構文です。カスタム要素と Web Components、そして意図して外した標準要素がこれに該当します。文書と <code>&lt;head&gt;</code> の要素、生テキスト要素、<code>template</code>\nと <code>slot</code>、<code>object</code>、SVG と MathML の要素です。タグはタグ名の形をしたコンパイル時定数でなければなりません（<a href=\"/docs/ja/diagnostics#bcf3009\">BCF3009</a>）。何が該当し、なぜ該当するのかは<a href=\"/docs/ja/elements-and-decorations#%E8%A6%81%E7%B4%A0\">要素と装飾</a>にあります。</p>\n<h2 id=\"要素に付ける装飾\">要素に付ける装飾<a href=\"#%E8%A6%81%E7%B4%A0%E3%81%AB%E4%BB%98%E3%81%91%E3%82%8B%E8%A3%85%E9%A3%BE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<table>\n<thead>\n<tr>\n<th>装飾</th>\n<th>書くもの</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>.Attr(name, value)</code></td>\n<td>任意の属性を名前で</td>\n</tr>\n<tr>\n<td><code>.Class(value)</code></td>\n<td>class のチャネル。畳まれる（<a href=\"/docs/ja/elements-and-decorations#class-%E3%81%AE%E3%83%81%E3%83%A3%E3%83%8D%E3%83%AB\">class のチャネル</a>）</td>\n</tr>\n<tr>\n<td><code>.Id(value)</code></td>\n<td><code>id</code></td>\n</tr>\n<tr>\n<td><code>.Title(value)</code></td>\n<td><code>title</code></td>\n</tr>\n<tr>\n<td><code>.Role(value)</code></td>\n<td><code>role</code></td>\n</tr>\n<tr>\n<td><code>.Type(value)</code></td>\n<td><code>type</code></td>\n</tr>\n<tr>\n<td><code>.Src(value)</code></td>\n<td><code>src</code></td>\n</tr>\n<tr>\n<td><code>.Alt(value)</code></td>\n<td><code>alt</code></td>\n</tr>\n<tr>\n<td><code>.Href(value)</code></td>\n<td><code>href</code></td>\n</tr>\n<tr>\n<td><code>.On(name, handler)</code></td>\n<td>任意のイベントを名前で</td>\n</tr>\n<tr>\n<td><code>.OnClick(handler)</code></td>\n<td><code>onclick</code></td>\n</tr>\n<tr>\n<td><code>.PreventDefault()</code></td>\n<td>直前のイベントの <code>preventDefault</code></td>\n</tr>\n<tr>\n<td><code>.StopPropagation()</code></td>\n<td>直前のイベントの <code>stopPropagation</code></td>\n</tr>\n<tr>\n<td><code>.Bind(…)</code></td>\n<td>双方向バインド（<a href=\"/docs/ja/two-way-binding\">双方向バインディング</a>）</td>\n</tr>\n<tr>\n<td><code>.Key(value)</code></td>\n<td>差分用のキー。マークアップには残らない（<a href=\"/docs/ja/control-flow#foreach-%E3%81%A8%E3%81%9D%E3%81%AE%E3%82%AD%E3%83%BC\">制御構文</a>）</td>\n</tr>\n<tr>\n<td><code>.Ref(capture)</code></td>\n<td>要素参照。マークアップには残らない</td>\n</tr>\n</tbody>\n</table>\n<p>名前の付いたものは略記であって、別の仕組みではありません。<code>.Id(&quot;x&quot;)</code> と <code>.Attr(&quot;id&quot;, &quot;x&quot;)</code> は同じフレームを出し、どちらも同じチャネルを数えます（<a href=\"/docs/ja/diagnostics#bcf3010\">BCF3010</a>）。</p>\n<h2 id=\"構文\">構文<a href=\"#%E6%A7%8B%E6%96%87\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<table>\n<thead>\n<tr>\n<th>構文</th>\n<th>すること</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>If(condition, then, otherwise?)</code></td>\n<td>分岐。互いに重ならないシーケンス範囲を取る</td>\n</tr>\n<tr>\n<td><code>ForEach(source, key, content)</code></td>\n<td>キー付きのリスト</td>\n</tr>\n<tr>\n<td><code>Fragment(children…)</code></td>\n<td>包む要素を出さずに子をまとめる</td>\n</tr>\n<tr>\n<td><code>Raw(html)</code></td>\n<td>信頼できる HTML をそのまま差し込む</td>\n</tr>\n<tr>\n<td><code>Slot</code></td>\n<td><code>SlotView</code> を返す <code>[ViewPart]</code> が、呼び出し側の子を置く場所</td>\n</tr>\n<tr>\n<td><code>Component&lt;T&gt;()</code></td>\n<td>Blazor コンポーネントを呼ぶ</td>\n</tr>\n</tbody>\n</table>\n<h2 id=\"コンポーネントの呼び出しに付ける装飾\">コンポーネントの呼び出しに付ける装飾<a href=\"#%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%81%AE%E5%91%BC%E3%81%B3%E5%87%BA%E3%81%97%E3%81%AB%E4%BB%98%E3%81%91%E3%82%8B%E8%A3%85%E9%A3%BE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<table>\n<thead>\n<tr>\n<th>装飾</th>\n<th>書くもの</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>.Param(selector, value)</code></td>\n<td><code>[Parameter]</code> を1つ</td>\n</tr>\n<tr>\n<td><code>.Template(selector, template)</code></td>\n<td><code>RenderFragment&lt;T&gt;</code> のパラメーター</td>\n</tr>\n<tr>\n<td><code>.Bind(selector, …)</code></td>\n<td>パラメーターの双方向バインド（<a href=\"/docs/ja/two-way-binding#%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%81%AE%E3%83%91%E3%83%A9%E3%83%A1%E3%83%BC%E3%82%BF%E3%83%BC%E3%82%92%E3%83%90%E3%82%A4%E3%83%B3%E3%83%89%E3%81%99%E3%82%8B\">双方向バインディング</a>）</td>\n</tr>\n<tr>\n<td><code>.Key(value)</code></td>\n<td>差分用のキー</td>\n</tr>\n<tr>\n<td><code>.RenderMode(mode)</code></td>\n<td>呼び出し側のレンダーモード（<a href=\"/docs/ja/installation-and-hosting#%E3%83%AC%E3%83%B3%E3%83%80%E3%83%BC%E3%83%A2%E3%83%BC%E3%83%89%E3%82%92%E6%8C%87%E5%AE%9A%E3%81%99%E3%82%8B\">導入とホスティング</a>）</td>\n</tr>\n<tr>\n<td><code>.Ref(capture)</code></td>\n<td>コンポーネント参照</td>\n</tr>\n</tbody>\n</table>\n<p>角括弧に書いた子の内容は <code>ChildContent</code> を設定し、そのパラメーターのバインドとして数えます（<a href=\"/docs/ja/diagnostics#bcf3007\">BCF3007</a>）。</p>\n<h2 id=\"基底型\">基底型<a href=\"#%E5%9F%BA%E5%BA%95%E5%9E%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<table>\n<thead>\n<tr>\n<th>型</th>\n<th>用途</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>BodyComponentBase</code></td>\n<td>コンポーネント。<code>Body</code> をオーバーライドする</td>\n</tr>\n<tr>\n<td><code>ChromeLayoutBase</code></td>\n<td>レイアウト。<code>Chrome</code> をオーバーライドする（<a href=\"/docs/ja/layouts\">レイアウト</a>）</td>\n</tr>\n<tr>\n<td><code>[ViewPart]</code></td>\n<td>マークアップを呼び出し側へ展開するメソッド</td>\n</tr>\n<tr>\n<td><code>SlotView</code></td>\n<td>呼び出し側の子を受け取るパーツの戻り値の型</td>\n</tr>\n</tbody>\n</table>\n"),
        new DocEntry(
            "diagnostics",
            "診断",
            "このコンパイラが報告する全診断と、それぞれの意味、代わりに書くべきコード。ビルドが出力した ID でページ内を検索する。",
            100,
            "reference",
            "ja",
            false,
            ["クラスとそのゲッター", "bcf1001", "bcf1002", "bcf1003", "bcf1004", "bcf1005", "この-api-が読まれる場所", "bcf2001", "bcf3029", "bcf3030", "bcf3001", "bcf3015", "要素", "bcf3009", "bcf3016", "bcf3027", "装飾", "bcf3008", "bcf3026", "bcf3010", "bcf3011", "bcf3023", "bcf3024", "bcf3033", "bcf3034", "イベント", "bcf3019", "bcf3028", "bcf3035", "bcf3036", "bcf3038", "制御構文", "bcf3002", "bcf3003", "bcf3004", "bcf3032", "コンポーネント", "bcf3005", "bcf3006", "bcf3007", "bcf3012", "bcf3013", "bcf3014", "bcf3022", "bcf3025", "双方向バインディング", "bcf3017", "bcf3018", "bcf3020", "bcf3031", "次に読むもの"],
            "<p>このコンパイラが報告する診断のすべてと、その意味と、代わりに書くものです。</p>\n<p>ビルドは ID を表示します。このページをその ID で検索してください。</p>\n<h2 id=\"クラスとそのゲッター\">クラスとそのゲッター<a href=\"#%E3%82%AF%E3%83%A9%E3%82%B9%E3%81%A8%E3%81%9D%E3%81%AE%E3%82%B2%E3%83%83%E3%82%BF%E3%83%BC\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf1001\">BCF1001<a href=\"#bcf1001\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. <code>Body</code> または <code>Chrome</code> を宣言するクラスが <code>partial</code> ではないため、生成される <code>RenderView</code>\nを書き込む先がありません。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">class</span> Home : BodyComponentBase          <span class=\"comment\">// BCF1001</span>\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Home : BodyComponentBase  <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>修飾子が必要なのは、オーバーライドを宣言するクラスだけです。BlazorCodeFirst の基底を継承しているだけのクラスには何も生成されません。間に挟まる抽象基底、基底が既にオーバーライドを宣言している末端のクラス、再抽象化したクラスは、いずれも対象外です。</p>\n<p>この診断がなければ、修飾子の欠落は抽象メンバー <code>RenderView</code> に対する CS0534 としてしか現れません。CS0534 が示すのは足りないメンバーで、修飾子ではありません。</p>\n<h3 id=\"bcf1002\">BCF1002<a href=\"#bcf1002\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 生成ファイルから見えないものを式が参照しているか、<code>[ViewPart]</code> メソッドが静的展開の契約を満たしていません。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt;\n    Div.Attr(<span class=\"string\">&quot;data-found&quot;</span>, _rows.TryGetValue(_key, <span class=\"keyword\">out</span> <span class=\"keyword\">var</span> row))\n       .Attr(<span class=\"string\">&quot;title&quot;</span>, row.Name);                               <span class=\"comment\">// BCF1002: row はそこに存在できない</span>\n</pre></div>\n<p>ジェネレーターは要素の各部を書かれた順に出力しないので、式のある部分で宣言したローカル変数は、別の部分の参照へ届きません。<code>return</code> の手前の文で宣言してください。</p>\n<p>宣言を運べる位置は2つあります。どちらも生成コードでは、それを読む側を包むヘッダーになるからです。\n<code>If</code> の条件は両方の分岐を包み、<code>ForEach</code> のソースはコンテンツとキーを包みます。</p>\n<p>BCF1003 との違いはここにあります。BCF1003 は、式を順序付けできなかったという意味です。BCF1002\nは、順序付けはできたものの、生成ファイルから見えないものを参照したという意味です。</p>\n<p><code>[ViewPart]</code> の本体にも、ゲッターについて <a href=\"#bcf1004\">BCF1004</a> が述べる予約名の規則が当てはまります。</p>\n<h3 id=\"bcf1003\">BCF1003<a href=\"#bcf1003\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 式はモデルの段階まで届きましたが、ジェネレーターが解析しない構文を使っているため翻訳できませんでした。</p>\n<div class=\"csharp\"><pre>\nDiv[_kids]                    <span class=\"comment\">// BCF1003: 子のリストを丸ごと渡している</span>\nDiv[<span class=\"keyword\">new</span> View[] { … }]         <span class=\"comment\">// BCF1003: 明示的な配列</span>\nDiv[[..items]]                <span class=\"comment\">// BCF1003: スプレッド</span>\n</pre></div>\n<p>繰り返しには <a href=\"/docs/ja/control-flow\"><code>ForEach</code></a> を使ってください。ジェネレーターが読むものは<a href=\"/docs/ja/elements-and-decorations\">要素と装飾</a>と<a href=\"/docs/ja/control-flow\">制御構文</a>に挙げてあります。要素ヘルパー、<code>Component&lt;T&gt;()</code>、<code>Fragment</code>、<code>Raw</code>、その場に書いた式のラムダ、そして <code>[ViewPart]</code>\nを付けたメソッドの呼び出しです。</p>\n<p>自分の <code>View</code> を返すメソッドに <code>[ViewPart]</code> を付ければ、そのマークアップを呼び出し側へ戻さずに分けたまま保てます。</p>\n<p><code>If</code> の分岐と、スプライスされた射影(<code>.. source.Select(item =&gt; …)</code>)は、BCF1004 のゲッターと同じように、本体を作者自身の名前のまま移植します。そのため <a href=\"#bcf1004\">BCF1004</a> が述べる予約名の規則が、ここにも届きます。</p>\n<h3 id=\"bcf1004\">BCF1004<a href=\"#bcf1004\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. ゲッターが、返り値の式1つに収まっていません。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div[H1[<span class=\"string\">&quot;Hello&quot;</span>]];              <span class=\"comment\">// これでよい</span>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body { <span class=\"keyword\">get</span> =&gt; Div[H1[<span class=\"string\">&quot;Hello&quot;</span>]]; }      <span class=\"comment\">// これでもよい</span>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body { <span class=\"keyword\">get</span> { <span class=\"keyword\">return</span> Div[H1[<span class=\"string\">&quot;Hello&quot;</span>]]; } }   <span class=\"comment\">// これでもよい</span>\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body { <span class=\"keyword\">get</span>; } = <span class=\"keyword\">default</span>;               <span class=\"comment\">// BCF1004</span>\n</pre></div>\n<p>その <code>return</code> の手前には、ローカル変数の宣言と式文を置けます。これらのステートメントは、生成される <code>RenderView</code> の中で、レンダーツリーのフレームを発行する呼び出しより前にそのまま出力されます。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body\n{\n    <span class=\"keyword\">get</span>\n    {\n        <span class=\"keyword\">var</span> greeting = $<span class=\"string\">&quot;Hello, {_name}&quot;</span>;\n        <span class=\"keyword\">return</span> Div[H1[greeting]];\n    }\n}\n</pre></div>\n<p>2つ目の <code>return</code> と C# 本来の制御構文は、それぞれ専用のシーケンス空間を必要とします。自動プロパティには、そもそもゲッターの本体がありません。<code>__builder</code> という名前のローカル、または <code>__bcf_</code>\nで始まるローカルも、ここには宣言できません。この2つの綴りは、移植したローカルが着地するどの位置でもジェネレーターが予約しています。名前を変えてください。本体がどうしてもこの形にならないなら、\n<code>RenderView</code> を手で書いてください。そのとき設計時の式は使われなくなり、何も報告されません。</p>\n<p>BCF1004 が報告するのは宣言そのものです。1つのクラスが <code>partial</code> の欠落とゲッターの問題を同時に持つことはあり、報告されるのは一度に1つです。<code>partial</code> の検査が先に実行されるので、まず BCF1001\nだけが出ます。</p>\n<h3 id=\"bcf1005\">BCF1005<a href=\"#bcf1005\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 入れ子のクラスが設計時の式を宣言しています。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Page\n{\n    <span class=\"keyword\">public</span> <span class=\"keyword\">partial</span> <span class=\"keyword\">class</span> Row : BodyComponentBase   <span class=\"comment\">// BCF1005</span>\n    {\n    }\n}\n</pre></div>\n<p>コンポーネントをトップレベルの型へ移してください。入れ子のクラスを生成ファイル側で開き直すには、外側の型の宣言を型引数まで含めて書き直す必要があり、ジェネレーターはそれを行いません。この診断がなければ、入れ子であることは CS0534 としてしか現れません。</p>\n<h2 id=\"この-api-が読まれる場所\">この API が読まれる場所<a href=\"#%E3%81%93%E3%81%AE-api-%E3%81%8C%E8%AA%AD%E3%81%BE%E3%82%8C%E3%82%8B%E5%A0%B4%E6%89%80\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf2001\">BCF2001<a href=\"#bcf2001\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Info. その呼び出しは静的に展開できないので、この領域は実行時のフラグメントを通して描画され、静的な差分の最適化を失います。</p>\n<p>ジェネレーターが展開するのは、読めるものだけです。設計時の API と、このコンパイルの中で宣言された <code>[ViewPart]</code> メソッドです。読めない呼び出しも誤りではなく、描画も正しく行われます。その領域のフレームが、静的なテンプレートと差分を取る代わりに、作り直されるというだけです。</p>\n<p>参照プロジェクトや NuGet パッケージの <code>[ViewPart]</code> がこれに該当します。定義は現コンパイルの構文から集められ、IL は本体の構文を持たないからです。アセンブリを越えた再利用はコンポーネントで行います。</p>\n<h3 id=\"bcf3029\">BCF3029<a href=\"#bcf3029\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 誰も読まない場所に設計時の構文が書かれているので、何も描画されず、ハンドラーも繋がりません。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">void</span> OnSomething()\n{\n    <span class=\"comment\">// BCF3029: 何も描画されず、DoThing も呼ばれない</span>\n    <span class=\"keyword\">var</span> card = Div.Class(<span class=\"string\">&quot;card&quot;</span>).OnClick(DoThing)[Span[<span class=\"string\">&quot;hello&quot;</span>]];\n}\n</pre></div>\n<p><code>Html.Div</code>、<code>.Class(...)</code>、<code>.OnClick(...)</code> をはじめ、要素のファクトリと装飾は、それ自体では何もしません。<code>View</code> は空の構造体で、要素ヘルパーは何も返さず、装飾はレシーバーをそのまま返すだけです。ジェネレーターが読むのは書かれた <em>構文</em> であって、値ではありません。読む場所も3つしかありません。コンポーネントの <code>Body</code>、レイアウトの <code>Chrome</code>、そして <code>[ViewPart]</code> メソッドの本体です。</p>\n<p>同じ API はどこからでも呼べますが、この3か所の外では誰も読みません。コンパイルは通りますが、レンダーツリーのフレームを1つも出さないので、何も描画されず、イベントハンドラーも登録されません。</p>\n<p>設計時型の値をフィールドやプロパティに取っておくのは報告しません。報告するのは、ローカル変数、破棄、引数の場合だけです。</p>\n<h3 id=\"bcf3030\">BCF3030<a href=\"#bcf3030\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 呼び出し先は設計時の API から <code>View</code> を組み立てているのに <code>[ViewPart]</code> を持たないので、この呼び出しは何も描画しません。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">static</span> View Card(<span class=\"keyword\">string</span> title) =&gt; Div.Class(<span class=\"string\">&quot;card&quot;</span>)[H2[title]];\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div[Card(<span class=\"string\">&quot;Hello&quot;</span>)];   <span class=\"comment\">// BCF3030</span>\n</pre></div>\n<p>そのメソッドが静的なら <code>[ViewPart]</code> を付けてください。そうでなければコンポーネントにします。属性がなければ、メソッドの結果はフラグメントを持たず、呼び出しはフレームを1つも出しません。</p>\n<p>これは BCF3029 を呼び出しの反対側から見たものです。BCF3029 は、誰も読まない場所に書かれた設計時の構文を報告します。こちらは、設計時の構文を書いたのに誰にも読まれなかったメソッドへの呼び出しを報告します。</p>\n<h3 id=\"bcf3001\">BCF3001<a href=\"#bcf3001\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 設計時の式の中で状態を書き換えています。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body\n{\n    <span class=\"keyword\">get</span>\n    {\n        _renderCount++;               <span class=\"comment\">// BCF3001</span>\n        <span class=\"keyword\">return</span> Div[Span[$<span class=\"string\">&quot;{_renderCount}&quot;</span>]];\n    }\n}\n</pre></div><div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">void</span> OnShown() =&gt; _renderCount++;                      <span class=\"comment\">// 代わりにこう書く</span>\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div[Span[$<span class=\"string\">&quot;{_renderCount}&quot;</span>]];\n</pre></div>\n<p>ゲッターは状態を UI へ映す射影であり、実行ではなく翻訳されます。書き換えはイベントハンドラーへ移してください。</p>\n<p><code>return</code> の手前の文も翻訳されるので、そこに書いた書き換えも BCF3001 です。</p>\n<h3 id=\"bcf3015\">BCF3015<a href=\"#bcf3015\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 設計時の値の式にある型名が解決できず、その名前は元ファイルの <code>using</code> や名前空間があって初めて解決する書き方です。</p>\n<p>値は <code>using</code> を一切持たない生成ファイルへ写されます。解決済みの型名は <code>global::</code> 修飾へ書き換えられますが、解決できない文脈依存の名前は安全に正規化できません。</p>\n<p>名前を直すか、完全修飾するか、ソース生成された型を参照プロジェクトへ移すか、手書きの C# の型に置き換えてください。既に <code>global::</code> から始まっている参照はそのまま残し、通常の C# の解決に任せます。ジェネリックの型引数は、それぞれ独立に検査します。</p>\n<h2 id=\"要素\">要素<a href=\"#%E8%A6%81%E7%B4%A0\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3009\">BCF3009<a href=\"#bcf3009\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. <code>Element</code> のタグが、タグ名の形をしたコンパイル時定数ではありません。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">private</span> <span class=\"keyword\">const</span> <span class=\"keyword\">string</span> Widget = <span class=\"string\">&quot;my-widget&quot;</span>;\n\nElement(Widget)                  <span class=\"comment\">// これでよい</span>\nElement(_kind + <span class=\"string\">&quot;-widget&quot;</span>)       <span class=\"comment\">// BCF3009: 定数ではない</span>\nElement(<span class=\"string\">&quot;&quot;</span>)                      <span class=\"comment\">// BCF3009: 空</span>\nElement(<span class=\"string\">&quot;my widget&quot;</span>)             <span class=\"comment\">// BCF3009: タグ名の形ではない</span>\n</pre></div>\n<p>タグ名とは、ASCII の英字で始まり、以降は ASCII の英数字と <code>-</code>、<code>_</code>、<code>.</code> が続くものです。</p>\n<p>定数であることを求めるのは、要素を宣言的に保つためです。計算されたタグは注入の危険でも順序付けの問題でもありませんが、書いた場所で要素のタグ名が読み取れなくなります。</p>\n<p>タグ名の形を求める理由は違います。ここが破れると、翻訳そのものが壊れます。どの要素にも使えないタグは、二通りに描かれます。プリレンダリングはマークアップに書き、HTML パーサーがそれを解釈し直します。対話的レンダリングは <code>createElement</code> に渡し、それが拒んでサーキットが終了します。</p>\n<h3 id=\"bcf3016\">BCF3016<a href=\"#bcf3016\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 空要素に子を書いています。</p>\n<div class=\"csharp\"><pre>\nImg.Src(<span class=\"string\">&quot;/logo.png&quot;</span>)[<span class=\"string\">&quot;Logo&quot;</span>]     <span class=\"comment\">// BCF3016</span>\nElement(<span class=\"string\">&quot;img&quot;</span>)[<span class=\"string\">&quot;Logo&quot;</span>]           <span class=\"comment\">// BCF3016、同じ規則</span>\nImg.Src(<span class=\"string\">&quot;/logo.png&quot;</span>).Alt(<span class=\"string\">&quot;Logo&quot;</span>) <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>空要素は13個あります。<code>area</code>、<code>base</code>、<code>br</code>、<code>col</code>、<code>embed</code>、<code>hr</code>、<code>img</code>、<code>input</code>、<code>link</code>、<code>meta</code>、\n<code>source</code>、<code>track</code>、<code>wbr</code> です。</p>\n<p>子は HTML を往復すると失われます。プリレンダリングはパーサーが受け付けない終了タグを書き出し、パーサーは子を要素の外へ移して兄弟にします。孤立した <code>&lt;/br&gt;</code> は開始タグとして読み直されるので、\n<code>Br[&quot;x&quot;]</code> は <code>&lt;br&gt;</code> 2つになります。</p>\n<p>対話的レンダリングにはパーサーが挟まらず、同じ子を要素の中に置きます。1つの式から2つの DOM ができ、ハイドレーションでページの形が変わります。</p>\n<p>空要素は装飾で設定し、内容はその隣に置いてください。</p>\n<p>ヘルパーと、空要素のタグを渡した <code>Element</code> の両方を検査します。カスタム要素と未知のタグは検査しません。内容モデルを読み取れる標準がないからです。</p>\n<p>この API が HTML について検査するのは、ここまでです。この線引きは意図したものです。BCF3016 は要素のタグだけから決定できます。ある子がある親の中に置けるかは決定できないので、\n<code>Table[Div[&quot;x&quot;]]</code> も、要素が定義しない属性（<code>Div.Href(&quot;/x&quot;)</code>）も受け付けます。</p>\n<h3 id=\"bcf3027\">BCF3027<a href=\"#bcf3027\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 要素ヘルパーが使うはずの単純名を、自分の宣言が奪っています。</p>\n<div class=\"csharp\"><pre>\n[Parameter] <span class=\"keyword\">public</span> <span class=\"keyword\">string</span> Data { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }\nDiv[Data[<span class=\"string\">&quot;Heading&quot;</span>]]                          <span class=\"comment\">// BCF3027、メンバー</span>\n\n<span class=\"keyword\">public</span> <span class=\"keyword\">sealed</span> <span class=\"keyword\">class</span> Table;                    <span class=\"comment\">// Table[&quot;x&quot;]   — BCF3027、型</span>\n<span class=\"keyword\">namespace</span> MyApp.Article { }                   <span class=\"comment\">// Article[&quot;x&quot;] — BCF3027、名前空間</span>\n<span class=\"keyword\">private</span> <span class=\"keyword\">string</span> Summary() =&gt; <span class=\"string\">&quot;&quot;</span>;               <span class=\"comment\">// Summary[&quot;x&quot;] — BCF3027、メソッド</span>\n\nDiv[Html.Data[<span class=\"string\">&quot;Heading&quot;</span>]]                     <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p><code>using static BlazorCodeFirst.Html;</code> は準拠する要素名をすべて取り込みますが、自分の宣言のほうが単純名の解決に勝ちます。<code>Label</code>、<code>Data</code>、<code>Summary</code>、<code>Source</code> という Blazor のパラメーター名はありふれているので、この衝突は実際に起きます。</p>\n<p>C# にはそれぞれ専用のエラーがあります。添字の引数に対する CS1503、CS0119、CS0118、CS0021 です。そのどれも報告されません。本体が翻訳されない限りコンポーネントには生成された <code>RenderView</code> がなく、コンパイラはメソッド本体を解決する前に止まります。4つのエラーは、どれもその解決の段階ではじめて見つかるものです。</p>\n<h2 id=\"装飾\">装飾<a href=\"#%E8%A3%85%E9%A3%BE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3008\">BCF3008<a href=\"#bcf3008\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 要素を開かないものに装飾を付けています。</p>\n<div class=\"csharp\"><pre>\nIf(_open, () =&gt; Div[<span class=\"string\">&quot;x&quot;</span>]).Class(<span class=\"string\">&quot;card&quot;</span>)   <span class=\"comment\">// BCF3008</span>\nDiv[<span class=\"string\">&quot;text&quot;</span>].Class(<span class=\"string\">&quot;card&quot;</span>)                 <span class=\"comment\">// BCF3008: 角括弧が既に View を作っている</span>\nDiv.Class(<span class=\"string\">&quot;card&quot;</span>)[<span class=\"string\">&quot;text&quot;</span>]                 <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>装飾は所有する要素の属性へ畳まれるので、付く先の要素が必要です。<code>If</code>、<code>ForEach</code>、<code>Fragment</code>、\n<code>Raw</code>、<code>[ViewPart]</code> やコンポーネントの結果は、どれも要素を開きません。</p>\n<h3 id=\"bcf3026\">BCF3026<a href=\"#bcf3026\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 装飾の位置に書かれた名前を、このライブラリは宣言していません。</p>\n<div class=\"csharp\"><pre>\nDiv.Clas(<span class=\"string\">&quot;card&quot;</span>)     <span class=\"comment\">// BCF3026</span>\nDiv.Class(<span class=\"string\">&quot;card&quot;</span>)    <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>綴り間違いも、要素を取って要素を返す自作の拡張メソッドも、これに該当します。綴り間違いには C# のエラーがありますが、同じ宣言段階の停止によって報告されません。</p>\n<h3 id=\"bcf3010\">BCF3010<a href=\"#bcf3010\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 1つの要素で、同じ属性またはイベントを2回以上バインドしています。</p>\n<div class=\"csharp\"><pre>\nInput.Type(<span class=\"string\">&quot;text&quot;</span>).Attr(<span class=\"string\">&quot;value&quot;</span>, _a).Attr(<span class=\"string\">&quot;value&quot;</span>, _b)   <span class=\"comment\">// BCF3010</span>\nInput.Type(<span class=\"string\">&quot;text&quot;</span>).Attr(<span class=\"string\">&quot;value&quot;</span>, _b)                     <span class=\"comment\">// 代わりにこう書く</span>\nDiv.Class(<span class=\"string\">&quot;card&quot;</span>).Class(<span class=\"string\">&quot;is-open&quot;</span>)                       <span class=\"comment\">// これでよい: class は畳まれる</span>\n</pre></div>\n<p>属性チャネルで2回バインドすると、後の書き込みが勝ち、先のものは捨てられます。1つの名前を属性チャネルとイベントチャネルで1回ずつバインドすると、両方が残ります。インラインのハンドラーと C# のハンドラーが、イベントごとに両方実行されます。どちらも書いたとおりではありません。</p>\n<p>例外は <code>class</code> だけです。<code>.Class</code> と <code>.Attr(&quot;class&quot;, …)</code> は空白で連結された1つの属性へ畳まれます。\n<code>style</code> は例外ではないので、1つの要素に2つ書けば BCF3010 です。</p>\n<h3 id=\"bcf3011\">BCF3011<a href=\"#bcf3011\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. <code>.Attr</code> の名前または <code>.On</code> のイベント名が、空でないコンパイル時定数の文字列ではありません。</p>\n<div class=\"csharp\"><pre>\nDiv.Attr(_name, <span class=\"string\">&quot;x&quot;</span>)          <span class=\"comment\">// BCF3011</span>\nDiv.Attr(<span class=\"string\">&quot;data-kind&quot;</span>, <span class=\"string\">&quot;x&quot;</span>)    <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>名前はリテラルとして出力されます。定数であることは、class の畳み込みと二重バインドの検出の前提でもあります。</p>\n<h3 id=\"bcf3023\">BCF3023<a href=\"#bcf3023\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. <code>class</code> に書いた装飾が、class チャネルがテキストとして連結できない値を持っています。</p>\n<div class=\"csharp\"><pre>\nDiv.Attr(<span class=\"string\">&quot;class&quot;</span>, _selected)                     <span class=\"comment\">// BCF3023</span>\nDiv.Attr(<span class=\"string\">&quot;class&quot;</span>)                                <span class=\"comment\">// BCF3023: 存在の表明にテキストはない</span>\nDiv.Class(_selected ? <span class=\"string\">&quot;is-selected&quot;</span> : <span class=\"keyword\">null</span>)      <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>class チャネルは、書かれた装飾を1つの値へテキストとして連結します。そのため <code>class</code> が取るのは文字列だけです。<code>.Attr</code> の <code>bool</code> オーバーロードは Blazor の条件付き属性の形で、引数なしの\n<code>.Attr(name)</code> は存在の表明です。どちらもテキストではありません。</p>\n<p>さもなければ、値は二通りに翻訳されます。class の装飾が1つだけならチャネルは値をそのまま出すので、\n<code>true</code> は <code>class=&quot;&quot;</code> になり class の一覧を空にします。2つ以上ならチャネルは <code>+</code> で連結するので、同じ <code>true</code> が <code>class=&quot;a True&quot;</code> になります。同じ書き方が、チェーンの別の場所に書かれた個数によって二通りの意味を持つ、というのが問題です。</p>\n<h3 id=\"bcf3024\">BCF3024<a href=\"#bcf3024\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 1つの要素が、class チャネルの装飾と <code>class</code> への <code>.Bind</code> の両方を持っています。</p>\n<div class=\"csharp\"><pre>\nDiv.Class(<span class=\"string\">&quot;card&quot;</span>).Bind(<span class=\"string\">&quot;class&quot;</span>, <span class=\"string\">&quot;onchange&quot;</span>, () =&gt; _classes)   <span class=\"comment\">// BCF3024</span>\n</pre></div>\n<p><code>.Class</code> と <code>.Attr(&quot;class&quot;, …)</code> は1つの属性へ畳まれます。同じ名前への <code>.Bind</code> はその畳み込みに加わらず、自分のフレームを出すので、要素は <code>class</code> を2つ持って出力されます。</p>\n<p>どちらが残るかは一通りに決まりません。プリレンダリングされたマークアップは HTML パーサーが解決して先勝ちになり、対話的レンダリングは DOM へ適用するので後勝ちになります。</p>\n<p>class の値は1か所から与えてください。バインドのゲッターにすべてを持たせるか、バインドをやめて装飾だけにします。</p>\n<h3 id=\"bcf3033\">BCF3033<a href=\"#bcf3033\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 属性ではない同じ装飾を、1つのノードに2回書いています。</p>\n<div class=\"csharp\"><pre>\nDiv.Key(row.Id).Key(row.Slug)[<span class=\"string\">&quot;x&quot;</span>]   <span class=\"comment\">// BCF3033</span>\nDiv.Key(row.Id)[<span class=\"string\">&quot;x&quot;</span>]                 <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p><code>.Key</code> と同種の装飾は、値を1つだけ持つチャネルを占めます。3つとも壊れ方が違い、どれも目に見える形では壊れません。</p>\n<ul>\n<li><code>SetKey</code> は開いているフレームへ書き込むので、2回目が1回目を上書きします。</li>\n<li><code>AddComponentRenderMode</code> は追記され、レンダラーは最初に見つけたフレームを読むので、そこでは\n2つ目が無視されます。</li>\n<li>参照の捕捉も追記され、両方の動作が実行されます。</li>\n</ul>\n<p>装飾は1回だけ書き、そのノードが持つべき値を渡してください。候補が2つあるということは、同一性がまだ決まっていないということです。決められる場所はソースだけです。</p>\n<h3 id=\"bcf3034\">BCF3034<a href=\"#bcf3034\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. コンポーネント自身の宣言がレンダーモードを固定しているので、呼び出し側からは設定できません。</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Counter&gt;().RenderMode(RenderMode.InteractiveWebAssembly)   <span class=\"comment\">// Counter が宣言していれば BCF3034</span>\n</pre></div>\n<p>フレームワークはこの組み合わせを拒みます。<code>RenderModeAttribute</code> を持つ型が呼び出し側からもモードを受け取ると、<code>ComponentFactory</code> が例外を投げます。呼び出し側で指定する形は、自分ではモードを宣言しないコンポーネントのためにあります。同じコンポーネントを、あるページからは対話的に、別のページからは静的に描く場合です。</p>\n<p>呼び出し側の <code>.RenderMode</code> を外し、コンポーネント自身の属性に任せてください。呼び出し側ごとにモードを変える必要が本当にあるなら、コンポーネントから属性を外します。その場合は、すべての呼び出し側がモードを書くことになります。</p>\n<h2 id=\"イベント\">イベント<a href=\"#%E3%82%A4%E3%83%99%E3%83%B3%E3%83%88\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3019\">BCF3019<a href=\"#bcf3019\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. イベント名が <code>on</code> で始まっていません。</p>\n<div class=\"csharp\"><pre>\nInput.On(<span class=\"string\">&quot;input&quot;</span>, (ChangeEventArgs e) =&gt; …)     <span class=\"comment\">// BCF3019</span>\nInput.On(<span class=\"string\">&quot;oninput&quot;</span>, (ChangeEventArgs e) =&gt; …)   <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>Blazor のイベント属性名は必ず <code>on</code> で始まり、接頭辞が補われることはありません。<code>on</code> のない名前は通常の属性として <code>AddAttribute</code> に届くので、ハンドラーは呼ばれず、実行時にも何も報告されません。</p>\n<p><code>.Bind</code> では、この検査がもう1つの役割を持ちます。属性名とイベント名は隣り合う文字列引数で、入れ替えてもコンパイルは通ります。入れ替えを止めるのがこの検査です。</p>\n<h3 id=\"bcf3028\">BCF3028<a href=\"#bcf3028\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. ハンドラーの引数型が、指定したイベントの渡す型ではありません。</p>\n<div class=\"csharp\"><pre>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (MouseEventArgs e) =&gt; Zoom(e.ClientX, e.ClientY))[<span class=\"string\">&quot;Zoom&quot;</span>]   <span class=\"comment\">// 渡される型</span>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (EventArgs e) =&gt; Save())[<span class=\"string\">&quot;Save&quot;</span>]                            <span class=\"comment\">// その基底: これでよい</span>\nButton.On(<span class=\"string\">&quot;onclick&quot;</span>, (KeyboardEventArgs e) =&gt; Save())[<span class=\"string\">&quot;Save&quot;</span>]                    <span class=\"comment\">// BCF3028</span>\n</pre></div>\n<p>Blazor はイベントの引数オブジェクトをハンドラーの引数型へキャストして渡すので、渡される型の基底は受け取れて、兄弟の型は受け取れません。<code>EventArgs</code> ですらない型も同じ診断です。</p>\n<p>対応表はフレームワークが提供する <code>[EventHandler]</code> のメタデータと、ビルド中のコンパイルにある登録から読みます。登録のないイベントには対応表がないので検査しません。</p>\n<div class=\"csharp\"><pre>\n[EventHandler(<span class=\"string\">&quot;onrate&quot;</span>, <span class=\"keyword\">typeof</span>(RatingEventArgs))]\n<span class=\"keyword\">public</span> <span class=\"keyword\">static</span> <span class=\"keyword\">class</span> AppEventHandlers;\n</pre></div><h3 id=\"bcf3035\">BCF3035<a href=\"#bcf3035\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. イベント修飾子の手前に、その要素のイベントがありません。</p>\n<div class=\"csharp\"><pre>\nForm.PreventDefault().On(<span class=\"string\">&quot;onsubmit&quot;</span>, () =&gt; Save())   <span class=\"comment\">// BCF3035</span>\nForm.On(<span class=\"string\">&quot;onsubmit&quot;</span>, () =&gt; Save()).PreventDefault()   <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p><code>.PreventDefault</code> と <code>.StopPropagation</code> は、手前に書いたイベントへ付きます。チェーンが示す読み方はそれだけです。装飾自身はイベント名を持ちません。</p>\n<h3 id=\"bcf3036\">BCF3036<a href=\"#bcf3036\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 1つのイベントに、同じイベント修飾子を2回書いています。</p>\n<div class=\"csharp\"><pre>\nForm.On(<span class=\"string\">&quot;onsubmit&quot;</span>, () =&gt; Save()).PreventDefault().PreventDefault()   <span class=\"comment\">// BCF3036</span>\nForm.On(<span class=\"string\">&quot;onsubmit&quot;</span>, () =&gt; Save()).PreventDefault()                    <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>2つのうち一方は、モデルがどちらを採っても何も変えません。どちらが無駄になるかは、呼び出し側からは分かりません。</p>\n<p>修飾子は1回だけ書いてください。値ではなくフラグなので、2つ目には1つ目に足すものがありません。</p>\n<h3 id=\"bcf3038\">BCF3038<a href=\"#bcf3038\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. そのイベント自身の <code>[EventHandler]</code> 登録が、その修飾子を無効にしています。</p>\n<p>Blazor は修飾子をイベントごとに制御し、登録が無効にした属性をレンダラーは無視します。修飾子を外してください。イベント自体は正しく、そのまま残ります。</p>\n<h2 id=\"制御構文\">制御構文<a href=\"#%E5%88%B6%E5%BE%A1%E6%A7%8B%E6%96%87\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3002\">BCF3002<a href=\"#bcf3002\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Warning. <code>ForEach</code> のキーセレクターが自分の要素に触れていないので、要素を見分けられません。</p>\n<div class=\"csharp\"><pre>\nForEach(rows, key: r =&gt; <span class=\"number\">0</span>, content: r =&gt; Li[r.Name])          <span class=\"comment\">// BCF3002</span>\nForEach(rows, key: r =&gt; r.Id, content: r =&gt; Li[r.Name])       <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>要素から作られたキーがあってはじめて、Blazor は挿入・削除・並び替えを越えて行ごとの状態を保てます。定数、外側のインデックス、別のリストの要素は、全体の再描画を招きます。</p>\n<p>検査はあえて控えめです。要素から作ってはいるものの実際には位置に近い、というキーは検出しません。</p>\n<h3 id=\"bcf3003\">BCF3003<a href=\"#bcf3003\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. <code>ForEach</code> の内容のルートは、単一の要素かコンポーネントである必要があります。そうでないと、キーの付く先がありません。</p>\n<div class=\"csharp\"><pre>\nForEach(rows, key: r =&gt; r.Id, content: r =&gt; If(r.Visible, () =&gt; Li[r.Name]))   <span class=\"comment\">// BCF3003</span>\nForEach(rows, key: r =&gt; r.Id, content: r =&gt; Li[If(r.Visible, () =&gt; Span[r.Name])])   <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>キーは内容のルートのフレームに付き、<code>SetKey</code> は現在開いている要素かコンポーネントのフレームに付きます。単独の <code>If</code>、入れ子の <code>ForEach</code>、テキストだけ、<code>Fragment</code>、<code>Raw</code>、外から渡された\n<code>RenderFragment</code> は、いずれもキーの付く単一のフレームを開きません。</p>\n<p>内容を要素で包んでください。<code>key: null</code> でキーを使わない <code>ForEach</code> は <code>SetKey</code> を出さないので、それらのルートも置けます。</p>\n<h3 id=\"bcf3004\">BCF3004<a href=\"#bcf3004\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. <code>ForEach</code> のキーか内容が、ジェネレーターの順序付けできない形です。</p>\n<p>キーの本体は <code>SetKey</code> の呼び出しへそのまま写されるので、式である必要があります。内容には静的なシーケンス空間が1つ与えられ、それを毎回の繰り返しが使い回します。2つ目の <code>return</code> や C# 本来の制御文は、それぞれ自分用の複製を必要とします。</p>\n<p>内容が受け付けるのは、式のラムダ、末尾に <code>return</code> を1つ持つブロック、引数1つの <code>View</code> を返すメソッドグループです。</p>\n<p>キーの本体と内容の本体にも、ゲッターについて <a href=\"#bcf1004\">BCF1004</a> が述べる予約名の規則が当てはまります。</p>\n<h3 id=\"bcf3032\">BCF3032<a href=\"#bcf3032\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. <code>ForEach</code> がキーを付ける内容のルートが、自分でも <code>.Key</code> を書いています。</p>\n<div class=\"csharp\"><pre>\nForEach(rows, key: r =&gt; r.Id, content: r =&gt; Li.Key(r.Id)[r.Name])   <span class=\"comment\">// BCF3032</span>\n</pre></div>\n<p>1つのフレームに <code>SetKey</code> が2回届き、後のほうが勝ちます。そのためどちらのキーが有効かは、呼び出しサイトではなくフレームの発行順で決まります。ルートに付けるか、ループに付けるか、どちらかにしてください。</p>\n<h2 id=\"コンポーネント\">コンポーネント<a href=\"#%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3005\">BCF3005<a href=\"#bcf3005\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. パラメーターのセレクターが、自分のラムダ引数に対する素直なプロパティ選択ではありません。</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Card&gt;().Param(c =&gt; (<span class=\"keyword\">string</span>)c.Label, <span class=\"string\">&quot;x&quot;</span>)   <span class=\"comment\">// BCF3005</span>\nComponent&lt;Card&gt;().Param(c =&gt; c.Label, <span class=\"string\">&quot;x&quot;</span>)           <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>ジェネレーターはセレクターに書かれた名前をそのまま読むので、キャスト、メソッド呼び出し、\nnull 条件アクセス、捕捉した変数のメンバーには読む名前がありません。<code>.Param</code>、<code>.Template</code>、\n<code>.Bind</code> はどれも同じセレクターを取ります。</p>\n<h3 id=\"bcf3006\">BCF3006<a href=\"#bcf3006\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 選んだプロパティが、設定できる <code>[Parameter]</code> ではありません。</p>\n<div class=\"csharp\"><pre>\n<span class=\"keyword\">public</span> <span class=\"keyword\">string</span> Label { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }              <span class=\"comment\">// BCF3006: [Parameter] が無い</span>\n[Parameter] <span class=\"keyword\">public</span> <span class=\"keyword\">string</span> Label { <span class=\"keyword\">get</span>; }       <span class=\"comment\">// BCF3006: セッターが無い</span>\n\n[Parameter] <span class=\"keyword\">public</span> <span class=\"keyword\">string</span> Label { <span class=\"keyword\">get</span>; <span class=\"keyword\">set</span>; }  <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>バインドできるのは、<code>[Parameter]</code> が付いていてアクセス可能なセッターを持つプロパティだけです。それ以外を設定すると、Blazor がパラメーターを適用する時点で例外がスローされます。</p>\n<p>プロパティに <code>[Parameter]</code> を付け、アクセス可能なセッターを与えてください。呼び出し側から受け取らない値は、パラメーターではなくフィールドに置きます。</p>\n<h3 id=\"bcf3007\">BCF3007<a href=\"#bcf3007\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 1つのチェーンが、同じパラメーターを2回以上バインドしています。</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Card&gt;().Param(c =&gt; c.Label, <span class=\"string\">&quot;a&quot;</span>).Param(c =&gt; c.Label, <span class=\"string\">&quot;b&quot;</span>)   <span class=\"comment\">// BCF3007</span>\nComponent&lt;Card&gt;().Param(c =&gt; c.Label, <span class=\"string\">&quot;b&quot;</span>)                            <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>数えるのはすべてのチャネルです。<code>.Param</code>、<code>.Template</code>、<code>.Bind</code>、そして角括弧に書いた子の内容。\nBlazor は最後の書き込みを適用するので、先の値は捨てられます。</p>\n<p>パラメーターは1回だけバインドし、コンポーネントに届いてほしい値を渡してください。状態で変わる値は、渡す式の中で決めます。2つ目の <code>.Param</code> で決めるものではありません。</p>\n<h3 id=\"bcf3012\">BCF3012<a href=\"#bcf3012\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. ジェネレーターの実行時点で型引数が解決できませんでした。</p>\n<p>よくある原因は、同じプロジェクトで宣言された <code>.razor</code> コンポーネントです。Razor コンパイラ自身がソースジェネレーターであり、ソースジェネレーターは互いの出力を観測できません。そのため最終的なコンパイルに存在していても、ここでは解決できません。</p>\n<p>参照プロジェクトへ移すか、手書きの C# コンポーネントにするか、名前を直してください。参照プロジェクトや NuGet パッケージの同じコンポーネントは通常どおり解決します。</p>\n<p>綴り間違い、アクセスできない型、あいまいな名前、<code>using</code> の不足もこれに該当します。その場合は同じ位置に C# の解決エラーも出ます。</p>\n<h3 id=\"bcf3013\">BCF3013<a href=\"#bcf3013\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 子の内容を受け取れないコンポーネントに、角括弧で内容を書いています。</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Panel&gt;()[<span class=\"string\">&quot;body&quot;</span>]                                  <span class=\"comment\">// Panel に ChildContent がなければ BCF3013</span>\nComponent&lt;Panel&gt;().Param(c =&gt; c.Content, Span[<span class=\"string\">&quot;body&quot;</span>])      <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>角括弧は <code>ChildContent</code> という名前のパラメーターにバインドされます。Razor が入れ子の内容を割り当てる先と同じです。そのパラメーターは、設定できる <code>[Parameter]</code> である必要があります。型は\n<code>RenderFragment</code> か <code>RenderFragment&lt;TContext&gt;</code> に限ります。ジェネリックのほうは、コンテキストを捨てて子を受け取ります。</p>\n<h3 id=\"bcf3014\">BCF3014<a href=\"#bcf3014\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 実体のない設計時の値を、ジェネリックの <code>Param</code> に渡しています。</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Card&gt;().Param(c =&gt; c.Body, Div[<span class=\"string\">&quot;x&quot;</span>])              <span class=\"comment\">// BCF3014</span>\nComponent&lt;Card&gt;().Param(c =&gt; c.Body, () =&gt; Div[<span class=\"string\">&quot;x&quot;</span>])        <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p><code>View</code> と <code>ComponentView&lt;T&gt;</code> は、ジェネレーターが読む空の目印であって、実行時の値ではありません。ジェネリックの <code>Param</code> は値の式をそのまま出すので、これをバインドすると目印が代入されます。<code>object</code>\n型のパラメーターは例外を出さずに受け取って誤った出力を描き、型の付いたパラメーターは Blazor がパラメーターを適用するときに無効なキャストを投げます。</p>\n<h3 id=\"bcf3022\">BCF3022<a href=\"#bcf3022\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. コンテキストを取る <code>.Template</code> の内容が、その場に書いた式のラムダではありません。</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Grid&lt;Row&gt;&gt;().Template(c =&gt; c.RowTemplate, RenderRow)          <span class=\"comment\">// BCF3022</span>\nComponent&lt;Grid&lt;Row&gt;&gt;().Template(c =&gt; c.RowTemplate, row =&gt; Td[row.Name]) <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>メソッドグループ、匿名メソッド、本体が文のラムダは、いずれも内容を呼び出しの内側に隠します。順序付ける式も、生成したコンテキスト変数を差し替える引数のシンボルも残りません。</p>\n<p>内容にも、ゲッターについて <a href=\"#bcf1004\">BCF1004</a> が述べる予約名の規則が当てはまります。</p>\n<h3 id=\"bcf3025\">BCF3025<a href=\"#bcf3025\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. 内容を取る <code>[ViewPart]</code> の本体の外に <code>Slot</code> があるか、ちょうど1回以外の回数で書かれています。</p>\n<div class=\"csharp\"><pre>\n[ViewPart]\n<span class=\"keyword\">public</span> <span class=\"keyword\">static</span> SlotView Panel(View heading) =&gt;\n    Section[heading, Div.Class(<span class=\"string\">&quot;body&quot;</span>)[Slot]];   <span class=\"comment\">// これでよい</span>\n\n<span class=\"keyword\">protected</span> <span class=\"keyword\">override</span> View Body =&gt; Div[Slot];       <span class=\"comment\">// BCF3025: Body は角括弧を受け取らない</span>\n</pre></div>\n<p><code>Slot</code> は、呼び出し側が角括弧で渡した内容をパーツが置く位置を示します。そのため置く内容がない場所では意味を持ちません。コンポーネントの <code>Body</code> や <code>Chrome</code> は角括弧を受け取らず、<code>View</code> を返すパーツは角括弧なしで呼ばれます。</p>\n<p>内容を取るパーツは、返り値の型に <code>SlotView</code> を宣言し、<code>Slot</code> をちょうど1回書きます。2回書けば呼び出し側の内容が2回出力され、1回も書かなければ、渡すことを義務づけた内容を捨てることになります。</p>\n<h2 id=\"双方向バインディング\">双方向バインディング<a href=\"#%E5%8F%8C%E6%96%B9%E5%90%91%E3%83%90%E3%82%A4%E3%83%B3%E3%83%87%E3%82%A3%E3%83%B3%E3%82%B0\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<h3 id=\"bcf3017\">BCF3017<a href=\"#bcf3017\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. <code>.Bind</code> のゲッターが、その場に書いた式本体のラムダではありません。</p>\n<div class=\"csharp\"><pre>\nInput.Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, GetName)          <span class=\"comment\">// BCF3017</span>\nInput.Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _name)      <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>ゲッターの本体は2か所へ写されます。バインドされる属性の値として1回、バインダーの現在値として1回です。そのため式として取り出せる必要があります。本体が文のラムダとメソッドグループは、どちらもそれを呼び出しの内側に隠します。</p>\n<p>セッターの引数にこの制限はありません。<code>EventCallback</code> へ丸ごと渡され、分解されないからです。</p>\n<h3 id=\"bcf3018\">BCF3018<a href=\"#bcf3018\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. ゲッターのみの <code>.Bind</code> で、ゲッターの本体に代入できないため、セッターを導けません。</p>\n<div class=\"csharp\"><pre>\nInput.Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; Name.Trim())                          <span class=\"comment\">// BCF3018</span>\nInput.Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; Name, v =&gt; Name = v.Trim())           <span class=\"comment\">// 代わりにこう書く</span>\n</pre></div>\n<p>ゲッターのみの形は、ゲッターの本体を代入の左辺に置いてセッターを導きます。そのためその本体は、フィールド、設定できるプロパティ、セッターを持つインデクサーへの要素アクセスのいずれかである必要があります。</p>\n<p>セッターがあることと、導いた代入がそれを呼べることは別の問いです。導いたセッターはラムダなので、\n<code>init</code> アクセサには届きません。C# が <code>init</code> への代入を許すのは、オブジェクト初期化子、コンストラクター、別の <code>init</code> アクセサの中だけです。プロパティ自身より狭く宣言したセッターにも届きません。こちらは代入がどこへ出力されるかで決まります。コンポーネント自身が宣言した\n<code>{ get; private set; }</code> は受け付けます。生成される <code>RenderView</code> が同じクラスの partial へ出力されるからです。別の型が宣言した同じ形は拒否します。</p>\n<p>ローカル変数、引数、<code>ForEach</code> の反復変数は、C# なら代入できても拒否します。設計時の式はプロパティのゲッターなので、それらは描画ごとに消え、書き戻しは次の描画まで残らないからです。反復変数のメンバーは受け付けます。元のリストの要素へ書き通るからです。</p>\n<h3 id=\"bcf3020\">BCF3020<a href=\"#bcf3020\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. コンポーネントに対応する変更コールバックがないので、双方向バインディングに書き戻す先がありません。</p>\n<div class=\"csharp\"><pre>\nComponent&lt;Field&gt;().Bind(c =&gt; c.Value, () =&gt; _query)   <span class=\"comment\">// ValueChanged がなければ BCF3020</span>\nComponent&lt;Field&gt;().Param(c =&gt; c.Value, _query)        <span class=\"comment\">// 代わりに片方向でこう書く</span>\n</pre></div>\n<p>コンポーネントのバインドは、パラメーター名を書かせるのではなく導きます。要素側とは逆です。それが成り立つのは、導出を検査できるからです。コンポーネントの型は分かっているので、ジェネレーターは導いた <code>{名前}Changed</code> を引き、無いか型が違えばこれを報告します。</p>\n<p>要素のバインドにはこの検査がありません。そのため名前を2つとも書かせます。</p>\n<h3 id=\"bcf3031\">BCF3031<a href=\"#bcf3031\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h3>\n<p>Error. <code>.Bind</code> が、フレームワークが書式を取る変換器を宣言していない型に書式を書いています。</p>\n<div class=\"csharp\"><pre>\nInput.Bind(<span class=\"string\">&quot;value&quot;</span>, <span class=\"string\">&quot;oninput&quot;</span>, () =&gt; _count, format: <span class=\"string\">&quot;N0&quot;</span>)   <span class=\"comment\">// BCF3031</span>\n</pre></div>\n<p>書式を取るオーバーロードを宣言しているのは、<code>BindConverter.FormatValue</code> と <code>CreateBinder</code> の\n2つです。対象の型は <code>DateTime</code>、<code>DateTimeOffset</code>、<code>DateOnly</code>、<code>TimeOnly</code> と、それらの null 許容形だけです。それ以外に書式を書くと、どのオーバーロードにも解決しない呼び出しが生成ファイルに残ります。その C# のエラーは、自分で書いたソースではなく生成コードの中で起きます。</p>\n<p>書式を外すか、ゲッターで整形してセッターで解析してください。受け付ける集合はフレームワーク自身のメタデータから読んでおり、このコンパイラが列挙しているのではありません。カルチャーは問題になりません。この API がバインドするどの型も、カルチャーを持てます。</p>\n<h2 id=\"次に読むもの\">次に読むもの<a href=\"#%E6%AC%A1%E3%81%AB%E8%AA%AD%E3%82%80%E3%82%82%E3%81%AE\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><a href=\"/docs/ja/getting-started\">はじめに</a>へ戻る、あるいは<a href=\"/docs/ja/elements-and-decorations\">要素と装飾</a>で書ける要素の一覧を読む。</p>\n"),
        new DocEntry(
            "faq",
            "FAQ",
            "VStack や型付きパディングがないのはなぜかなど、この API の形が生む疑問と、その答えがどこで決まっているか。",
            110,
            "reference",
            "ja",
            false,
            ["vstack-や-padding-や-text-が無いのはなぜですか", "razor-ファイルを残せますか", "mudblazor-や-radzen-などのコンポーネントライブラリと一緒に使えますか", "実行時のコストはどれくらいですか", "クラスが-partial-かつトップレベルでなければならないのはなぜですか", "body-の中で通常の-if-や-foreach-を書けないのはなぜですか", "foreach-がキーを要求するのはなぜですか", "raw-は安全ですか", "ビルドが止まったが-id-に見覚えがない", "書いたものと違う描画になったらどこを見ますか"],
            "<p>この API の形から生じる疑問と、その答えがどこで決まっているかです。</p>\n<h2 id=\"vstack-や-padding-や-text-が無いのはなぜですか\"><code>VStack</code> や <code>.Padding()</code> や <code>Text()</code> が無いのはなぜですか<a href=\"#vstack-%E3%82%84-padding-%E3%82%84-text-%E3%81%8C%E7%84%A1%E3%81%84%E3%81%AE%E3%81%AF%E3%81%AA%E3%81%9C%E3%81%A7%E3%81%99%E3%81%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>コードファーストにも種類があり、この API はその種類ではないからです。この API は HTML を写します。書いた要素はそのまま出る要素で、レイアウトは CSS が担い、文字列をそのまま書けばテキストノードです。</p>\n<p>HTML とは別の名前を用意すると、それを覚え、描画がおかしいときは HTML へ読み替え、HTML と CSS が変わるたびに保守する必要が出ます。どの系譜に連なるのか、なぜ SwiftUI の系譜を採らなかったのかは\n<code>DESIGN.md</code> §4.1 にあります。</p>\n<h2 id=\"razor-ファイルを残せますか\"><code>.razor</code> ファイルを残せますか<a href=\"#razor-%E3%83%95%E3%82%A1%E3%82%A4%E3%83%AB%E3%82%92%E6%AE%8B%E3%81%9B%E3%81%BE%E3%81%99%E3%81%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>残せます。どちらの向きでも呼べます。<code>.razor</code> ファイルはこのコンポーネントを通常のタグとして書けますし、こちらからは <code>Component&lt;T&gt;()</code> で <code>.razor</code> コンポーネントを呼べます。</p>\n<p>制限は同一プロジェクトの場合だけです。<code>Component&lt;T&gt;()</code> は、同じプロジェクトで宣言された <code>.razor</code>\nの型を指定できません。ソースジェネレーターは互いの出力を見られないからです（<a href=\"/docs/ja/diagnostics#bcf3012\">BCF3012</a>）。参照プロジェクトにある同じコンポーネントは通常どおり解決します。<a href=\"/docs/ja/components-and-reuse#%E6%97%A2%E5%AD%98%E3%81%AE-razor-%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%82%84%E3%82%B5%E3%83%BC%E3%83%89%E3%83%91%E3%83%BC%E3%83%86%E3%82%A3%E3%81%AE%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%82%92%E5%91%BC%E3%81%B6\">コンポーネントと再利用</a>を読んでください。</p>\n<h2 id=\"mudblazor-や-radzen-などのコンポーネントライブラリと一緒に使えますか\">MudBlazor や Radzen などのコンポーネントライブラリと一緒に使えますか<a href=\"#mudblazor-%E3%82%84-radzen-%E3%81%AA%E3%81%A9%E3%81%AE%E3%82%B3%E3%83%B3%E3%83%9D%E3%83%BC%E3%83%8D%E3%83%B3%E3%83%88%E3%83%A9%E3%82%A4%E3%83%96%E3%83%A9%E3%83%AA%E3%81%A8%E4%B8%80%E7%B7%92%E3%81%AB%E4%BD%BF%E3%81%88%E3%81%BE%E3%81%99%E3%81%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>使えます。どれも参照アセンブリにある通常の Blazor コンポーネントで、<code>Component&lt;T&gt;()</code> はまさにその場合のためにあります。パラメーターは <code>.Param</code>、テンプレートは <code>.Template</code>、子の内容は角括弧です。</p>\n<h2 id=\"実行時のコストはどれくらいですか\">実行時のコストはどれくらいですか<a href=\"#%E5%AE%9F%E8%A1%8C%E6%99%82%E3%81%AE%E3%82%B3%E3%82%B9%E3%83%88%E3%81%AF%E3%81%A9%E3%82%8C%E3%81%8F%E3%82%89%E3%81%84%E3%81%A7%E3%81%99%E3%81%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>.razor</code> コンポーネントと変わりません。ジェネレーターが出すのは、シーケンス番号を静的に振った\n<code>RenderTreeBuilder</code> のメソッドで、これは Razor コンパイラが出すものと同じです。</p>\n<p>実行時の UI ツリーはなく、リフレクションもなく、式のコンパイルもありません。コンポーネントを書いた設計時の API は配布物に残りません。IL トリマーが削ります。</p>\n<h2 id=\"クラスが-partial-かつトップレベルでなければならないのはなぜですか\">クラスが <code>partial</code> かつトップレベルでなければならないのはなぜですか<a href=\"#%E3%82%AF%E3%83%A9%E3%82%B9%E3%81%8C-partial-%E3%81%8B%E3%81%A4%E3%83%88%E3%83%83%E3%83%97%E3%83%AC%E3%83%99%E3%83%AB%E3%81%A7%E3%81%AA%E3%81%91%E3%82%8C%E3%81%B0%E3%81%AA%E3%82%89%E3%81%AA%E3%81%84%E3%81%AE%E3%81%AF%E3%81%AA%E3%81%9C%E3%81%A7%E3%81%99%E3%81%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p><code>partial</code> なのは、ジェネレーターが描画をそのクラスへ書き込むからです（<a href=\"/docs/ja/diagnostics#bcf1001\">BCF1001</a>）。トップレベルなのは、入れ子のクラスを生成ファイル側で開き直すには、外側の型の宣言を型引数まで含めて書き直さねばならないからです（<a href=\"/docs/ja/diagnostics#bcf1005\">BCF1005</a>）。</p>\n<h2 id=\"body-の中で通常の-if-や-foreach-を書けないのはなぜですか\"><code>Body</code> の中で通常の <code>if</code> や <code>foreach</code> を書けないのはなぜですか<a href=\"#body-%E3%81%AE%E4%B8%AD%E3%81%A7%E9%80%9A%E5%B8%B8%E3%81%AE-if-%E3%82%84-foreach-%E3%82%92%E6%9B%B8%E3%81%91%E3%81%AA%E3%81%84%E3%81%AE%E3%81%AF%E3%81%AA%E3%81%9C%E3%81%A7%E3%81%99%E3%81%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>それぞれが専用のシーケンス空間を必要とするからです。このコンパイルの要点は、テンプレートのどの位置にもビルド時に番号が振られることです。<code>If</code> と <code>ForEach</code> は、その空間を明示した同じ制御構文です。</p>\n<p>ゲッターが返すのは1つの式で、その手前にローカル変数を置けます（<a href=\"/docs/ja/getting-started#%E3%82%B2%E3%83%83%E3%82%BF%E3%83%BC%E3%81%8C%E8%BF%94%E3%81%99%E3%81%AE%E3%81%AF1%E3%81%A4%E3%81%AE%E5%BC%8F\">はじめに</a>）。本体がどうしてもその形にならないなら、<code>RenderView</code> を手で書いてください。</p>\n<h2 id=\"foreach-がキーを要求するのはなぜですか\"><code>ForEach</code> がキーを要求するのはなぜですか<a href=\"#foreach-%E3%81%8C%E3%82%AD%E3%83%BC%E3%82%92%E8%A6%81%E6%B1%82%E3%81%99%E3%82%8B%E3%81%AE%E3%81%AF%E3%81%AA%E3%81%9C%E3%81%A7%E3%81%99%E3%81%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>位置で差分を取るリストは、並び替わった瞬間に別の要素の状態を使い回すからです。そしてそれは、利用者が入力の移動に気づくまで見えません。パラメーターに既定値はないので、リストは項目を識別するか、<code>key: null</code> と明示して代償を引き受けるかのどちらかです（<a href=\"/docs/ja/control-flow#%E3%82%AD%E3%83%BC%E3%82%92%E4%BD%BF%E3%82%8F%E3%81%AA%E3%81%84\">キーを使わない</a>）。</p>\n<h2 id=\"raw-は安全ですか\"><code>Raw</code> は安全ですか<a href=\"#raw-%E3%81%AF%E5%AE%89%E5%85%A8%E3%81%A7%E3%81%99%E3%81%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>信頼できる内容に限って安全です。エスケープせずに DOM へ書きます。Razor の <code>MarkupString</code> と同じです。利用者の入力や外部の応答を通してはいけません（<a href=\"/docs/ja/control-flow#raw\">Raw</a>）。</p>\n<h2 id=\"ビルドが止まったが-id-に見覚えがない\">ビルドが止まったが ID に見覚えがない<a href=\"#%E3%83%93%E3%83%AB%E3%83%89%E3%81%8C%E6%AD%A2%E3%81%BE%E3%81%A3%E3%81%9F%E3%81%8C-id-%E3%81%AB%E8%A6%8B%E8%A6%9A%E3%81%88%E3%81%8C%E3%81%AA%E3%81%84\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>どの診断も<a href=\"/docs/ja/diagnostics\">リファレンス</a>に項があり、そこに意味と、代わりに書くコードがあります。ビルドが ID を表示するので、そのページをその ID で検索してください。</p>\n<h2 id=\"書いたものと違う描画になったらどこを見ますか\">書いたものと違う描画になったら、どこを見ますか<a href=\"#%E6%9B%B8%E3%81%84%E3%81%9F%E3%82%82%E3%81%AE%E3%81%A8%E9%81%95%E3%81%86%E6%8F%8F%E7%94%BB%E3%81%AB%E3%81%AA%E3%81%A3%E3%81%9F%E3%82%89%E3%81%A9%E3%81%93%E3%82%92%E8%A6%8B%E3%81%BE%E3%81%99%E3%81%8B\" class=\"headlink\" aria-label=\"Permalink to this section\">#</a></h2>\n<p>それは、このコンパイラが防ぐために作られている事態です。まず診断を見てください。違うものを出す代わりに、翻訳できないことを報告する作りです。何も出ていないなら、書いた式と期待した HTML のあいだに差があります。その対応は<a href=\"/docs/ja/elements-and-decorations\">要素と装飾</a>に書いてあります。</p>\n"),
    ];

    /// <summary>One language's documents, in navigation order.</summary>
    public static ImmutableArray<DocEntry> ForLang(string lang) => ForLang(All, lang);

    /// <summary>The same, over a manifest given directly rather than this build's.</summary>
    public static ImmutableArray<DocEntry> ForLang(ImmutableArray<DocEntry> docs, string lang)
    {
        var builder = ImmutableArray.CreateBuilder<DocEntry>();
        foreach (var entry in docs)
        {
            if (string.Equals(entry.Lang, lang, StringComparison.Ordinal))
            {
                builder.Add(entry);
            }
        }

        return builder.ToImmutable();
    }

    /// <summary>One language's documents in one navigation group, in reading order.</summary>
    public static ImmutableArray<DocEntry> ForGroup(string lang, string group) =>
        ForGroup(All, lang, group);

    /// <summary>The same, over a manifest given directly rather than this build's.</summary>
    public static ImmutableArray<DocEntry> ForGroup(
        ImmutableArray<DocEntry> docs, string lang, string group)
    {
        var builder = ImmutableArray.CreateBuilder<DocEntry>();
        foreach (var entry in ForLang(docs, lang))
        {
            if (string.Equals(entry.Group, group, StringComparison.Ordinal))
            {
                builder.Add(entry);
            }
        }

        return builder.ToImmutable();
    }

    /// <summary>The groups one language actually has documents in, in navigation order.</summary>
    /// <remarks>A group with no document in this language is left out, so a translation
    /// that has not reached a group yet shows no empty heading.</remarks>
    public static ImmutableArray<string> GroupsFor(string lang) => GroupsFor(All, lang);

    /// <summary>The same, over a manifest given directly rather than this build's.</summary>
    public static ImmutableArray<string> GroupsFor(ImmutableArray<DocEntry> docs, string lang)
    {
        var builder = ImmutableArray.CreateBuilder<string>();
        foreach (string group in GroupOrder)
        {
            if (ForGroup(docs, lang, group).Length > 0)
            {
                builder.Add(group);
            }
        }

        return builder.ToImmutable();
    }

    /// <summary>What one language calls one navigation group.</summary>
    public static string GroupLabel(string lang, string group)
    {
        foreach (var heading in Shell(lang).Groups)
        {
            if (string.Equals(heading.Group, group, StringComparison.Ordinal))
            {
                return heading.Label;
            }
        }

        return group;
    }

    /// <summary>Finds a document by language and slug. Blazor route matching is
    /// case-insensitive, so the slug lookup must be too; the language comes from the route
    /// template rather than from the reader, so it is matched exactly.</summary>
    public static DocEntry? Find(string lang, string? slug) => Find(All, lang, slug);

    /// <summary>The same, over a manifest given directly rather than this build's.</summary>
    public static DocEntry? Find(ImmutableArray<DocEntry> docs, string lang, string? slug)
    {
        if (slug is null)
        {
            return null;
        }

        foreach (var entry in docs)
        {
            if (string.Equals(entry.Lang, lang, StringComparison.Ordinal) &&
                string.Equals(entry.Slug, slug, StringComparison.OrdinalIgnoreCase))
            {
                return entry;
            }
        }

        return null;
    }
}
